INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25758, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "也可以的意思", "primary_collocate": null, "pronunciation": "yì kě", "ipa": "i˥˩ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "走路去亦可，坐车去亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有红笔，用黑笔亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，改天再去亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你累了，先休息亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现金不够，刷卡亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜不辣，加点辣椒亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家很近，晚上来亦可。", "target_word": "亦可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买不到票，坐下一班亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不会写汉字，用拼音亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不想出门，在家看书亦可。", "target_word": "亦可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "也可以，另一选择同样行得通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8690e496-04c6-47d2-9989-640dbeda1136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。yì kě 表示也可以，另一选择同样行得通。"}, {"text": "一颗", "is_correct": false, "explanation": "yī kē 两个音节的声调都不同，意思是一粒。"}, {"text": "议课", "is_correct": false, "explanation": "yì kè 第二个音节声调不同（kè 与 kě），意思是讨论课堂教学。"}, {"text": "一刻", "is_correct": false, "explanation": "yí kè 两个音节的声调都不同，意思是十五分钟。"}], "explanations": {"亦可": "正确答案。yì kě 表示也可以，另一选择同样行得通。", "一颗": "yī kē 两个音节的声调都不同，意思是一粒。", "议课": "yì kè 第二个音节声调不同（kè 与 kě），意思是讨论课堂教学。", "一刻": "yí kè 两个音节的声调都不同，意思是十五分钟。"}, "sentence_index": null, "correct_answer": "亦可"}, "level_3": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。与后句“坐车去亦可”并列，表示走路去也可以。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示强制，与后句“坐车去亦可”的并列选择冲突。"}, {"text": "只能", "is_correct": false, "explanation": "语义：“只能”表示唯一选择，与后句的另一选择冲突。"}, {"text": "虽然", "is_correct": false, "explanation": "语法：“虽然”是连词，要放在小句开头，不能放在句末，“走路去虽然”不成句。"}], "explanations": {"亦可": "正确答案。与后句“坐车去亦可”并列，表示走路去也可以。", "必须": "语义：“必须”表示强制，与后句“坐车去亦可”的并列选择冲突。", "只能": "语义：“只能”表示唯一选择，与后句的另一选择冲突。", "虽然": "语法：“虽然”是连词，要放在小句开头，不能放在句末，“走路去虽然”不成句。"}, "sentence_index": 0, "correct_answer": "亦可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢游泳，亦可喜欢跑步。", "explanation": "这里应该用〈也〉。亦可表示另一做法同样可以，不能用于表达爱好。"}, {"text": "他亦可是老师，已经在学校教了十年书。", "explanation": "这里应该用〈也〉。亦可表示可能或另一情况也成立，不用来陈述已经确定的身份；“已经教了十年书”说明他确实是老师，应说“也是老师”。"}, {"text": "他已经跑完了全程，亦可很累。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不能用来描述已经发生的状态；“已经跑完了全程”是事实，应说“也很累”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亦可", "is_correct": true, "explanation": "正确答案。表示晚上来也可以，与前文“我家很近”相符。"}, {"text": "务必", "is_correct": false, "explanation": "语义：“务必”表示一定要，与“也可以”的许可之意冲突。"}, {"text": "应当", "is_correct": false, "explanation": "搭配：“应当”后面需要动词或小句，句末单用不通顺。"}, {"text": "不宜", "is_correct": false, "explanation": "语义：“不宜”表示不适合，与前文“我家很近”的便利语境冲突。"}], "explanations": {"亦可": "正确答案。表示晚上来也可以，与前文“我家很近”相符。", "务必": "语义：“务必”表示一定要，与“也可以”的许可之意冲突。", "应当": "搭配：“应当”后面需要动词或小句，句末单用不通顺。", "不宜": "语义：“不宜”表示不适合，与前文“我家很近”的便利语境冲突。"}, "sentence_index": 6, "correct_answer": "亦可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩很好，亦可考上了重点中学。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不用于陈述已经发生的结果；“考上了重点中学”是事实，应说“也考上了重点中学”。"}, {"text": "这个方案我已经试过了，亦可很有效。", "explanation": "这里应该用〈也〉。亦可表示可能或另一情况也成立，不能用来说明已经确定的结果；“已经试过了”说明事情已经发生，应说“也很有效”。"}, {"text": "他跑得很快，亦可拿了第一名。", "explanation": "这里应该用〈也〉。亦可表示“也可以”，不用来说明已经发生的结果；“拿了第一名”是事实，应说“也拿了第一名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雨了，坐公交车去也亦可。", "corrected_sentence": "下雨了，坐公交车去亦可。", "error_description": "“也”与“亦可”意思重复，不能叠用，应只保留“亦可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天冷的时候，穿毛衣亦可了。", "corrected_sentence": "天冷的时候，穿毛衣亦可。", "error_description": "“亦可”表示“也可以”，后面不能加“了”，应说“穿毛衣亦可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
