INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容很慢，像卡住一样不动。", "primary_collocate": null, "pronunciation": "chí zhì", "ipa": "tʂʰɨ˧˥ tʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他今天的动作很迟滞。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的反应有些迟滞。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水迟滞，几乎不流动。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪后，路上的车流迟滞。", "target_word": "迟滞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝多了酒以后，他的思维变得迟滞。", "target_word": "迟滞", "complexity_tier": "T3", "furigana": "hē duō le jiǔ yǐhòu tā de sīwéi biàn de chízhì", "sentence_source": "generated"}, {"text": "天太冷，他的手指迟滞，扣不上扣子。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病后她的步子迟滞而沉重。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里没有一丝风，空气迟滞不动，让人透不过气。", "target_word": "迟滞", "complexity_tier": "T3", "furigana": "wū lǐ méi yǒu yì sī fēng kōngqì chízhì bú dòng ràng rén tòu bu guò qì", "sentence_source": "generated"}, {"text": "他思路迟滞，半天答不上来。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了，脚步越来越迟滞。", "target_word": "迟滞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容动作、反应、流动缓慢呆滞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8690e496-04c6-47d2-9989-640dbeda1136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迟滞", "is_correct": true, "explanation": "正确：「迟滞」形容动作缓慢、不灵活，只有它能填入。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」形容高度，不用来形容动作的快慢，「动作很高」说法不通。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：「厚」形容物体的厚度，不能修饰动作。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人的体形，不能用来形容动作。"}], "explanations": {"迟滞": "正确：「迟滞」形容动作缓慢、不灵活，只有它能填入。", "高": "搭配：「高」形容高度，不用来形容动作的快慢，「动作很高」说法不通。", "厚": "搭配：「厚」形容物体的厚度，不能修饰动作。", "瘦": "体貌：「瘦」形容人的体形，不能用来形容动作。"}, "sentence_index": 0, "correct_answer": "迟滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很迟滞，不够鲜艳。", "explanation": "这里应该用〈暗淡〉。迟滞形容动作、反应、流动缓慢，不形容颜色；颜色不鲜艳要说暗淡。"}, {"text": "他性格很迟滞，不爱说话。", "explanation": "这里应该用〈沉闷〉。性格要说沉闷；迟滞用于形容动作、进展缓慢，不描述性格。"}, {"text": "他说话的音量很迟滞，大家都听不清。", "explanation": "这里应该用〈微弱〉。声音的大小要说微弱；迟滞形容动作、反应缓慢，不用于描述音量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迟滞", "is_correct": true, "explanation": "正确：步子缓慢停滞，与「沉重」一起描写病后的样子。"}, {"text": "轻盈", "is_correct": false, "explanation": "语义：「轻盈」与「沉重」意思相反，句中并列的说法矛盾。"}, {"text": "利落", "is_correct": false, "explanation": "语义：「利落」形容动作干脆快捷，与「而沉重」矛盾。"}, {"text": "蓬松", "is_correct": false, "explanation": "搭配：「蓬松」形容松软、膨起的东西，不能形容步子。"}], "explanations": {"迟滞": "正确：步子缓慢停滞，与「沉重」一起描写病后的样子。", "轻盈": "语义：「轻盈」与「沉重」意思相反，句中并列的说法矛盾。", "利落": "语义：「利落」形容动作干脆快捷，与「而沉重」矛盾。", "蓬松": "搭配：「蓬松」形容松软、膨起的东西，不能形容步子。"}, "sentence_index": 6, "correct_answer": "迟滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布摸起来很迟滞。", "explanation": "这里应该用〈粗糙〉。迟滞形容动作、反应缓慢，不描述手感；布摸起来不光滑要说粗糙。"}, {"text": "他对疼痛很迟滞。", "explanation": "这里应该用〈麻木〉。对疼痛失去感觉要说麻木；迟滞不表示感觉的丧失。"}, {"text": "他的笑容很迟滞，看上去不太自然。", "explanation": "这里应该用〈僵硬〉。笑容不自然要说僵硬；迟滞形容动作缓慢，不用于描述笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天他的反应比以前最迟滞了。", "corrected_sentence": "这几天他的反应比以前更迟滞了。", "error_description": "「比」字句中表示程度要用「更」，不能用「最」，应说「比以前更迟滞了」；「比以前最迟滞」母语者会立刻觉得不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病后，她迟滞地的步子很沉重。", "corrected_sentence": "病后，她迟滞的步子很沉重。", "error_description": "「迟滞」作定语修饰名词时用「的」，不用「地」（「地」用于修饰动词），应说「迟滞的步子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
