INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "气体或气味慢慢散开，跑到空气里不见了。", "primary_collocate": null, "pronunciation": "yì sàn", "ipa": "i˥˩ san˥˩", "syllable_count": 2, "sentences": [{"text": "煤气泄漏后，气体会慢慢逸散到空气中。", "target_word": "逸散", "complexity_tier": "T3", "furigana": "yì sàn", "sentence_source": "generated"}, {"text": "香水瓶开着，香味都逸散了。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤的香气从锅盖缝里逸散出来。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗，房间里的烟味慢慢逸散。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽水没盖好，里面的二氧化碳会逸散到空气中。", "target_word": "逸散", "complexity_tier": "T3", "furigana": "yì sàn", "sentence_source": "generated"}, {"text": "臭味逸散以后，房间又干净了。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盖子盖紧，别让香气逸散。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，花香就逸散了。", "target_word": "逸散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽油的味道会慢慢逸散，车库要常通风。", "target_word": "逸散", "complexity_tier": "T3", "furigana": "yì sàn", "sentence_source": "generated"}, {"text": "冰箱门开太久，冷气都逸散了。", "target_word": "逸散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逸散了", "label": "体标"}, {"form": "逸散过", "label": "体标"}], "register": "书面", "sense_fingerprint": "气体、气味慢慢散进空气里消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8690e496-04c6-47d2-9989-640dbeda1136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逸散", "is_correct": true, "explanation": "正确：气体慢慢散进空气中，正是「逸散」，符合句意。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：气体不会凝固，凝固说的是液体变成固体。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：气体不会被冻结，冻结用于液体或水分变硬。"}, {"text": "熔化", "is_correct": false, "explanation": "搭配：熔化用于固体受热变成液体，不说气体熔化到空气中。"}], "explanations": {"逸散": "正确：气体慢慢散进空气中，正是「逸散」，符合句意。", "凝固": "语义：气体不会凝固，凝固说的是液体变成固体。", "冻结": "语义：气体不会被冻结，冻结用于液体或水分变硬。", "熔化": "搭配：熔化用于固体受热变成液体，不说气体熔化到空气中。"}, "sentence_index": 0, "correct_answer": "逸散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泥沙慢慢逸散到杯底。", "explanation": "这里应该用〈沉淀〉。「逸散」只用于气体、气味，泥沙下沉要说沉淀。"}, {"text": "冰块在阳光下慢慢逸散。", "explanation": "这里应该用〈融化〉。「逸散」用于气体、气味，冰块变成水要说融化。"}, {"text": "木炭在火里慢慢逸散。", "explanation": "这里应该用〈燃烧〉。「逸散」指气体、气味散开，木炭烧起来要说燃烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逸散", "is_correct": true, "explanation": "正确：香气散出去，正是「逸散」，符合句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：香气是无形的，不能切割。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：香气不会倒塌，句意说不通。"}, {"text": "断裂", "is_correct": false, "explanation": "语义：香气不会断裂，断裂说的是物体折断。"}], "explanations": {"逸散": "正确：香气散出去，正是「逸散」，符合句意。", "切割": "搭配：香气是无形的，不能切割。", "倒塌": "语义：香气不会倒塌，句意说不通。", "断裂": "语义：香气不会断裂，断裂说的是物体折断。"}, "sentence_index": 6, "correct_answer": "逸散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火山逸散出了滚烫的岩浆。", "explanation": "这里应该用〈迸发〉。「逸散」指气体、气味慢慢散开，岩浆从火山喷涌而出要说迸发。"}, {"text": "水蒸气遇冷逸散成了小水珠。", "explanation": "这里应该用〈凝结〉。水蒸气遇冷变成水珠是凝结，「逸散」说的是散开消失。"}, {"text": "树叶逸散了一地。", "explanation": "这里应该用〈散落〉。「逸散」只用于气体、气味，树叶散落在地上要说散落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "泄漏的煤气很逸散到空气中。", "corrected_sentence": "泄漏的煤气慢慢逸散到空气中。", "error_description": "程度副词错误：「很」不能修饰动词「逸散」，此处应用表示方式的「慢慢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "香水的味道很逸散到屋子里。", "corrected_sentence": "香水的味道慢慢逸散到屋子里。", "error_description": "程度副词错误：「很」不能直接修饰动词「逸散」，此处应用表示方式的「慢慢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
