INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体上的小洞或窟窿。", "primary_collocate": null, "pronunciation": "kǒng", "ipa": "kʰʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "鞋子的底部有一个孔，下雨时会进水。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用针在布上扎了一个孔。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯盖上有一个孔，可以放吸管。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子中间留了一个孔，电线可以穿过去。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球上有个孔，所以慢慢变小了。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的孔很小，看不到外面。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头有一个孔，像一只眼睛。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活页本的边上有一排孔，方便把纸夹进去。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在木头上钻了一个孔，再放进螺丝。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶盖的孔太小，水倒得很慢。", "target_word": "孔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小孔", "label": "复合词"}, {"form": "针孔", "label": "复合词"}, {"form": "气孔", "label": "复合词"}, {"form": "孔洞", "label": "复合词"}], "register": "中性", "sense_fingerprint": "东西上面穿通的小洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38096432-dacc-4bd4-bbc5-445f189b8c2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25770, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔 kǒng（第三声）意思是小洞、窟窿。"}, {"text": "空", "is_correct": false, "explanation": "kōng（第一声）与 kǒng（第三声）声调不同，意思是空，不是小洞。"}, {"text": "控", "is_correct": false, "explanation": "kòng（第四声）与 kǒng（第三声）声调不同，意思是控制。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 kǒng 仅声母不同（g 与 k），意思是拱起。"}], "explanations": {"孔": "孔 kǒng（第三声）意思是小洞、窟窿。", "空": "kōng（第一声）与 kǒng（第三声）声调不同，意思是空，不是小洞。", "控": "kòng（第四声）与 kǒng（第三声）声调不同，意思是控制。", "拱": "gǒng（第三声）与 kǒng 仅声母不同（g 与 k），意思是拱起。"}, "sentence_index": null, "correct_answer": "孔"}, "level_3": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔指东西上穿通的小洞，「鞋子的底部有一个孔，下雨时会进水」正是这个意思。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不会出现在鞋子底部，句意不通。"}, {"text": "按钮", "is_correct": false, "explanation": "搭配：「下雨时会进水」说的是洞口的功能，按钮与进水的语境不搭配。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是用来照看的器物，鞋子底部不会有镜子，句意不通。"}], "explanations": {"孔": "孔指东西上穿通的小洞，「鞋子的底部有一个孔，下雨时会进水」正是这个意思。", "窗户": "语义：窗户是墙上的开口，不会出现在鞋子底部，句意不通。", "按钮": "搭配：「下雨时会进水」说的是洞口的功能，按钮与进水的语境不搭配。", "镜子": "语义：镜子是用来照看的器物，鞋子底部不会有镜子，句意不通。"}, "sentence_index": 0, "correct_answer": "孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子中间留了一块孔，电线可以穿过去。", "explanation": "这里的量词「块」用于块状的东西，孔应该用「个」，这是量词误用。"}, {"text": "桌子中间的孔很甜，我想吃一口。", "explanation": "孔是物体上的洞，没有甜不甜的味道，不能拿来吃，搭配不当。"}, {"text": "他把桌子中间的孔买回了家。", "explanation": "孔是物体上的洞，是空缺而不是可以买回家的东西，这里把它当成了具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25770, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔 kǒng（第三声）意思是小洞、窟窿。"}, {"text": "巩", "is_correct": false, "explanation": "巩 gǒng（第三声）与 kǒng 仅声母不同（g 与 k），意思是巩固。"}, {"text": "桶", "is_correct": false, "explanation": "桶 tǒng（第三声）与 kǒng 仅声母不同（t 与 k），意思是水桶。"}, {"text": "口", "is_correct": false, "explanation": "kǒu 与 kǒng 韵母不同（ou 与 ong），意思是嘴巴或口子。"}], "explanations": {"孔": "孔 kǒng（第三声）意思是小洞、窟窿。", "巩": "巩 gǒng（第三声）与 kǒng 仅声母不同（g 与 k），意思是巩固。", "桶": "桶 tǒng（第三声）与 kǒng 仅声母不同（t 与 k），意思是水桶。", "口": "kǒu 与 kǒng 韵母不同（ou 与 ong），意思是嘴巴或口子。"}, "sentence_index": null, "correct_answer": "孔"}, "level_3": {"options": [{"text": "孔", "is_correct": true, "explanation": "孔指物体上的小洞，「这块石头有一个孔，像一只眼睛」正是这个意思。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是石头上的洞，「有一个名字，像一只眼睛」句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「有一个颜色」不能这样说，颜色不作为可数的部分出现在石头上。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是穿在脚上的物品，与石头上的洞及比喻无关，句意不通。"}], "explanations": {"孔": "孔指物体上的小洞，「这块石头有一个孔，像一只眼睛」正是这个意思。", "名字": "语义：名字是称呼，不是石头上的洞，「有一个名字，像一只眼睛」句意不通。", "颜色": "搭配：「有一个颜色」不能这样说，颜色不作为可数的部分出现在石头上。", "皮鞋": "语义：皮鞋是穿在脚上的物品，与石头上的洞及比喻无关，句意不通。"}, "sentence_index": 6, "correct_answer": "孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的孔很喜欢跑步，每天都去操场。", "explanation": "孔是物体上的洞，不会喜欢跑步，这里把它当成了有意愿的人，搭配不当。"}, {"text": "老师让我们把瓶盖的孔背下来。", "explanation": "「背」用于课文、单词等需要记住的内容，孔不能被背，这里搭配不当。"}, {"text": "瓶盖的孔很好吃，我每天都想咬一口。", "explanation": "「好吃」形容食物的味道，孔不是食物，这里把它当成了食物来用，搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "瓶子的盖子上有一颗孔，方便倒水。", "corrected_sentence": "瓶子的盖子上有一个孔，方便倒水。", "error_description": "「孔」的量词应为「个」。「颗」用于颗粒状的小东西，这里误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这个孔大钻了一点。", "corrected_sentence": "我把这个孔钻大了一点。", "error_description": "表示结果的补语「大」应放在动词「钻」之后，说「钻大了」。「大钻了」是补语位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
