INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "温度和湿度放在一起说。", "primary_collocate": null, "pronunciation": "wēn shī dù", "ipa": "wən˥ ʂɨ˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "天气预报会告诉我们明天的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室要记录每天的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "葡萄酒需要放在温湿度稳定的地方。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的温湿度和城市很不一样。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调可以把房间的温湿度调到合适的范围。", "target_word": "温湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物对温湿度的变化很敏感。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的温湿度正好，很适合出去玩。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先看一下机房的温湿度再进去。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶叶放久了，温湿度不对就会发霉。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温湿度太高的时候，衣服很难干。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "温湿度计", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把温度和湿度合在一起说的日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38096432-dacc-4bd4-bbc5-445f189b8c2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "票价", "is_correct": false, "explanation": "语义：天气预报不报告票价，两者无关。"}, {"text": "血压", "is_correct": false, "explanation": "语义：血压是人的指标，不是天气预报的内容。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：天气预报会告诉我们明天的温湿度，符合语境。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“天气预报会告诉我们”后不接“明天的生日”。"}], "explanations": {"票价": "语义：天气预报不报告票价，两者无关。", "血压": "语义：血压是人的指标，不是天气预报的内容。", "温湿度": "正确：天气预报会告诉我们明天的温湿度，符合语境。", "生日": "搭配：“天气预报会告诉我们”后不接“明天的生日”。"}, "sentence_index": 0, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的温湿度是三十度，很热。", "explanation": "这里应该用〈气温〉。温湿度是温度与湿度的合称，不能单指一个温度数值。"}, {"text": "他发烧了，温湿度很高。", "explanation": "这里应该用〈体温〉。温湿度指环境的温度与湿度，不用来说人的体温。"}, {"text": "这间屋子的温湿度是百分之六十，衣服一直干不了。", "explanation": "这里应该用〈湿度〉。温湿度是合称，不单指湿度的数值，不能说“是百分之六十”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业不是天气，“春天的作业正好”不合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与天气无关，“正好，适合出去玩”无法解释。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“春天的手机正好”不成立，“正好”不搭配手机。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：春天的温湿度正好，很适合出去玩，符合语境。"}], "explanations": {"作业": "语义：作业不是天气，“春天的作业正好”不合语境。", "年龄": "语义：年龄与天气无关，“正好，适合出去玩”无法解释。", "手机": "搭配：“春天的手机正好”不成立，“正好”不搭配手机。", "温湿度": "正确：春天的温湿度正好，很适合出去玩，符合语境。"}, "sentence_index": 6, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的温湿度是二十五度，很舒服。", "explanation": "这里应该用〈室温〉。温湿度是合称，不单指室内温度。"}, {"text": "我把温湿度当成一件衣服穿在身上。", "explanation": "温湿度指环境的温度与湿度，不是衣物，此处不能当成实物。"}, {"text": "这杯茶的温湿度很香。", "explanation": "这里应该用〈味道〉。温湿度指温度与湿度，不能用来形容茶的香气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里挂着一个温湿度。", "corrected_sentence": "车间里挂着一个温湿度计。", "error_description": "应为“温湿度计”。“温湿度”是温度与湿度的合称，不是仪器，挂的仪器要说“温湿度计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空调把房间的温湿度打开了。", "corrected_sentence": "空调把房间的温湿度调好了。", "error_description": "搭配错误：“温湿度”是数值状态，只能“调”“控制”，不能“打开”，应说“把温湿度调好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
