INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所达到的高低、轻重、深浅的水平。", "primary_collocate": null, "pronunciation": "chéng dù", "ipa": "ʈʂʰɤŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "天气冷到了让人受不了的程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说病情到了什么程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的难易程度差别很大。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气的程度超过了我的想象。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢这家店，但还没到天天去的程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习到一定程度，你就会觉得容易。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛到了很紧张的程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里空气污染的程度越来越低。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累到了站不住的程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请说说你对这件事满意到什么程度。", "target_word": "程度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "事物发展或变化所达到的高低、轻重、深浅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "正确。“程度”指事情达到的高低、轻重，符合“冷到让人受不了的程度”。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，与冷的程度无关。"}, {"text": "角度", "is_correct": false, "explanation": "搭配：“角度”多与看问题搭配，不用来形容冷的程度。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，与“冷到让人受不了”的意思不合。"}], "explanations": {"程度": "正确。“程度”指事情达到的高低、轻重，符合“冷到让人受不了的程度”。", "速度": "语义：“速度”指快慢，与冷的程度无关。", "角度": "搭配：“角度”多与看问题搭配，不用来形容冷的程度。", "长度": "语义：“长度”指长短，与“冷到让人受不了”的意思不合。"}, "sentence_index": 0, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的程度超过了两米。", "explanation": "这里应该用〈深度〉。“深度”指河、井等纵向的距离，“程度”不表示可以量出的尺寸。"}, {"text": "这个月他加班的程度很多。", "explanation": "这里应该用〈次数〉。“程度”说的是高低深浅，不能用来计算重复的次数。"}, {"text": "他的程度超过了六十岁。", "explanation": "这里应该用〈年龄〉。“年龄”指人的岁数，“程度”不用于表示年岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "正确。“到了很紧张的程度”表示情况达到的程度。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“很紧张”来形容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指轻重的数值，与“很紧张”不搭。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“数字”不用“很紧张”修饰，搭配不当。"}], "explanations": {"程度": "正确。“到了很紧张的程度”表示情况达到的程度。", "颜色": "语义：“颜色”不能用“很紧张”来形容。", "体重": "语义：“体重”指轻重的数值，与“很紧张”不搭。", "数字": "搭配：“数字”不用“很紧张”修饰，搭配不当。"}, "sentence_index": 6, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼的程度有三十层。", "explanation": "这里应该用〈高度〉。“高度”指楼、山等从下到上的距离，“程度”不表示可以量出的尺寸。"}, {"text": "这次活动的参加程度很多。", "explanation": "这里应该用〈人数〉。“人数”是人的总数，“程度”不表示人数多少。"}, {"text": "我家到学校的程度很远。", "explanation": "这里应该用〈距离〉。“距离”指两地之间的空间间隔，“程度”不表示远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药对病情有一本程度的缓解。", "corrected_sentence": "这种药对病情有一定程度的缓解。", "error_description": "量词错误：“程度”前不能用“本”（那是书册的量词），应说“一定程度的缓解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的伤势需要手术的程度。", "corrected_sentence": "他的伤势到了需要手术的程度。", "error_description": "“到了……的程度”是固定格式，表示达到的状况。漏掉“到了”句子不通。正确说法是「他的伤势到了需要手术的程度。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
