INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25786, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "手里拿着东西。", "primary_collocate": null, "pronunciation": "shǒu wò", "ipa": "ʂou˨˩˦ wo˥˩", "syllable_count": 2, "sentences": [{"text": "他手握一本书坐在窗边。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩手握气球站在路边。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸手握一杯热茶看报纸。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她手握着手机，等朋友的电话。", "target_word": "手握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师手握粉笔在黑板上写字。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他手握一张车票走进车站。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟手握玩具枪跑来跑去。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师手握菜刀，很快切好了菜。", "target_word": "手握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客手握地图四处找路。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老奶奶手握一把伞，站在雨中。", "target_word": "手握", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "手握着", "label": "持续体"}, {"form": "手握过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "手里拿着某样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e69618b-7a06-4ac6-b69c-32dc57bf871e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手握", "is_correct": true, "explanation": "正确。手握一本书指手里拿着一本书，符合句意。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚碰撞，与手里拿着书的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱，与拿着书无关。"}, {"text": "吻", "is_correct": false, "explanation": "搭配：“吻”不能带“书”作宾语，搭配不当。"}], "explanations": {"手握": "正确。手握一本书指手里拿着一本书，符合句意。", "踢": "语义：“踢”指用脚碰撞，与手里拿着书的意思不符。", "唱": "语义：“唱”指演唱，与拿着书无关。", "吻": "搭配：“吻”不能带“书”作宾语，搭配不当。"}, "sentence_index": 0, "correct_answer": "手握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人手握着墙，慢慢走出了门。", "explanation": "这里应该用〈扶〉。手握指用手握住物品，扶墙走路要用〈扶〉。"}, {"text": "妈妈手握着孩子，哄他睡觉。", "explanation": "这里应该用〈搂〉。手握指用手握住物品，搂着孩子睡觉要用〈搂〉。"}, {"text": "他手握着水，慢慢喝下去。", "explanation": "这里应该用〈捧〉。手握指用手握住物品，水无法被握住，捧水要用〈捧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ad1b798-40b2-4ee8-afbd-c476b4f32db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手握", "is_correct": true, "explanation": "正确。手握玩具枪指手里拿着玩具枪，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，与拿着玩具枪无关。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“玩具枪”。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能带“玩具枪”作宾语，搭配不当。"}], "explanations": {"手握": "正确。手握玩具枪指手里拿着玩具枪，符合句意。", "煮": "语义：“煮”指烹饪，与拿着玩具枪无关。", "笑": "配价：“笑”是不及物动词，不能带宾语“玩具枪”。", "哭": "搭配：“哭”不能带“玩具枪”作宾语，搭配不当。"}, "sentence_index": 6, "correct_answer": "手握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手握着耳朵，不想听见吵闹。", "explanation": "这里应该用〈捂〉。手握指用手握住物品，捂耳朵要用〈捂〉。"}, {"text": "妈妈手握着孩子的背，轻声哄他。", "explanation": "这里应该用〈拍〉。手握指用手握住物品，轻拍背要用〈拍〉。"}, {"text": "他手握着后背，痒得厉害。", "explanation": "这里应该用〈挠〉。手握指用手握住物品，挠后背要用〈挠〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ad1b798-40b2-4ee8-afbd-c476b4f32db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈了手握着一个苹果，走进厨房。", "corrected_sentence": "妈妈手握着一个苹果，走进厨房。", "error_description": "“了”的位置错误：“了”不能放在动词“手握”之前；此处表示持续状态，应说“手握着一个苹果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ad1b798-40b2-4ee8-afbd-c476b4f32db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务员把手握托盘，走过来。", "corrected_sentence": "服务员手握托盘，走过来。", "error_description": "“把”误加：“手握”后直接带宾语“托盘”，不能再用“把”引出“手”作处置对象，应说“手握托盘”，去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ad1b798-40b2-4ee8-afbd-c476b4f32db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
