INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嗜热菌是一种喜欢在很热的地方生活的很小很小的生物。", "primary_collocate": null, "pronunciation": "shì rè jūn", "ipa": "ʂɻ̩˥˩ ɻɤ˥˩ tɕyn˥˥", "syllable_count": 3, "sentences": [{"text": "嗜热菌是一种喜欢热地方的小生物。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太热时，别的小生物会死，嗜热菌却活得很好。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热泉里很热，嗜热菌就住在那里。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌太小了，眼睛看不见。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷的地方不适合嗜热菌生活。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，嗜热菌最喜欢很热的水。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山旁边很热，那里有嗜热菌。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌不怕热，我们人却受不了。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，嗜热菌是很小很小的生物。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把水加热到很高，嗜热菌还是能活着。", "target_word": "嗜热菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "嗜熱菌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "喜欢住在很热地方的极小生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de1e997-cade-4800-bbaf-67fd2a0fa879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗜热菌", "is_correct": true, "explanation": "正确：嗜热菌是喜欢热地方的很小的生物，与句意一致。"}, {"text": "嗜冷菌", "is_correct": false, "explanation": "语义：嗜冷菌喜欢寒冷，与“喜欢热地方”正相反。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大，与“很小的生物”不符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“喜欢”需要有生命的主语，石头不能充当。"}], "explanations": {"嗜热菌": "正确：嗜热菌是喜欢热地方的很小的生物，与句意一致。", "嗜冷菌": "语义：嗜冷菌喜欢寒冷，与“喜欢热地方”正相反。", "大象": "体貌：大象体型庞大，与“很小的生物”不符。", "石头": "配价：“喜欢”需要有生命的主语，石头不能充当。"}, "sentence_index": 0, "correct_answer": "嗜热菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嗜热菌喜欢在零度左右的冰水里生活。", "explanation": "这里应该用〈嗜冷菌〉。嗜热菌喜欢热地方，在零度左右的冰水里生活要说嗜冷菌。"}, {"text": "嗜热菌的个头比大象还大，肉眼一看就能看见。", "explanation": "这里应该用〈大型动物〉。嗜热菌是很小很小的生物，肉眼看不见，不能说它的个头比大象还大。"}, {"text": "嗜热菌喜欢在阴暗潮湿的角落里生长。", "explanation": "这里应该用〈霉菌〉。霉菌常在阴暗潮湿的角落里生长；嗜热菌喜欢热地方，不适合这样的环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗜热菌", "is_correct": true, "explanation": "正确：嗜热菌能在很热的地方生活，与“火山旁边很热”相合。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：火山旁边很热，不会有冰川。"}, {"text": "企鹅", "is_correct": false, "explanation": "语义：企鹅怕热，不会出现在火山旁边的高温处。"}, {"text": "雪糕", "is_correct": false, "explanation": "语义：火山旁边很热，雪糕会融化，不会出现在那里，与句意不合。"}], "explanations": {"嗜热菌": "正确：嗜热菌能在很热的地方生活，与“火山旁边很热”相合。", "冰川": "语义：火山旁边很热，不会有冰川。", "企鹅": "语义：企鹅怕热，不会出现在火山旁边的高温处。", "雪糕": "语义：火山旁边很热，雪糕会融化，不会出现在那里，与句意不合。"}, "sentence_index": 6, "correct_answer": "嗜热菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嗜热菌在零下几十度的冰层里依然活跃。", "explanation": "这里应该用〈耐寒菌〉。嗜热菌喜欢高温，在零下几十度的冰层里活跃要说耐寒菌。"}, {"text": "温泉边的石头缝里，嗜热菌长出了一棵小草。", "explanation": "这里应该用〈植物〉。嗜热菌是微生物，不会长出小草；长草的是植物。"}, {"text": "嗜热菌在高温下会被杀死，所以煮沸能消毒。", "explanation": "这里应该用〈病原菌〉。嗜热菌喜欢高温，不会被煮沸杀死；多数病原菌不耐高温，煮沸可以杀死。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这头嗜热菌喜欢住在很热的地方。", "corrected_sentence": "这种嗜热菌喜欢住在很热的地方。", "error_description": "“嗜热菌”是微生物，量词应用“种”，不能用“头”（“头”多用于牛、猪等大牲畜）。应改为“这种嗜热菌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多嗜热菌们喜欢住在热泉里。", "corrected_sentence": "很多嗜热菌喜欢住在热泉里。", "error_description": "“们”多用于指人的名词，一般不加在“嗜热菌”这类微生物名词后；“很多”已表示复数，应说“很多嗜热菌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
