INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25794, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容一个人或事情很有精神，动来动去。", "primary_collocate": null, "pronunciation": "huó yuè", "ipa": "xwo˧˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子很活跃，一刻也不想坐着。", "target_word": "活跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗很活跃，在院子里跑来跑去。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的小儿子活跃得一分钟也停不下来。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟特别活跃，一会儿跳一会儿跑。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们很活跃，在操场上玩得很开心。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完早饭，宝宝变得特别活跃。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只小猴子又活跃又可爱。", "target_word": "活跃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是个活跃的小男孩，一点也不怕生。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼在水里很活跃，游来游去。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡了一觉以后，孩子又变得活跃了。", "target_word": "活跃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "活跃了", "label": "体标"}, {"form": "活跃度", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人或动物精力充沛、爱动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38096432-dacc-4bd4-bbc5-445f189b8c2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活跃", "is_correct": true, "explanation": "“活跃”形容人精力充沛、爱动，与“一刻也不想坐着”相合，可以放入空缺。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与“一刻也不想坐着”的意思相反，搭配矛盾。"}, {"text": "沉稳", "is_correct": false, "explanation": "语义：“沉稳”指性格稳重，与“一刻也不想坐着”的状态相互矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能说明一个孩子是否爱动。"}], "explanations": {"活跃": "“活跃”形容人精力充沛、爱动，与“一刻也不想坐着”相合，可以放入空缺。", "安静": "语义：“安静”与“一刻也不想坐着”的意思相反，搭配矛盾。", "沉稳": "语义：“沉稳”指性格稳重，与“一刻也不想坐着”的状态相互矛盾。", "矮小": "体貌：“矮小”形容身材，不能说明一个孩子是否爱动。"}, "sentence_index": 0, "correct_answer": "活跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "拿到礼物后，他心情很活跃。", "explanation": "这里应该用〈兴奋〉。“活跃”形容人的精力或行动，描述心情要说“兴奋”。"}, {"text": "这张桌子很活跃，每天都在搬来搬去。", "explanation": "这里不能用“活跃”形容桌子。“活跃”只用于人或动物，表示精力充沛、爱动。"}, {"text": "这个句子很活跃，读起来很有精神。", "explanation": "“活跃”形容人或动物，不用来形容句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活跃", "is_correct": true, "explanation": "“活跃”形容人或动物爱动、精力充沛，与“又可爱”相合，可以放入空缺。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度或态度，与“可爱”的评价不搭。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”用于天气或物体，不能用来形容小猴子的性情。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：“苍老”形容年纪和外貌，与“小猴子”的身份矛盾。"}], "explanations": {"活跃": "“活跃”形容人或动物爱动、精力充沛，与“又可爱”相合，可以放入空缺。", "冰冷": "语义：“冰冷”形容温度或态度，与“可爱”的评价不搭。", "潮湿": "搭配：“潮湿”用于天气或物体，不能用来形容小猴子的性情。", "苍老": "体貌：“苍老”形容年纪和外貌，与“小猴子”的身份矛盾。"}, "sentence_index": 6, "correct_answer": "活跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很活跃地坐在椅子上，一动不动。", "explanation": "“活跃”形容爱动、精力充沛，与“一动不动”相互矛盾，搭配不通。"}, {"text": "这只杯子很活跃，装满了水。", "explanation": "“活跃”形容人或动物的行动，杯子不能用来形容。"}, {"text": "他的身高很活跃，有一米八。", "explanation": "“活跃”形容精力或行动，不用来形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们玩了一下午，还是活跃地很。", "corrected_sentence": "孩子们玩了一下午，还是活跃得很。", "error_description": "“活跃地很”不通：“地”用于修饰动词的状语，“很”不能接在带“地”的结构后面；“活跃”后面表示程度的补语要用“得”，应说“活跃得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小狗一出门就活跃起去了。", "corrected_sentence": "那只小狗一出门就活跃起来了。", "error_description": "趋向补语错误。“活跃起来”表示状态开始并持续，“起来”不能换成“起去”，应说“活跃起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
