INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一段范围。", "primary_collocate": null, "pronunciation": "qū jiān", "ipa": "tɕʰy˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这两站之间的区间很长。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速公路上有一段测速区间。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体重在这个区间内算健康。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区间的路正在修。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心跳一直在安全区间里。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的价格在合理区间内。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车在这个区间里开得很慢。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室内温度保持在舒适区间。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区间有五公里长。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里这一段区间没有手机信号。", "target_word": "区间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个区间", "label": "量词"}, {"form": "安全区间", "label": "复合"}, {"form": "區間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "区间：一段范围，如路段或安全、合理的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de1e997-cade-4800-bbaf-67fd2a0fa879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指一段路程或范围。"}, {"text": "期间", "is_correct": false, "explanation": "qī 与 qū 韵母不同（i 与 ü），意思是“期间”，指某段时期之内。"}, {"text": "其间", "is_correct": false, "explanation": "qí 与 qū 韵母不同，意思是“其间”，指那段时间或两者之中。"}, {"text": "去见", "is_correct": false, "explanation": "qù 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“去见”，指前往会见。"}, {"text": "取件", "is_correct": false, "explanation": "qǔ 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“取件”，指领取物品。"}], "explanations": {"区间": "正确：区间指一段路程或范围。", "期间": "qī 与 qū 韵母不同（i 与 ü），意思是“期间”，指某段时期之内。", "其间": "qí 与 qū 韵母不同，意思是“其间”，指那段时间或两者之中。", "去见": "qù 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“去见”，指前往会见。", "取件": "qǔ 与 qū 声调不同，jiàn 与 jiān 声调不同，意思是“取件”，指领取物品。"}, "sentence_index": null, "correct_answer": "区间"}, "level_3": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指一段路程，“两站之间的路段”可以说很长。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“很长”说距离或时间，不能用来形容心情。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：两站之间是路段，不会是一张桌子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有长短，两站之间不会是颜色。"}], "explanations": {"区间": "正确：区间指一段路程，“两站之间的路段”可以说很长。", "心情": "搭配：“很长”说距离或时间，不能用来形容心情。", "桌子": "语义：两站之间是路段，不会是一张桌子。", "颜色": "语义：颜色没有长短，两站之间不会是颜色。"}, "sentence_index": 0, "correct_answer": "区间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们就在区间见面吧。", "explanation": "这里应该用〈地点〉。区间指一段范围，不指具体的点；约在一个地方见面要说地点。"}, {"text": "这个区间能装十升水。", "explanation": "这里应该用〈容器〉。区间指一段路或范围，不能装东西；能装水的是容器。"}, {"text": "他坐在第三排的区间上。", "explanation": "这里应该用〈座位〉。区间指一段范围，不能用来指座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区间", "is_correct": true, "explanation": "正确：区间指一段路段，列车可以在其中行驶，与句意一致。"}, {"text": "房间", "is_correct": false, "explanation": "语义：列车不能在房间里行驶。"}, {"text": "医院", "is_correct": false, "explanation": "语义：列车不会在医院里行驶，与“开得很慢”不合。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“开”要求能让列车行驶的场所，书包不能充当。"}], "explanations": {"区间": "正确：区间指一段路段，列车可以在其中行驶，与句意一致。", "房间": "语义：列车不能在房间里行驶。", "医院": "语义：列车不会在医院里行驶，与“开得很慢”不合。", "书包": "配价：“开”要求能让列车行驶的场所，书包不能充当。"}, "sentence_index": 6, "correct_answer": "区间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一段区间讲的是历史故事。", "explanation": "这里应该用〈段落〉。区间指路段或某种范围，不用来指文章的段落。"}, {"text": "我把区间放在桌子上了。", "explanation": "这里应该用〈书包〉。区间指一段路或范围，不是东西，不能拿起来放在桌子上。"}, {"text": "这篇文章的区间很长，读起来很累。", "explanation": "这里应该用〈篇幅〉。区间指一段范围，形容文章长短要用篇幅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这段路分成了几张区间。", "corrected_sentence": "我们把这段路分成了几个区间。", "error_description": "“区间”指一段范围，是抽象概念，量词应用“个”；“张”用于平面的东西，不能用来数区间。应改为“几个区间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张区间的路很窄。", "corrected_sentence": "这段区间的路很窄。", "error_description": "“区间”指一段路或范围，量词应用“段”；“张”用于平面的东西，不能用来数区间。应改为“这段区间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
