INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方，那里的工作人员会一直看着各种设备，监控有没有危险发生。", "primary_collocate": null, "pronunciation": "jiān cè zhōng xīn", "ipa": "tɕjɛn˥˥ tsʰɤ˥˩ ʈʂʊŋ˥˥ ɕin˥˥", "syllable_count": 4, "sentences": [{"text": "监测中心里的人一直看着各种机器。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有危险时，监测中心会先知道。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在监测中心上夜班，要看着屏幕。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测中心的墙上挂着很多屏幕，工作人员盯着它们。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上着火时，监测中心马上打电话报警。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的妈妈每天去监测中心看机器有没有问题。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测中心二十四小时有人，不会没人看着机器。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器出了问题，监测中心的人马上就知道。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去监测中心工作，每天保护大家的安全。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测中心的人发现水位太高，赶快通知了大家。", "target_word": "监测中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个监测中心", "label": "量词"}, {"form": "空气监测中心", "label": "复合"}, {"form": "監測中心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作人员盯着设备防范危险的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de1e997-cade-4800-bbaf-67fd2a0fa879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监测中心", "is_correct": true, "explanation": "“监测中心”是工作人员看着设备的地方，与“一直看着各种机器”相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园里没有需要人一直盯着看的机器，与语境不符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海里不存在工作人员盯着的各种机器，与语境不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“图书馆”不搭配“一直看着各种机器”的工作场景。"}], "explanations": {"监测中心": "“监测中心”是工作人员看着设备的地方，与“一直看着各种机器”相符。", "花园": "语义：花园里没有需要人一直盯着看的机器，与语境不符。", "大海": "语义：大海里不存在工作人员盯着的各种机器，与语境不符。", "图书馆": "搭配：“图书馆”不搭配“一直看着各种机器”的工作场景。"}, "sentence_index": 0, "correct_answer": "监测中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人在监测中心躺在床上打点滴。", "explanation": "这里应该用〈医院〉。监测中心没有病床，不是给病人治疗的地方。"}, {"text": "监测中心里陈列着很多古代的文物。", "explanation": "这里应该用〈博物馆〉。监测中心是工作人员盯着设备、防范危险的地方，不陈列文物。"}, {"text": "周末我们去监测中心里划船。", "explanation": "这里应该用〈湖〉。监测中心不是水域，划船要去湖或河上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监测中心", "is_correct": true, "explanation": "“监测中心”二十四小时有人值守，符合“不会没人看着机器”。"}, {"text": "花店", "is_correct": false, "explanation": "语义：花店没有需要一直有人看着的机器，与语境不符。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店里不需要人一直盯着看机器，与语境不符。"}, {"text": "海滩", "is_correct": false, "explanation": "搭配：“海滩”不搭配“有人看着机器”的表达。"}], "explanations": {"监测中心": "“监测中心”二十四小时有人值守，符合“不会没人看着机器”。", "花店": "语义：花店没有需要一直有人看着的机器，与语境不符。", "理发店": "语义：理发店里不需要人一直盯着看机器，与语境不符。", "海滩": "搭配：“海滩”不搭配“有人看着机器”的表达。"}, "sentence_index": 6, "correct_answer": "监测中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们每天早上去监测中心上课。", "explanation": "这里应该用〈学校〉。监测中心是工作人员盯着设备、防范危险的地方，不是上课的地方。"}, {"text": "妈妈去监测中心买了一些菜。", "explanation": "这里应该用〈超市〉。监测中心不卖东西，买菜要去超市。"}, {"text": "顾客在监测中心存钱。", "explanation": "这里应该用〈银行〉。监测中心不办理存款业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近有一位监测中心。", "corrected_sentence": "我家附近有一个监测中心。", "error_description": "量词错误：“位”用于人，监测中心是场所，应用“个”。应改为“一个监测中心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都监测中心值班。", "corrected_sentence": "他每天都在监测中心值班。", "error_description": "缺少介词：表示场所要说“在监测中心值班”，不能说“监测中心值班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93777b65-4e92-4fa7-8dfd-a693d7cacd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
