INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是确定下来，不再改变。", "primary_collocate": null, "pronunciation": "dìng", "ipa": "tiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这件事就这么定了。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的地点已经定下来了。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路线定了以后，不要再改。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单定了，谁也不能换人。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，考试时间定在星期五。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发的日子还没定，你再等等。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说：好，那就定了，下周去。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格定下来以后，他们才签了字。", "target_word": "定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的校服颜色早就定了，不能变。", "target_word": "定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划一旦定了，我们就要照着做。", "target_word": "定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定了", "label": "体标"}, {"form": "定下来", "label": "复合"}, {"form": "定好", "label": "复合"}], "register": "中性", "sense_fingerprint": "定：确定下来，不再改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6f056b-9b65-490b-8dc3-4791e2f44aeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。定（dìng）在此表示确定下来，不再改变。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，顶是顶住的意思。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，盯是注视的意思。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，钉是钉子的意思。"}], "explanations": {"定": "正确。定（dìng）在此表示确定下来，不再改变。", "顶": "dǐng（第三声）与 dìng（第四声）声调不同，顶是顶住的意思。", "盯": "dīng（第一声）与 dìng（第四声）声调不同，盯是注视的意思。", "钉": "dīng（第一声）与 dìng（第四声）声调不同，钉是钉子的意思。"}, "sentence_index": null, "correct_answer": "定"}, "level_3": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。定了表示事情确定下来，不再改变。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”不能用于“这件事”，“这件事就这么买了”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与事情确定无关，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于“这件事”，句中要的是确定下来的意思。"}], "explanations": {"定": "正确。定了表示事情确定下来，不再改变。", "买": "搭配：“买”不能用于“这件事”，“这件事就这么买了”说不通。", "唱": "语义：唱与事情确定无关，句意不通。", "洗": "搭配：“洗”不能用于“这件事”，句中要的是确定下来的意思。"}, "sentence_index": 0, "correct_answer": "定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家人在春节就定了一封信。", "explanation": "这里应该用〈写〉。定是确定下来的意思，写信要用〈写〉。"}, {"text": "我已经定了两个电话，明天去。", "explanation": "这里应该用〈打〉。定是确定下来的意思，打电话要用〈打〉。"}, {"text": "今天的雨已经定了，改不了。", "explanation": "这里应该用〈预报〉。定指人确定下来，天气不能由人确定，只能预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。定（dìng）在此表示确定下来，不再改变。"}, {"text": "丁", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，丁是天干的第四位，与本词义无关。"}, {"text": "鼎", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，鼎指古代烹煮食物的器具，与本词义无关。"}, {"text": "叮", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，叮指叮咛、叮嘱，与本词义无关。"}], "explanations": {"定": "正确。定（dìng）在此表示确定下来，不再改变。", "丁": "dīng（第一声）与 dìng（第四声）声调不同，丁是天干的第四位，与本词义无关。", "鼎": "dǐng（第三声）与 dìng（第四声）声调不同，鼎指古代烹煮食物的器具，与本词义无关。", "叮": "dīng（第一声）与 dìng（第四声）声调不同，叮指叮咛、叮嘱，与本词义无关。"}, "sentence_index": null, "correct_answer": "定"}, "level_3": {"options": [{"text": "定", "is_correct": true, "explanation": "正确。“那就定了”指事情已经确定，不再改变。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与“下周去”的安排无关，“那就哭了”句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉与定下出行的时间无关，句意不通。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”不能用来表示作出决定，“那就摇了”说不通。"}], "explanations": {"定": "正确。“那就定了”指事情已经确定，不再改变。", "哭": "语义：哭与“下周去”的安排无关，“那就哭了”句意不通。", "睡": "语义：睡觉与定下出行的时间无关，句意不通。", "摇": "搭配：“摇”不能用来表示作出决定，“那就摇了”说不通。"}, "sentence_index": 6, "correct_answer": "定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场地震的时间已经定了，大家都得准备。", "explanation": "这里应该用〈预测〉。定指确定下来，地震的时间无法确定，只能预测。"}, {"text": "他定到了丢失的钥匙，很高兴。", "explanation": "这里应该用〈找到〉。定是确定下来的意思，找回丢失的东西要用〈找到〉。"}, {"text": "今晚的月亮已经定了，改不了。", "explanation": "这里应该用〈升起〉。定指人确定下来，月亮是自然升起的，不能说“定了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案定下去以后，大家都没意见。", "corrected_sentence": "这个方案定下来以后，大家都没意见。", "error_description": "补语错误：表示“定”的结果要用“下来”，“下去”表示持续，不能表示确定。正确为“定下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "名单已经定着了，谁也不能换人。", "corrected_sentence": "名单已经定了，谁也不能换人。", "error_description": "体标错误：“定”表示确定的结果，要用“了”，不能用表示持续的“着”，应说“已经定了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
