INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "闻起来很舒服、干净的味道。", "primary_collocate": null, "pronunciation": "qīng xiāng", "ipa": "tɕʰiŋ˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "妈妈洗完头，头发上有一股清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块香皂的清香让我很喜欢。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开衣柜，里面有一阵清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床单晒过太阳，闻起来有清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身上总有淡淡的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢雨后空气里的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣液的清香一点也不刺鼻。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一进新家，我就闻到了淡淡的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶香水的清香很舒服，不太浓。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚擦过桌子，房间里留着一点清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股清香", "label": "量词搭配"}, {"form": "一阵清香", "label": "量词搭配"}, {"form": "清香扑鼻", "label": "四字格"}], "register": "中性", "sense_fingerprint": "清香：闻起来舒服、干净的淡淡味道（洗发水、衣物、空气等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清香", "is_correct": true, "explanation": "本词，指闻起来干净舒服的淡淡味道。"}, {"text": "轻响", "is_correct": false, "explanation": "轻响（qīng xiǎng）与清香（qīng xiāng）第二个音节声调不同（第三声与第一声），意思是轻微的声响。"}, {"text": "清宵", "is_correct": false, "explanation": "清宵（qīng xiāo）与清香（qīng xiāng）韵母不同（iao 与 iang），意思是清静的夜晚。"}, {"text": "倾向", "is_correct": false, "explanation": "倾向（qīng xiàng）与清香（qīng xiāng）第二个音节声调不同（第四声与第一声），意思是心理或行为上的偏向。"}], "explanations": {"清香": "本词，指闻起来干净舒服的淡淡味道。", "轻响": "轻响（qīng xiǎng）与清香（qīng xiāng）第二个音节声调不同（第三声与第一声），意思是轻微的声响。", "清宵": "清宵（qīng xiāo）与清香（qīng xiāng）韵母不同（iao 与 iang），意思是清静的夜晚。", "倾向": "倾向（qīng xiàng）与清香（qīng xiāng）第二个音节声调不同（第四声与第一声），意思是心理或行为上的偏向。"}, "sentence_index": null, "correct_answer": "清香"}, "level_3": {"options": [{"text": "清香", "is_correct": true, "explanation": "清香指闻起来干净舒服的味道，与洗完头后的感觉一致。"}, {"text": "汽油味", "is_correct": false, "explanation": "语义：汽油味刺鼻，与“洗完头”后应有的干净感觉相反。"}, {"text": "烟味", "is_correct": false, "explanation": "语义：烟味令人不舒服，与“洗完头”后头发应有的清爽相矛盾。"}, {"text": "汗臭", "is_correct": false, "explanation": "语义：洗完头后头发应是干净的，汗臭是出汗后的难闻气味，与洗头后的情境矛盾。"}], "explanations": {"清香": "清香指闻起来干净舒服的味道，与洗完头后的感觉一致。", "汽油味": "语义：汽油味刺鼻，与“洗完头”后应有的干净感觉相反。", "烟味": "语义：烟味令人不舒服，与“洗完头”后头发应有的清爽相矛盾。", "汗臭": "语义：洗完头后头发应是干净的，汗臭是出汗后的难闻气味，与洗头后的情境矛盾。"}, "sentence_index": 0, "correct_answer": "清香"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喝多了，身上一股清香，臭烘烘的。", "explanation": "这里应该用〈酒味〉。清香指闻起来干净舒服的味道，喝醉后身上的酒气要说酒味，不能说清香。"}, {"text": "锅烧糊了，厨房里全是清香。", "explanation": "这里应该用〈焦糊味〉。清香指闻起来干净舒服的味道，烧焦的气味要说焦糊味，不能说清香。"}, {"text": "刚刷完墙，屋里一股清香，很刺鼻。", "explanation": "这里应该用〈油漆味〉。清香指干净舒服的味道，刚刷完墙的刺鼻气味要说油漆味，不能说清香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清香", "is_correct": true, "explanation": "清香指清淡宜人的香味，与“一点也不刺鼻”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“刺鼻”形容气味，颜色不能刺鼻，句子不成立。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“刺鼻”说的是气味令人不适，声音不能被闻到，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能用“刺鼻”来形容，句子搭配不当。"}], "explanations": {"清香": "清香指清淡宜人的香味，与“一点也不刺鼻”相符。", "颜色": "搭配：“刺鼻”形容气味，颜色不能刺鼻，句子不成立。", "声音": "语义：“刺鼻”说的是气味令人不适，声音不能被闻到，与句意不符。", "体重": "搭配：“体重”不能用“刺鼻”来形容，句子搭配不当。"}, "sentence_index": 6, "correct_answer": "清香"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "垃圾堆里散发着一股清香。", "explanation": "这里应该用〈腐臭〉。清香指干净舒服的香味，垃圾堆的气味应说腐臭，不能说清香。"}, {"text": "厕所里一股清香，让人憋得慌。", "explanation": "这里应该用〈尿臊味〉。清香令人舒服，厕所里刺鼻的气味应说尿臊味，不能说清香。"}, {"text": "地下室有一股清香，潮得很。", "explanation": "这里应该用〈霉味〉。清香指干净舒服的味道，陈旧潮湿的气味要说霉味，不能说清香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我洗完澡，身上有一个清香。", "corrected_sentence": "我洗完澡，身上有一股清香。", "error_description": "量词错误：“清香”作名词时用“股”，不能用“个”，应改为“一股清香”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开窗通风后，屋里还留着一个清香。", "corrected_sentence": "开窗通风后，屋里还留着一点清香。", "error_description": "量词错误：“清香”作名词时不能用“个”计量，应用“点”表示少量，改为“一点清香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
