INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最后得到的东西。", "primary_collocate": null, "pronunciation": "zhōng chǎn wù", "ipa": "ʈʂʊŋ˥ ʈʂʰan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "做完这些步骤，终产物就是一杯果汁。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一块布经过很多步骤，终产物是一件衣服。", "target_word": "终产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们做了三天，终产物是一张桌子。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个过程很长，但终产物很漂亮。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看看这些材料的终产物是什么。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写作文的终产物是一篇好文章。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看终产物，就知道工人做得好不好。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小麦经过磨粉，终产物是白色的面粉。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "终产物放进盒子里，就可以卖了。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每天检查终产物的质量。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "終產物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经过一系列步骤后最后得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6f056b-9b65-490b-8dc3-4791e2f44aeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": false, "explanation": "语义：原料是加工前投入的东西，不是加工完成后得到的饮品。"}, {"text": "半成品", "is_correct": false, "explanation": "语义：半成品指尚未加工完成的东西，与“做完这些步骤”相矛盾。"}, {"text": "配料", "is_correct": false, "explanation": "搭配：“配料”是加进食物里的成分，不能说“配料就是一杯果汁”。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：做完步骤后得到的最后东西，即一杯果汁。"}], "explanations": {"原料": "语义：原料是加工前投入的东西，不是加工完成后得到的饮品。", "半成品": "语义：半成品指尚未加工完成的东西，与“做完这些步骤”相矛盾。", "配料": "搭配：“配料”是加进食物里的成分，不能说“配料就是一杯果汁”。", "终产物": "正确：做完步骤后得到的最后东西，即一杯果汁。"}, "sentence_index": 0, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做衣服前，先要准备好终产物。", "explanation": "这里应该用〈原料〉。终产物是加工完成后得到的东西，不能在加工前准备。"}, {"text": "我们刚开始做果汁，先把终产物洗干净。", "explanation": "这里应该用〈水果〉。刚开始做时用的是原来的水果，终产物是做完后最后得到的东西。"}, {"text": "这些衣服还是终产物，扣子还没缝上。", "explanation": "这里应该用〈半成品〉。终产物指加工完成的东西，与“扣子还没缝上”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：说明书只讲使用方法，看它不能知道工人做得好不好。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与工人的工作质量无关，看天气不能判断东西做得好不好。"}, {"text": "配方", "is_correct": false, "explanation": "搭配：“配方”是配料和步骤，不能与“做得好不好”搭配来判断工作质量。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：指加工完成后得到的东西，看它才能知道工人做得好不好。"}], "explanations": {"说明书": "语义：说明书只讲使用方法，看它不能知道工人做得好不好。", "天气": "语义：天气与工人的工作质量无关，看天气不能判断东西做得好不好。", "配方": "搭配：“配方”是配料和步骤，不能与“做得好不好”搭配来判断工作质量。", "终产物": "正确：指加工完成后得到的东西，看它才能知道工人做得好不好。"}, "sentence_index": 6, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清洗后，机器里还留着很多终产物。", "explanation": "这里应该用〈残渣〉。终产物是加工得到的成果，留在机器里的是残渣，不是终产物。"}, {"text": "我们跑到终产物就停下来了。", "explanation": "这里应该用〈终点〉。终产物是最后得到的东西；跑步到达、停下来的地方叫终点，不能说终产物。"}, {"text": "这一步得到的终产物还要继续加工。", "explanation": "这里应该用〈中间品〉。终产物是最后得到的东西，不会再被加工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把终产物们装进了箱子。", "corrected_sentence": "工人把终产物装进了箱子。", "error_description": "“终产物”是物品，不能加“们”；“们”只用于指人的名词。应改为：工人把终产物装进了箱子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂每天生产一位终产物。", "corrected_sentence": "工厂每天生产一批终产物。", "error_description": "“位”只用于人，终产物是物品，不能用“位”；成批生产的东西用“批”。应改为：工厂每天生产一批终产物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水开始流出来的地方，也指事情开始的地方。", "primary_collocate": null, "pronunciation": "yuán tóu", "ipa": "ɥɛn˧˥ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们走了很久，终于看到小河的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个泉水就是那条小溪的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这件事的源头是一个误会。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道黄河的源头在哪个省吗？", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脚下有一个小湖，是这条河的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架的源头其实是一句玩笑话。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上山顶，去看河水的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找到火灾的源头，所以去了仓库。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的源头是一本老书。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很清，因为源头没有污染。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "源頭", "label": "繁体"}, {"form": "源头活水", "label": "四字格"}, {"form": "一个源头", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "源头：水开始流出的地方，也指事情开始的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脚印", "is_correct": false, "explanation": "语义：脚印是人或动物踩出的痕迹，小河不会留下脚印，句中说“终于看到小河的……”讲不通。"}, {"text": "源头", "is_correct": true, "explanation": "源头：水开始流出的地方。这里指小河的起始处，与“看到”搭配，句意通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或动物活了多少年，不用来说小河。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”要用“闻”或“尝”，不能和“看到”搭配。"}], "explanations": {"脚印": "语义：脚印是人或动物踩出的痕迹，小河不会留下脚印，句中说“终于看到小河的……”讲不通。", "源头": "源头：水开始流出的地方。这里指小河的起始处，与“看到”搭配，句意通顺。", "年龄": "语义：年龄指人或动物活了多少年，不用来说小河。", "味道": "搭配：“味道”要用“闻”或“尝”，不能和“看到”搭配。"}, "sentence_index": 0, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的源头很宽，大船可以从那里驶入大海。", "explanation": "这里应该用〈河口〉。河口是河流汇入大海、可以行船的地方；源头是水开始流出的地方，通常很窄，不能说很宽，也不能让大船从那里驶入大海。"}, {"text": "这条路的源头在山的那一边。", "explanation": "这里应该用〈起点〉。起点指道路开始的地方；源头指水或事情的根源，一般不用来指道路的起始处。"}, {"text": "我们的源头在这片草原上生活了三千年。", "explanation": "这里应该用〈祖先〉。祖先是世代相传的先人，能在某地生活；源头指水或事情开始的地方，不指人群，不能作“生活”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山顶", "is_correct": false, "explanation": "语义：山顶是山的最高处，河水没有山顶，与“河水的”搭配不成立。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“去看”后面不能接“声音”，声音要用“听”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，河水不说体重。"}, {"text": "源头", "is_correct": true, "explanation": "源头：水开始流出的地方。这里指河水的起始处，与“去看”搭配，句意通顺。"}], "explanations": {"山顶": "语义：山顶是山的最高处，河水没有山顶，与“河水的”搭配不成立。", "声音": "搭配：“去看”后面不能接“声音”，声音要用“听”。", "体重": "语义：体重指人或动物的重量，河水不说体重。", "源头": "源头：水开始流出的地方。这里指河水的起始处，与“去看”搭配，句意通顺。"}, "sentence_index": 6, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场马拉松的源头在市政府门口。", "explanation": "这里应该用〈起点〉。起点可用于比赛、路线的出发处；源头指水或事情开始的根源，不用于比赛的起跑地。"}, {"text": "这个博物馆的源头在东边，大家从那里进去。", "explanation": "这里应该用〈入口〉。入口是人可以进入的地方；源头是水或事情开始的地方，不指建筑的进出口。"}, {"text": "这个学期的源头是期末考试。", "explanation": "这里应该用〈终点〉。终点指一段过程结束的地方或时候；源头指水或事情开始的地方，不能指结束的时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿着河走，终于找到了一只源头。", "corrected_sentence": "我们沿着河走，终于找到了一个源头。", "error_description": "“源头”的量词错误：应说“一个源头”，不能说“一只源头”。“只”多用于动物，或用于成对、小件的东西，“源头”应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泉水源头流出来。", "corrected_sentence": "泉水从源头流出来。", "error_description": "介词“从”的遗漏：表示起点要说“从源头流出来”，不能直接说“源头流出来”，否则“源头”前缺少引出起点的“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
