INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农民伯伯用来让庄稼长得更好的东西。", "primary_collocate": null, "pronunciation": "huà xué féi liào", "ipa": "xua˥˩ ɕɥe˧˥ fei˧˥ liɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "爸爸给菜地撒了化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民伯伯买了化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学肥料可以让庄稼长得好。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这袋化学肥料很重。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地里的苗太小，要加点化学肥料。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民伯伯背着化学肥料走向田里。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，化学肥料能让麦子长得更好。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库里放着很多化学肥料。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以前，不要撒化学肥料。", "target_word": "化学肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用化学肥料种出了大白菜。", "target_word": "化学肥料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "化學肥料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "撒在地里让庄稼长得更好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学肥料", "is_correct": true, "explanation": "正确。“给菜地撒了……”指施给庄稼用的肥料，符合句意。"}, {"text": "煤油", "is_correct": false, "explanation": "语义：煤油撒在菜地里会伤害庄稼，不是让庄稼长得好的东西，与句子语境相反。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能促进庄稼生长，撒在菜地里只会妨碍作物。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“撒”一般不与“手机”搭配，撒在菜地里的东西不会是手机。"}], "explanations": {"化学肥料": "正确。“给菜地撒了……”指施给庄稼用的肥料，符合句意。", "煤油": "语义：煤油撒在菜地里会伤害庄稼，不是让庄稼长得好的东西，与句子语境相反。", "石头": "语义：石头不能促进庄稼生长，撒在菜地里只会妨碍作物。", "手机": "搭配：“撒”一般不与“手机”搭配，撒在菜地里的东西不会是手机。"}, "sentence_index": 0, "correct_answer": "化学肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一个化学肥料。", "explanation": "这里应该用〈袋〉。肥料多按袋计量，“个”不适用于化学肥料。"}, {"text": "农场的牛每天吃化学肥料。", "explanation": "这里应该用〈饲料〉。牛吃的是饲料；化学肥料是施给庄稼的，不能拿来喂牛。"}, {"text": "农民喷化学肥料消灭害虫。", "explanation": "这里应该用〈农药〉。消灭害虫要用农药；化学肥料的作用是让庄稼长得更好，不能用来杀虫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学肥料", "is_correct": true, "explanation": "正确。化学肥料是施给庄稼的东西，能让麦子长得更好，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨用的，不能让麦子长得更好。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与麦子的生长无关。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书用的，不能让麦子长得更好。"}], "explanations": {"化学肥料": "正确。化学肥料是施给庄稼的东西，能让麦子长得更好，符合句意。", "雨伞": "语义：雨伞是挡雨用的，不能让麦子长得更好。", "手机": "语义：手机与麦子的生长无关。", "书包": "语义：书包是装书用的，不能让麦子长得更好。"}, "sentence_index": 6, "correct_answer": "化学肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们买了一根化学肥料。", "explanation": "这里应该用〈袋〉。肥料按袋计量，“根”用于细长的东西，不能用于化学肥料。"}, {"text": "小华用化学肥料洗袜子。", "explanation": "这里应该用〈洗衣粉〉。洗袜子要用洗衣粉；化学肥料是给庄稼用的，不能用来洗袜子。"}, {"text": "奶奶用化学肥料包饺子。", "explanation": "这里应该用〈面粉〉。包饺子要用面粉和面皮；化学肥料不能用来做食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民伯伯昨天买了两只化学肥料。", "corrected_sentence": "农民伯伯昨天买了两袋化学肥料。", "error_description": "量词错误：化学肥料应用“袋”计量，“只”用于动物或成对的东西，应说“两袋化学肥料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用化学肥料种很好。", "corrected_sentence": "他们用化学肥料种得很好。", "error_description": "补语错误：“种”后面的状态补语“很好”要用“得”连接，应说“种得很好”，不能说“种很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
