INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把垃圾运走，让环境干净。", "primary_collocate": null, "pronunciation": "lā jī qīng yùn", "ipa": "la˥ tɕi˥ tɕʰiŋ˥ yn˥˩", "syllable_count": 4, "sentences": [{"text": "垃圾清运以后，街道变干净了。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天晚上都有人负责垃圾清运。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里没有垃圾清运，河边堆满了垃圾。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的垃圾清运很准时。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风天垃圾清运停止了，大家要把垃圾放在家里。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天垃圾清运要更勤，不然会有臭味。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司做垃圾清运，工作很辛苦。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的垃圾清运一天两次。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾清运完了，工人们才回家休息。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的垃圾清运已经停了三天。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾清運", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把垃圾运走使环境干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指把垃圾运走的工作，“……以后，街道变干净了”的主语成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业与“街道变干净”无关，不能使街道变干净。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日期或活动，与街道卫生的语境不相关。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“树木以后，街道变干净了”不成话，树木不能作这种时间状语。"}], "explanations": {"垃圾清运": "正确：指把垃圾运走的工作，“……以后，街道变干净了”的主语成立。", "作业": "语义：作业与“街道变干净”无关，不能使街道变干净。", "生日": "语义：生日是日期或活动，与街道卫生的语境不相关。", "树木": "搭配：“树木以后，街道变干净了”不成话，树木不能作这种时间状语。"}, "sentence_index": 0, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的垃圾清运臭得厉害。", "explanation": "清运是把垃圾运走的过程，不是散发臭味的废物，所以不能说“臭得厉害”。"}, {"text": "我用垃圾清运做了一把椅子。", "explanation": "清运是动作或过程，不是材料，不能用来制作东西。"}, {"text": "他是个能干的垃圾清运。", "explanation": "指人时应说〈垃圾清运工〉。“垃圾清运”表示行为，不能直接指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指在公司从事的垃圾收运工作，与“工作很辛苦”的语境吻合。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景不是可以“做”的工作，与“工作很辛苦”无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做天气”不是常见搭配，天气不能被“做”。"}, {"text": "海浪", "is_correct": false, "explanation": "搭配：“做海浪”不成话，海浪不能作“做”的对象。"}], "explanations": {"垃圾清运": "正确：指在公司从事的垃圾收运工作，与“工作很辛苦”的语境吻合。", "风景": "语义：风景不是可以“做”的工作，与“工作很辛苦”无关。", "天气": "搭配：“做天气”不是常见搭配，天气不能被“做”。", "海浪": "搭配：“做海浪”不成话，海浪不能作“做”的对象。"}, "sentence_index": 6, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都对窗户进行垃圾清运。", "explanation": "清运的对象是垃圾，不能用来指擦洗窗户。"}, {"text": "这幅画的垃圾清运很美。", "explanation": "清运是把垃圾运走的过程，不能用来形容画作。"}, {"text": "我们周末去垃圾清运旅行。", "explanation": "清运是过程，不是地点，不能用来指旅行的目的地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区的垃圾清运的很快。", "corrected_sentence": "这个小区的垃圾清运得很快。", "error_description": "助词错误：动词后表示程度的补语要用“得”，不能用“的”；“清运的很快”是错的，应说“清运得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在打垃圾清运。", "corrected_sentence": "工人们正在进行垃圾清运。", "error_description": "搭配错误：“垃圾清运”不能和“打”搭配，应说“进行垃圾清运”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
