INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "得到的东西。", "primary_collocate": null, "pronunciation": "suǒ dé", "ipa": "suo˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他把一天的所得放在桌子上。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打工一个月，她的所得不多。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我们大家辛苦工作的所得。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把所得分给了几个朋友。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王看着一年的所得，笑了。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的所得，我要全部存起来。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民出海一天，所得是三筐鱼。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们数了数今天的所得。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想要别人的所得，只想靠自己。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的所得，是一个宝贵的经验。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所得税", "label": "复合"}, {"form": "劳动所得", "label": "复合"}], "register": "书面", "sense_fingerprint": "自己得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”指得到的东西，可以放在桌子上。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能放在桌子上，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不是可以放置的东西。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“放”要带具体物品作宾语，“笑声”不能放在桌子上。"}], "explanations": {"所得": "正确：“所得”指得到的东西，可以放在桌子上。", "时间": "语义：“时间”是抽象概念，不能放在桌子上，句意不通。", "体温": "语义：“体温”是身体的温度，不是可以放置的东西。", "笑声": "搭配：“放”要带具体物品作宾语，“笑声”不能放在桌子上。"}, "sentence_index": 0, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友的所得很深。", "explanation": "这里应该用〈感情〉。“所得”指得到的东西，不能用“很深”来形容。"}, {"text": "他每天早上都要喝一杯所得。", "explanation": "这里应该用〈牛奶〉。“所得”指得到的东西，不是饮料，不能“喝一杯”。"}, {"text": "他的心里充满了所得。", "explanation": "这里应该用〈喜悦〉。“所得”是得到的东西，不是情绪，不能“充满”心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”指渔民出海得到的东西，即三筐鱼。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：“疲惫”是人的状态，不是出海的结果，与“三筐鱼”不搭。"}, {"text": "理想", "is_correct": false, "explanation": "语义：“理想”是抽象的愿望，与“三筐鱼”这样具体的收获不搭。"}, {"text": "渔网", "is_correct": false, "explanation": "搭配：“三筐”计量的是鱼、果实等收获，“渔网”是工具，不能用“三筐”来计量。"}], "explanations": {"所得": "正确：“所得”指渔民出海得到的东西，即三筐鱼。", "疲惫": "语义：“疲惫”是人的状态，不是出海的结果，与“三筐鱼”不搭。", "理想": "语义：“理想”是抽象的愿望，与“三筐鱼”这样具体的收获不搭。", "渔网": "搭配：“三筐”计量的是鱼、果实等收获，“渔网”是工具，不能用“三筐”来计量。"}, "sentence_index": 6, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失误给球队带来了很大的所得。", "explanation": "这里应该用〈损失〉。失误带来的是损失，“所得”指得到的收益，不能与负面结果搭配。"}, {"text": "这笔债务成了他的所得。", "explanation": "这里应该用〈负担〉。债务是需要偿还的负担，不是得到的东西。"}, {"text": "他一生都在忍受所得。", "explanation": "这里应该用〈痛苦〉。忍受的是痛苦，“所得”不能被忍受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她攒下了一块不小的所得。", "corrected_sentence": "她攒下了一笔不小的所得。", "error_description": "错误：“所得”前的量词“块”不当，应为“笔”。“块”用于块状物，不用于计量所得。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民今天拿回了一座可观的所得。", "corrected_sentence": "渔民今天拿回了一笔可观的所得。", "error_description": "错误：“所得”前的量词“座”不当，应为“笔”。“座”用于山、房屋等大型固定物，不用于计量所得。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "笼统", "is_correct": true, "explanation": "正确：“具体”指清楚、不笼统，“笼统”与其相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“具体”没有反义关系，“漂亮”形容外貌好看。"}, {"text": "安静", "is_correct": false, "explanation": "与“具体”没有反义关系，“安静”形容没有声音。"}, {"text": "明亮", "is_correct": false, "explanation": "与“具体”没有反义关系，“明亮”形容光线充足。"}], "correct_answer": "笼统", "explanations": {"笼统": "正确：“具体”指清楚、不笼统，“笼统”与其相对。", "漂亮": "与“具体”没有反义关系，“漂亮”形容外貌好看。", "安静": "与“具体”没有反义关系，“安静”形容没有声音。", "明亮": "与“具体”没有反义关系，“明亮”形容光线充足。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "笼统", "is_correct": true, "explanation": "正确：“具体”指清楚、不笼统，“笼统”与其相对。"}, {"text": "复杂", "is_correct": false, "explanation": "与“具体”没有反义关系，“复杂”形容事情多而难懂。"}, {"text": "好看", "is_correct": false, "explanation": "与“具体”没有反义关系，“好看”形容外表美观。"}, {"text": "可靠", "is_correct": false, "explanation": "与“具体”没有反义关系，“可靠”形容值得信任。"}], "correct_answer": "笼统", "explanations": {"笼统": "正确：“具体”指清楚、不笼统，“笼统”与其相对。", "复杂": "与“具体”没有反义关系，“复杂”形容事情多而难懂。", "好看": "与“具体”没有反义关系，“好看”形容外表美观。", "可靠": "与“具体”没有反义关系，“可靠”形容值得信任。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是说得很清楚，不模糊。", "primary_collocate": null, "pronunciation": "jù tǐ", "ipa": "tɕy˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "请你说得具体一点。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的计划很具体，大家都看得懂。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们具体的办法。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议的具体时间还没定。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太大，要说具体的例子。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道具体地址，好去找你。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "具体怎么做，我们明天再谈。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的介绍很具体，我一听就懂。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里没有写具体的数字。", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的“好”太简单了，能不能具体说说？", "target_word": "具体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更具体", "label": "程度"}, {"form": "具体化", "label": "复合"}, {"form": "具体地", "label": "状语"}], "register": "中性", "sense_fingerprint": "清楚、详细、不笼统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具体", "is_correct": true, "explanation": "正确：“具体”指说得清楚、不笼统，符合“请你说得……一点”的语境。"}, {"text": "远", "is_correct": false, "explanation": "语义：“说得远一点”没有意义，“远”不能描述说话的清楚程度。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”描述空间，不能用来形容说话的方式。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”不修饰说话，“说得厚一点”不成词组。"}], "explanations": {"具体": "正确：“具体”指说得清楚、不笼统，符合“请你说得……一点”的语境。", "远": "语义：“说得远一点”没有意义，“远”不能描述说话的清楚程度。", "窄": "语义：“窄”描述空间，不能用来形容说话的方式。", "厚": "搭配：“厚”不修饰说话，“说得厚一点”不成词组。"}, "sentence_index": 0, "correct_answer": "具体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很具体，大家都说他好相处。", "explanation": "这里应该用〈开朗〉。“具体”指说得清楚、不笼统，不能用来形容性格，形容性格应说“开朗”。"}, {"text": "这盒蛋糕的味道很具体，我一口就吃完了。", "explanation": "这里应该用〈香〉。“具体”指说得清楚、不笼统，不能用来形容味道，形容味道应说“香”。"}, {"text": "我很具体地哭了一场。", "explanation": "这里应该用〈伤心〉。“具体”修饰的是说明、要求等，不能修饰哭的动作，哭应说“伤心地哭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具体", "is_correct": true, "explanation": "正确：“具体”在这里作状语，说明要把怎么做的细节说清楚，符合语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上怎么做”要求立即行动，与后半句“我们明天再谈”冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，不能修饰“怎么做”。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说话，不能用来修饰“怎么做”。"}], "explanations": {"具体": "正确：“具体”在这里作状语，说明要把怎么做的细节说清楚，符合语境。", "马上": "语义：“马上怎么做”要求立即行动，与后半句“我们明天再谈”冲突。", "偶尔": "搭配：“偶尔”表示不常发生，不能修饰“怎么做”。", "大声": "搭配：“大声”修饰说话，不能用来修饰“怎么做”。"}, "sentence_index": 6, "correct_answer": "具体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的友情很具体，谁也分不开。", "explanation": "这里应该用〈深厚〉。“具体”指说得清楚、不笼统，不能形容情感，友情应说“深厚”。"}, {"text": "天气今天很具体，我们去海边吧。", "explanation": "这里应该用〈好〉。“具体”指说得清楚、不笼统，不能形容天气，天气应说“好”。"}, {"text": "这幅画的颜色很具体，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。“具体”指说明清楚，不能形容颜色，颜色应说“鲜艳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他具体的讲了一遍，大家都能听懂。", "corrected_sentence": "他具体地讲了一遍，大家都能听懂。", "error_description": "错误：“具体”作状语修饰动词“讲”时要用“地”，不能用“的”。正确：“具体地讲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想要一个具体地答案。", "corrected_sentence": "我想要一个具体的答案。", "error_description": "错误：“具体”修饰名词“答案”时要用“的”，不能用“地”。正确：“具体的答案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
