INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "自己动手做，不是让别人帮忙。", "primary_collocate": null, "pronunciation": "qīn shǒu", "ipa": "tɕʰin˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是我亲手做的饭。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈亲手做了很多菜。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想亲手给他一朵花。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张画是弟弟亲手画的。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师亲手写了一封信。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他亲手做了一个小船。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸亲手给我做玩具。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服是奶奶亲手做的。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要亲手把信交给她。", "target_word": "亲手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她亲手种了一棵小树。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己动手做，不让别人帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8156197-8a74-47f3-bff9-59c094dadc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。"}, {"text": "亲口", "is_correct": false, "explanation": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。"}, {"text": "亲友", "is_correct": false, "explanation": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。"}, {"text": "亲属", "is_correct": false, "explanation": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}], "explanations": {"亲手": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。", "亲口": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。", "亲友": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。", "亲属": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}, "sentence_index": null, "correct_answer": "亲手"}, "level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里指我自己动手做饭，符合句意。"}, {"text": "亲口", "is_correct": false, "explanation": "搭配：“亲口”指用嘴说，做饭这一动作不能用它修饰。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”指随便说出，不能修饰做饭。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”描述音量，与做饭这一动作无关，句意不通。"}], "explanations": {"亲手": "正确。这里指我自己动手做饭，符合句意。", "亲口": "搭配：“亲口”指用嘴说，做饭这一动作不能用它修饰。", "随口": "搭配：“随口”指随便说出，不能修饰做饭。", "大声": "语义：“大声”描述音量，与做饭这一动作无关，句意不通。"}, "sentence_index": 0, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他亲手承认了错误。", "explanation": "这里应该用〈亲口〉。承认是用嘴说出来，“亲手”不能修饰这一动作，应说“亲口承认”。"}, {"text": "我亲手听到他的声音。", "explanation": "这里应该用〈亲耳〉。听靠耳朵，“亲手”不适用于听觉，应说“亲耳听到”。"}, {"text": "我亲手看见了日出。", "explanation": "这里应该用〈亲眼〉。看见靠眼睛，“亲手”不能用于视觉动作，应说“亲眼看见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里表示爸爸自己动手做玩具，符合句意。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突然发生，与做玩具这一需要持续时间的过程冲突。"}, {"text": "瞬间", "is_correct": false, "explanation": "搭配：“瞬间”表示极短的时间，做玩具需要一段时间，二者不搭配。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示立即出现的变化，与做玩具的过程不合。"}], "explanations": {"亲手": "正确。这里表示爸爸自己动手做玩具，符合句意。", "猛然": "语义：“猛然”表示突然发生，与做玩具这一需要持续时间的过程冲突。", "瞬间": "搭配：“瞬间”表示极短的时间，做玩具需要一段时间，二者不搭配。", "顿时": "语义：“顿时”表示立即出现的变化，与做玩具的过程不合。"}, "sentence_index": 6, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲手经历过那次地震。", "explanation": "这里应该用〈亲身〉。亲手指手上的动作，经历地震不靠手，应说“亲身经历”。"}, {"text": "校长亲手参加了开幕式。", "explanation": "这里应该用〈亲自〉。参加活动不是手上的动作，应说“亲自参加”。"}, {"text": "我亲手见过那座古城。", "explanation": "这里应该用〈亲眼〉。见到景物靠眼睛，“亲手”不能用于视觉，应说“亲眼见过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个书架是爸爸亲手做了。", "corrected_sentence": "这个书架是爸爸亲手做的。", "error_description": "错误：“是……的”强调句的句末应用“的”，不能用“了”。正确是“这个书架是爸爸亲手做的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶亲手了缝这块布。", "corrected_sentence": "奶奶亲手缝了这块布。", "error_description": "错误：“了”误放在副词“亲手”和动词“缝”之间，应放在动词后。正确是“亲手缝了这块布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新鲜", "is_correct": true, "explanation": "新鲜：食物未变质，与「腐败」（食物变质）相对。"}, {"text": "高大", "is_correct": false, "explanation": "高大形容个子或建筑高，与「腐败」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色亮，与「腐败」没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地硬，与「腐败」没有反义关系。"}], "correct_answer": "新鲜", "explanations": {"新鲜": "新鲜：食物未变质，与「腐败」（食物变质）相对。", "高大": "高大形容个子或建筑高，与「腐败」没有反义关系。", "明亮": "明亮形容光线或颜色亮，与「腐败」没有反义关系。", "坚硬": "坚硬形容质地硬，与「腐败」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
