INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西变坏了，比如食物发霉不能吃。", "primary_collocate": null, "pronunciation": "fǔ bài", "ipa": "fu˨˩˦ pai˥˩", "syllable_count": 2, "sentences": [{"text": "这些水果放太久，已经腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "腐败的食物不能吃。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，鱼很快就腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱能让牛奶不容易腐败。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里有一股腐败的味道。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剩菜放在桌上慢慢腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把腐败的肉扔进了垃圾桶。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭没放进冰箱，第二天就腐败了。", "target_word": "腐败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盒鸡蛋腐败了，不要再吃。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮湿的粮食容易腐败。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐败了", "label": "体标"}, {"form": "腐败的", "label": "复合"}, {"form": "腐敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "食物、肉类等东西变质发臭、不能再吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐败", "is_correct": true, "explanation": "腐败：食物变质。此处指水果放太久已经变质。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」指清洁，放太久的水果不会变得干净，与「放太久」的变化相反。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：「坚硬」用于形容物体的质地，水果放久不会变得坚硬。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线，与食物变质的状态无关。"}], "explanations": {"腐败": "腐败：食物变质。此处指水果放太久已经变质。", "干净": "语义：「干净」指清洁，放太久的水果不会变得干净，与「放太久」的变化相反。", "坚硬": "搭配：「坚硬」用于形容物体的质地，水果放久不会变得坚硬。", "明亮": "语义：「明亮」形容光线，与食物变质的状态无关。"}, "sentence_index": 0, "correct_answer": "腐败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把铁刀放在雨里，已经腐败了。", "explanation": "这里应该用〈生锈〉。腐败指食物等有机物变质，金属在雨中变色要用「生锈」。"}, {"text": "冰块放在太阳下，已经腐败了。", "explanation": "这里应该用〈融化〉。冰块受热变成水要用「融化」，腐败只用于食物等变质。"}, {"text": "这块塑料放在火上，已经腐败了。", "explanation": "这里应该用〈变形〉。塑料受热改变形状要用「变形」，塑料不会腐败。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐败", "is_correct": true, "explanation": "腐败：肉已经变质。此处指变质的肉，所以要扔掉。"}, {"text": "美味", "is_correct": false, "explanation": "语义：「美味」指好吃，与扔进垃圾桶的情景相矛盾。"}, {"text": "清香", "is_correct": false, "explanation": "语义：「清香」形容气味清爽，与被扔掉的肉的状态不相符。"}, {"text": "发光", "is_correct": false, "explanation": "搭配：「发光」形容物体自身发亮，不用来描述肉的状态。"}], "explanations": {"腐败": "腐败：肉已经变质。此处指变质的肉，所以要扔掉。", "美味": "语义：「美味」指好吃，与扔进垃圾桶的情景相矛盾。", "清香": "语义：「清香」形容气味清爽，与被扔掉的肉的状态不相符。", "发光": "搭配：「发光」形容物体自身发亮，不用来描述肉的状态。"}, "sentence_index": 6, "correct_answer": "腐败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的油漆已经腐败了。", "explanation": "这里应该用〈褪色〉。腐败指食物等有机物变质，油漆颜色变淡要用「褪色」。"}, {"text": "这台旧手机用了五年，已经腐败了。", "explanation": "这里应该用〈老化〉。手机用久了性能变差要用「老化」，腐败不用于电子产品。"}, {"text": "杯子不小心摔在地上，已经腐败了。", "explanation": "这里应该用〈破碎〉。杯子摔裂成碎片要用「破碎」，腐败只用于食物等变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些菜在厨房里放了三天，被腐败了。", "corrected_sentence": "这些菜在厨房里放了三天，已经腐败了。", "error_description": "「腐败」是形容词，不能用「被」构成被动句。应说「已经腐败了」，去掉「被」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块肉放在厨房一夜，就腐败很厉害了。", "corrected_sentence": "这块肉放在厨房一夜，就腐败得很厉害了。", "error_description": "「腐败」后面要用补语标志「得」引出程度补语。应说「腐败得很厉害」，不能直接说「腐败很厉害」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
