INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人或动物反复练习，学会本领或习惯。", "primary_collocate": null, "pronunciation": "xùn liàn", "ipa": "ɕyn˥˩ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈训练孩子自己穿衣服。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师训练小朋友排好队。", "target_word": "训练", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸训练我每天自己刷牙。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶训练弟弟自己吃饭。", "target_word": "训练", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要训练孩子做家务。", "target_word": "训练", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "幼儿园老师训练小朋友唱歌。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈从小训练他自己睡觉。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈训练妹妹一个人去买东西。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师训练孩子们每天读书。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想训练女儿学会骑自行车。", "target_word": "训练", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "训练了", "label": "体标"}, {"form": "训练过", "label": "体标"}, {"form": "训练着", "label": "体标"}], "register": "中性", "sense_fingerprint": "使人或动物反复练习以掌握技能或习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8156197-8a74-47f3-bff9-59c094dadc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训练", "is_correct": true, "explanation": "正确：妈妈让孩子反复练习穿衣服，“训练孩子自己穿衣服”符合语境。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”不能用于让孩子自己穿衣服的语境。"}, {"text": "修改", "is_correct": false, "explanation": "语义：修改孩子与“学本领”的语境无关。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象是物品，不能用于孩子。"}], "explanations": {"训练": "正确：妈妈让孩子反复练习穿衣服，“训练孩子自己穿衣服”符合语境。", "烫": "搭配：“烫”不能用于让孩子自己穿衣服的语境。", "修改": "语义：修改孩子与“学本领”的语境无关。", "清洗": "搭配：“清洗”的对象是物品，不能用于孩子。"}, "sentence_index": 0, "correct_answer": "训练"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶训练了弟弟的电视。", "explanation": "训练的对象是人或动物，电视不能被训练，这里应该用〈修〉。"}, {"text": "奶奶训练了弟弟的饭菜。", "explanation": "训练的对象是人或动物，饭菜不能被训练，这里应该用〈做〉。"}, {"text": "老师训练了小朋友的哭声。", "explanation": "训练的结果是掌握本领，哭声不是可以训练的本领，这里应该用〈止〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训练", "is_correct": true, "explanation": "正确：爸爸妈妈从小让他反复练习自己睡觉，“训练他自己睡觉”符合语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于“自己睡觉”的语境。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤与“让孩子自己睡觉”无关。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不能用于孩子的睡眠习惯。"}], "explanations": {"训练": "正确：爸爸妈妈从小让他反复练习自己睡觉，“训练他自己睡觉”符合语境。", "洗": "搭配：“洗”不能用于“自己睡觉”的语境。", "烤": "语义：烤与“让孩子自己睡觉”无关。", "修": "搭配：“修”不能用于孩子的睡眠习惯。"}, "sentence_index": 6, "correct_answer": "训练"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想训练女儿的自行车。", "explanation": "训练的对象是人或动物，自行车不能被训练，这里应该用〈修〉。"}, {"text": "他想训练女儿的旧书包。", "explanation": "训练的对象是人或动物，书包不能被训练，这里应该用〈洗〉。"}, {"text": "他想训练女儿的心情变好。", "explanation": "训练的目标是掌握技能或习惯，心情不能通过训练变好，这里应该用〈安慰〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他训练着孩子一次。", "corrected_sentence": "他训练过孩子一次。", "error_description": "体标错误：“一次”表示一次完成的经历，应用“过”，不能用“着”（表示持续），应为“训练过孩子一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸每天训练了女儿骑车。", "corrected_sentence": "爸爸每天训练女儿骑车。", "error_description": "体标错误：“每天”表示经常性的动作，不能与“了”搭配，应为“每天训练女儿骑车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
