INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次活过来或重新开始生活。", "primary_collocate": null, "pronunciation": "chóng shēng", "ipa": "ʈʂʰʊŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "传说中，凤凰会在火里重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在游戏里死了，过一会儿又重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人希望死后可以重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，要是能重生，还想当老师。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的主角重生到了十年前。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里，这个英雄死后又重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火过后，草地上的小草慢慢重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想离开旧生活，重生一次。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络小说常写主角重生回到学生时代。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信人死后能重生吗？", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重生了", "label": "体标"}, {"form": "重生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "死后再次活过来，或重新开始生活（动词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8156197-8a74-47f3-bff9-59c094dadc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“凤凰会在火里重生”指凤凰在火中再次活过来，符合神话情境。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：凤凰的神话是再生，“逃跑”表示离开，与“在火里”的再生情境不合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”描述的是火的状态，不能用来描述凤凰的行为。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“哭泣”不能与“在火里”搭配来描述凤凰的行为。"}], "explanations": {"重生": "正确。“凤凰会在火里重生”指凤凰在火中再次活过来，符合神话情境。", "逃跑": "语义：凤凰的神话是再生，“逃跑”表示离开，与“在火里”的再生情境不合。", "熄灭": "语义：“熄灭”描述的是火的状态，不能用来描述凤凰的行为。", "哭泣": "搭配：“哭泣”不能与“在火里”搭配来描述凤凰的行为。"}, "sentence_index": 0, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷是在一个寒冷的冬天重生的。", "explanation": "这里应该用〈出生〉。重生指再次活过来或重新开始生活，人第一次来到世界应说“出生”。"}, {"text": "我们下周重生。", "explanation": "这里应该用〈搬家〉。重生不指迁移居住地，句中“下周”的安排应说“搬家”。"}, {"text": "请你明天把作业重生给老师。", "explanation": "这里应该用〈交〉。重生指再次活过来或重新开始生活，把作业给老师应说“交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“草地上的小草慢慢重生了”指大火后小草重新生长，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：小草不能结婚，与句子主语及描写的情境不合。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：小草不会歌唱，“歌唱”与描写植物恢复的语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能与“小草”搭配，句意不通。"}], "explanations": {"重生": "正确。“草地上的小草慢慢重生了”指大火后小草重新生长，符合句意。", "结婚": "语义：小草不能结婚，与句子主语及描写的情境不合。", "歌唱": "语义：小草不会歌唱，“歌唱”与描写植物恢复的语境不合。", "游泳": "搭配：“游泳”不能与“小草”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请帮我把这杯水重生一下。", "explanation": "这里应该用〈加热〉。重生指再次活过来或重新开始生活，不能用于把水弄热。"}, {"text": "这个孩子去年重生了三公分。", "explanation": "这里应该用〈长高〉。重生指再次活过来或重新开始生活，身高增加应说“长高”。"}, {"text": "这封信刚才重生了。", "explanation": "这里应该用〈寄到〉。重生指人或生命、状态重新开始，信件送达应说“寄到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人终于被重生了。", "corrected_sentence": "这位老人终于重生了。", "error_description": "“重生”是不及物动词，不能用“被”构成被动句，应说“重生了”，这里误加了“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那场病后重生着一次。", "corrected_sentence": "他在那场病后重生了一次。", "error_description": "错误：“重生”表示一次性的变化，不能用表示持续状态的“着”，应用“了”，说“重生了一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
