INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "眼睛看到事情发生。", "primary_collocate": null, "pronunciation": "mù jī", "ipa": "mu˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我在街上目击了一次打架。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机目击前面的车撞到了树。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有目击火灾，只是听别人说的。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多游客目击了山上的雪崩。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王目击了朋友摔倒的那一刻。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在公园目击小狗救了一个孩子。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己曾经目击过一次交通事故。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁目击了昨晚发生的事？", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我：“你目击了打架的过程吗？”", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躲在树后，目击了这一切。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "目击了", "label": "体标"}, {"form": "目击过", "label": "体标"}, {"form": "目击者", "label": "复合"}, {"form": "目擊", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用眼睛看到事情发生，日常叙述中的见证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指在街上亲眼看到一次打架。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的宾语是商品，不能说购买一次打架。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：「支付」的宾语是款项，不能说支付一次打架。"}, {"text": "设计", "is_correct": false, "explanation": "语义：「设计」指有意识地构思，与「在街上」偶然遇到的情况不符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指在街上亲眼看到一次打架。", "购买": "搭配：「购买」的宾语是商品，不能说购买一次打架。", "支付": "搭配：「支付」的宾语是款项，不能说支付一次打架。", "设计": "语义：「设计」指有意识地构思，与「在街上」偶然遇到的情况不符。"}, "sentence_index": 0, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去博物馆目击了恐龙化石。", "explanation": "这里应该用〈参观〉。目击的对象必须是发生的事件，化石是物品，只能去参观。"}, {"text": "我一边写作业，一边目击音乐。", "explanation": "这里应该用〈听〉。目击靠视觉，音乐是声音，不是可以亲眼看见的事件，应该用听。"}, {"text": "他目击了一种新的洗衣机。", "explanation": "这里应该用〈发明〉。目击指亲眼看见已经发生的事件，洗衣机是物品，不能被目击；发明是做出新东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指她曾经亲眼看到一次交通事故。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」的宾语是物品，不能说收藏一次事故。"}, {"text": "布置", "is_correct": false, "explanation": "搭配：「布置」的宾语是场地或任务，不能说布置一次事故。"}, {"text": "嘲讽", "is_correct": false, "explanation": "语义：「嘲讽」是讥笑他人，与她讲述亲身经历的语境不相符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指她曾经亲眼看到一次交通事故。", "收藏": "搭配：「收藏」的宾语是物品，不能说收藏一次事故。", "布置": "搭配：「布置」的宾语是场地或任务，不能说布置一次事故。", "嘲讽": "语义：「嘲讽」是讥笑他人，与她讲述亲身经历的语境不相符。"}, "sentence_index": 6, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家正在目击这个问题。", "explanation": "这里应该用〈讨论〉。目击是亲眼看见事件，问题是需要讨论的内容，不能被目击。"}, {"text": "这首歌让我目击了温暖。", "explanation": "这里应该用〈感受〉。目击是亲眼看见事情，温暖是一种感觉，不能被目击。"}, {"text": "他常常目击小时候的生活。", "explanation": "这里应该用〈回忆〉。目击指亲眼看见某件事情发生，「小时候的生活」是一段生活状态，不是可以目击的事件，应说回忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷说他年轻时曾经目击了过一场大火。", "corrected_sentence": "爷爷说他年轻时曾经目击过一场大火。", "error_description": "错误：「目击了过」，「了」和「过」不能这样连用在「目击」后面。「曾经」表示经历，应只用「过」：「目击过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在桥上被目击了那只船沉没。", "corrected_sentence": "他在桥上目击了那只船沉没。", "error_description": "错误：「被」使「他」成为被看见的一方，但句中的「他」是看见船沉没的人。正确：去掉「被」，「他在桥上目击了那只船沉没」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
