INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去做自己说过要做的事。", "primary_collocate": null, "pronunciation": "jiàn xíng", "ipa": "tɕjɛn˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "说了要早起，就要践行。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他践行了自己的承诺，每天跑步。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说要帮我，现在该践行了。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直践行自己说过的话。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明践行了对妈妈的约定，没有玩手机。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有想法不行，还要去践行。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想践行新年的计划，每天读书。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说要节约用水，我先来践行。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他践行诺言，把钱还给了朋友。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友应该践行自己的承诺。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "践行了", "label": "完成体"}, {"form": "践行着", "label": "持续体"}, {"form": "践行过", "label": "经历体"}, {"form": "踐行", "label": "繁体"}], "register": "书面", "sense_fingerprint": "去做自己说过要做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：践行 jiàn xíng，意为去做自己说过要做的事。"}, {"text": "现行", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现行意思是当前施行的。"}, {"text": "现形", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现形意思是显露原形。"}, {"text": "减刑", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，后字 xíng 相同，减刑意思是减少刑期。"}], "explanations": {"践行": "正确：践行 jiàn xíng，意为去做自己说过要做的事。", "现行": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现行意思是当前施行的。", "现形": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现形意思是显露原形。", "减刑": "jiǎn（第三声）与 jiàn（第四声）声调不同，后字 xíng 相同，减刑意思是减少刑期。"}, "sentence_index": null, "correct_answer": "践行"}, "level_3": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：“践行”指去做自己说过要做的事，与“说了要……”相呼应。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”是违反，与“说了要早起，就要……”的要求相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“说了要早起”的承诺意图相反，句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“说了要早起”的承诺相反，句意不通。"}], "explanations": {"践行": "正确：“践行”指去做自己说过要做的事，与“说了要……”相呼应。", "违背": "语义：“违背”是违反，与“说了要早起，就要……”的要求相反。", "忘记": "语义：“忘记”与“说了要早起”的承诺意图相反，句意不通。", "放弃": "语义：“放弃”与“说了要早起”的承诺相反，句意不通。"}, "sentence_index": 0, "correct_answer": "践行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师要求我们在实验室里践行化学实验。", "explanation": "这里应该用〈进行〉。“践行”指把承诺、理念付诸行动，做实验要说“进行”。"}, {"text": "他终于践行了那道数学题。", "explanation": "这里应该用〈解〉。做数学题要说“解”；“践行”用于理念、承诺，不用于习题。"}, {"text": "小红今天践行了运动会。", "explanation": "这里应该用〈参加〉。运动会是要去参与的活动，要说“参加”；“践行”指把自己说过的事做到，不用于活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：“践行”指把计划付诸实际行动，与“每天读书”的做法相符。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”是毁坏，与“我想……新年的计划”的积极意愿相反。"}, {"text": "泄露", "is_correct": false, "explanation": "语义：“泄露”是让秘密外传，与计划要实施的意图不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“我想……”的积极意愿相反，句意不通。"}], "explanations": {"践行": "正确：“践行”指把计划付诸实际行动，与“每天读书”的做法相符。", "破坏": "语义：“破坏”是毁坏，与“我想……新年的计划”的积极意愿相反。", "泄露": "语义：“泄露”是让秘密外传，与计划要实施的意图不符。", "拒绝": "语义：“拒绝”与“我想……”的积极意愿相反，句意不通。"}, "sentence_index": 6, "correct_answer": "践行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于践行了那篇论文。", "explanation": "这里应该用〈发表〉。论文是书面成果，要说“发表”；“践行”指把说过的事做到，不用于文章。"}, {"text": "双方践行了友好的谈判。", "explanation": "这里应该用〈进行〉。“践行”用于理念、承诺，谈判要说“进行”。"}, {"text": "社区践行了一场义诊活动。", "explanation": "这里应该用〈开展〉。“践行”不用于一场具体的活动，活动要说“开展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把诺言践行很好。", "corrected_sentence": "她把诺言践行得很好。", "error_description": "错误：“践行”后缺少补语标记“得”。正确形式是“践行得很好”，“得”引出程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会这个承诺践行下去。", "corrected_sentence": "他会把这个承诺践行下去。", "error_description": "错误：宾语“这个承诺”位于动词前，缺少“把”字，应说“他会把这个承诺践行下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
