INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西做出来给别人看，让大家知道怎么做。", "primary_collocate": null, "pronunciation": "yǎn shì", "ipa": "jɛn˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈演示怎么包饺子。", "target_word": "演示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师演示了一遍，我就会了。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给孩子们演示怎么洗手。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练在场上演示正确的动作。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能给我演示一下吗？", "target_word": "演示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "店员当场演示了机器怎么用。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师把做鱼的方法演示给大家。", "target_word": "演示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在台上演示化妆的步骤。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸演示完，我自己试了试。", "target_word": "演示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王演示怎么用新手机。", "target_word": "演示", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "演示了", "label": "完成体"}, {"form": "演示过", "label": "经历体"}, {"form": "演示演示", "label": "重叠"}, {"form": "演示文稿", "label": "复合词"}], "register": "中性", "sense_fingerprint": "演示：亲手做一遍给别人看，让人学会做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演示", "is_correct": true, "explanation": "演示：亲手做一遍给别人看，让大家知道怎么做。"}, {"text": "厌世", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是厌恶世事。"}, {"text": "仰视", "is_correct": false, "explanation": "yǎng 与 yǎn 韵母不同（ang 与 an），意思是抬头向上看。"}, {"text": "验视", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，shì 相同，意思是检查、查看。"}], "explanations": {"演示": "演示：亲手做一遍给别人看，让大家知道怎么做。", "厌世": "yàn（第四声）与 yǎn（第三声）声调不同，意思是厌恶世事。", "仰视": "yǎng 与 yǎn 韵母不同（ang 与 an），意思是抬头向上看。", "验视": "yàn（第四声）与 yǎn（第三声）声调不同，shì 相同，意思是检查、查看。"}, "sentence_index": null, "correct_answer": "演示"}, "level_3": {"options": [{"text": "演示", "is_correct": true, "explanation": "正确：「演示」指亲手做给别人看，让人学会做法，符合「包饺子」的语境。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：「推翻」指否定或颠覆，与「做给人看」无关。"}, {"text": "吞咽", "is_correct": false, "explanation": "搭配：「吞咽」的动作针对食物，不能用于「怎么包饺子」。"}, {"text": "摔", "is_correct": false, "explanation": "配价：「摔」的受事是具体物体，不能带「怎么包饺子」这样的谓词性宾语。"}], "explanations": {"演示": "正确：「演示」指亲手做给别人看，让人学会做法，符合「包饺子」的语境。", "推翻": "语义：「推翻」指否定或颠覆，与「做给人看」无关。", "吞咽": "搭配：「吞咽」的动作针对食物，不能用于「怎么包饺子」。", "摔": "配价：「摔」的受事是具体物体，不能带「怎么包饺子」这样的谓词性宾语。"}, "sentence_index": 0, "correct_answer": "演示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿出证件，演示了自己的身份。", "explanation": "这里应该用〈出示〉。演示是把做法做给人看、让人学会；拿证件给人看要说出示。"}, {"text": "演员在台上演示了一段精彩的舞蹈。", "explanation": "这里应该用〈表演〉。演示是为了让人学会做法，供观赏的舞蹈要说表演。"}, {"text": "老师演示了那个不听话的孩子。", "explanation": "这里应该用〈批评〉。演示的对象是做法或动作，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演示", "is_correct": true, "explanation": "正确：「演示」指亲手做给大家看，让人学会做鱼的方法。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：「烧毁」指毁坏，与「让大家学会做法」正好相反。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：「清洗」的对象是器物或衣物，不能用于「方法」。"}, {"text": "冲撞", "is_correct": false, "explanation": "配价：「冲撞」不能带「给大家」的与事，也不能以「方法」为受事。"}], "explanations": {"演示": "正确：「演示」指亲手做给大家看，让人学会做鱼的方法。", "烧毁": "语义：「烧毁」指毁坏，与「让大家学会做法」正好相反。", "清洗": "搭配：「清洗」的对象是器物或衣物，不能用于「方法」。", "冲撞": "配价：「冲撞」不能带「给大家」的与事，也不能以「方法」为受事。"}, "sentence_index": 6, "correct_answer": "演示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把个人信息演示给了前台。", "explanation": "这里应该用〈登记〉。演示是把做法做给人看、让人学会，提交个人信息要说登记。"}, {"text": "他在朋友圈演示了自己的近况。", "explanation": "这里应该用〈公布〉。演示指亲手做出来给人看，告知近况要说公布。"}, {"text": "工人演示了那台坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。演示是把做法展示给人看，修好坏机器要说修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把做法演示完过，我才开始做。", "corrected_sentence": "他把做法演示完了，我才开始做。", "error_description": "错误：「演示完过」，动态助词「过」表示经历，不能与表示结束的结果补语「完」搭配。正确：「演示完了」，「了」表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师当着全班演示着一遍，同学们都学会了。", "corrected_sentence": "老师当着全班演示了一遍，同学们都学会了。", "error_description": "错误：「演示着一遍」，「着」表示动作持续，不能和表示完整次数的「一遍」连用。正确：「演示了一遍」，「了」表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
