INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人把一个东西给另一个人，同时另一个人也把一个东西给第一个人。", "primary_collocate": null, "pronunciation": "jiāo huàn", "ipa": "tɕjɑʊ˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "我和同桌交换了铅笔。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你给我苹果，我给你饼干，我们交换吧。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐和我交换了衣服穿。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在课间交换小卡片。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们互相交换了手机号。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明想用玩具车交换我的球。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好明天交换照片。", "target_word": "交换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新年时，同事们互相交换礼物。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的帽子和我的交换了。", "target_word": "交换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意和我交换座位吗？", "target_word": "交换", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "交换了", "label": "完成体"}, {"form": "交换过", "label": "经历体"}, {"form": "交换着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "交换：两人各把自己的东西给对方，彼此换得对方的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交换", "is_correct": true, "explanation": "交换：两人各把东西给对方，「交换铅笔」符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，铅笔不能吃，句意说不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」用于衣服、鞋袜，不能用于铅笔。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：「骑」用于自行车、马等交通工具或动物，不能用于铅笔。"}], "explanations": {"交换": "交换：两人各把东西给对方，「交换铅笔」符合句意。", "吃": "语义：「吃」指进食，铅笔不能吃，句意说不通。", "穿": "搭配：「穿」用于衣服、鞋袜，不能用于铅笔。", "骑": "搭配：「骑」用于自行车、马等交通工具或动物，不能用于铅笔。"}, "sentence_index": 0, "correct_answer": "交换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈交换了我的零花钱。", "explanation": "这里应该用〈没收〉。交换要求双方各给出东西，妈妈单方面拿走我的零花钱、我没有回报时应说没收。"}, {"text": "警察交换了他的玩具。", "explanation": "这里应该用〈没收〉。交换是双方互相给出东西，警察单方面拿走玩具应说没收。"}, {"text": "我向灾区交换了一批衣服。", "explanation": "这里应该用〈捐〉。交换是双方各给出东西，把衣服送给灾区而不求回报应说捐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交换", "is_correct": true, "explanation": "交换：指两人各给对方照片，「交换照片」符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」用于食物，不能用于照片。"}, {"text": "教", "is_correct": false, "explanation": "配价：「教」要求教的对象是人，「教照片」不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」用于歌曲、戏曲，照片不能唱。"}], "explanations": {"交换": "交换：指两人各给对方照片，「交换照片」符合句意。", "煮": "搭配：「煮」用于食物，不能用于照片。", "教": "配价：「教」要求教的对象是人，「教照片」不成立。", "唱": "搭配：「唱」用于歌曲、戏曲，照片不能唱。"}, "sentence_index": 6, "correct_answer": "交换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你愿意把座位交换给我，却不要任何回报吗？", "explanation": "这里应该用〈让〉。交换要求双方都给出东西，只是把座位让给对方而不要回报时应说让。"}, {"text": "你愿意交换我的座位，却什么也不给我吗？", "explanation": "这里应该用〈拿〉。交换要求双方都给出东西，只拿走对方的座位而自己不给时应说拿。"}, {"text": "我向同桌交换了一块橡皮，用完就还给他了。", "explanation": "这里应该用〈借〉。交换要求双方各给出东西，我只是暂时用同桌的橡皮、用完归还，没有给他任何东西，应说借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小华和弟弟交换着了一套玩具。", "corrected_sentence": "小华和弟弟交换了一套玩具。", "error_description": "错误：「交换着了」，「着」表示动作持续，与表示完成的「了」不能同时使用。正确：「交换了一套玩具」，只用「了」表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天交换着了贺卡。", "corrected_sentence": "他们昨天交换了贺卡。", "error_description": "错误：「交换着了」，「着」表示动作持续，与表示完成的「了」不能同时使用。正确：「交换了贺卡」，只用「了」表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开口", "is_correct": true, "explanation": "正确答案。“开口”指张口说话，与“静默”（不开口）相对。"}, {"text": "奔跑", "is_correct": false, "explanation": "“奔跑”是身体动作，与说话与否无关，没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指脑力活动，与“静默”不是反义关系。"}, {"text": "离开", "is_correct": false, "explanation": "“离开”指移动位置，与“静默”没有反义关系。"}], "correct_answer": "开口", "explanations": {"开口": "正确答案。“开口”指张口说话，与“静默”（不开口）相对。", "奔跑": "“奔跑”是身体动作，与说话与否无关，没有反义关系。", "思考": "“思考”指脑力活动，与“静默”不是反义关系。", "离开": "“离开”指移动位置，与“静默”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发言", "is_correct": true, "explanation": "正确答案。“发言”指公开讲话，与“静默”（不开口）相对。"}, {"text": "种花", "is_correct": false, "explanation": "“种花”是园艺劳动，与说不说话无关，没有反义关系。"}, {"text": "观望", "is_correct": false, "explanation": "“观望”指注视、等待，与“静默”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是步行的动作，与说话与否无关，没有反义关系。"}], "correct_answer": "发言", "explanations": {"发言": "正确答案。“发言”指公开讲话，与“静默”（不开口）相对。", "种花": "“种花”是园艺劳动，与说不说话无关，没有反义关系。", "观望": "“观望”指注视、等待，与“静默”没有反义关系。", "散步": "“散步”是步行的动作，与说话与否无关，没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不说话，不出声音。", "primary_collocate": null, "pronunciation": "jìng mò", "ipa": "tɕiŋ˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "听到坏消息，大家都静默了。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他静默了一会儿，才慢慢开口。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，全场静默三分钟。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对质问，她始终静默，没有回应。", "target_word": "静默", "complexity_tier": "T3", "furigana": "jìng mò", "sentence_source": "generated"}, {"text": "孩子们静默着，等老师说话。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低下头，一直静默不语。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问了几次，学生都静默着。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家为遇难者静默片刻。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸静默地听完，什么也没说。", "target_word": "静默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里的两个人都静默着，谁也没开口。", "target_word": "静默", "complexity_tier": "T3", "furigana": "jìng mò", "sentence_source": "generated"}], "morphological_forms": [{"form": "静默了", "label": "体标"}, {"form": "静默着", "label": "体标"}, {"form": "靜默", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人沉默下来，不开口说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静默", "is_correct": true, "explanation": "正确答案。“大家都静默了”指听到坏消息后大家都不出声。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：听到坏消息后欢呼与情境相反。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：听到坏消息后鼓掌不合情理。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”需要带对象，如“祝贺某人”，不能单独作谓语。"}], "explanations": {"静默": "正确答案。“大家都静默了”指听到坏消息后大家都不出声。", "欢呼": "语义：听到坏消息后欢呼与情境相反。", "鼓掌": "语义：听到坏消息后鼓掌不合情理。", "祝贺": "配价：“祝贺”需要带对象，如“祝贺某人”，不能单独作谓语。"}, "sentence_index": 0, "correct_answer": "静默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们静默着，一起大声念课文。", "explanation": "这里表示齐声念出，应该用〈齐声〉。“静默”指不开口，与念课文相反。"}, {"text": "会议上，他静默地发表了三十分钟演讲。", "explanation": "这里表示连续讲话，应该用〈滔滔不绝〉。“静默”指不开口，与三十分钟的演讲相反。"}, {"text": "他静默地抬头，大声喊了一句。", "explanation": "这里表示喊叫，应该用〈高喊〉。“静默”指不开口，与大声喊相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静默", "is_correct": true, "explanation": "正确答案。“学生都静默着”指学生在老师问话后都不作声。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是生理反应，不是对老师提问的回应。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：被反复追问时大笑与学生的反应不相符。"}, {"text": "举手", "is_correct": false, "explanation": "搭配：“举手”是动宾短语，不能直接与“都……着”组合成谓语。"}], "explanations": {"静默": "正确答案。“学生都静默着”指学生在老师问话后都不作声。", "咳嗽": "语义：咳嗽是生理反应，不是对老师提问的回应。", "大笑": "语义：被反复追问时大笑与学生的反应不相符。", "举手": "搭配：“举手”是动宾短语，不能直接与“都……着”组合成谓语。"}, "sentence_index": 6, "correct_answer": "静默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩静默地在操场上追逐打闹。", "explanation": "这里表示吵闹玩耍，应该用〈嬉闹〉。“静默”指不出声，与追逐打闹相反。"}, {"text": "电视里的主持人静默地播报着新闻。", "explanation": "这里表示开口讲述，应该用〈讲述〉。“静默”指不开口，不能用来形容播报新闻。"}, {"text": "大家一边吃饭，一边静默地热烈交谈。", "explanation": "这里表示吵闹，应该用〈喧哗〉。“静默”指不开口，与热烈交谈的场面相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直静默的不语，没有回答老师的问题。", "corrected_sentence": "他一直静默不语，没有回答老师的问题。", "error_description": "多加了“的”：“静默不语”是固定说法，“静默”后直接接“不语”，不用“的”；加“的”会把“静默”当作修饰语的形容词，这里不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她静默的低下了头，不说话。", "corrected_sentence": "她静默地低下了头，不说话。", "error_description": "修饰动词“低下”的状语应用“地”，写作“静默地低下”。用“的”会把“静默”当作形容词修饰名词，这里不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
