INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商店是卖东西的地方。", "primary_collocate": null, "pronunciation": "shāng diàn", "ipa": "ʂɑŋ˥ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家商店在地铁站旁边。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去商店买了一瓶水。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店几点关门？", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上有很多小商店。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的东西又好又便宜。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的人不多，我很快就买好了。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近新开了一家商店。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，商店都放假。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在商店里工作了三年。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家商店卖水果和蔬菜。", "target_word": "商店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家商店", "label": "量词：家"}], "register": "通用", "sense_fingerprint": "卖东西给顾客的店铺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商店", "is_correct": true, "explanation": "正确：“商店”是卖东西的地方，可以用“这家”来数，也能位于地铁站旁边。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“家”不用来数房间，厨房应说“这间”，而且厨房不是卖东西的地方。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不是做生意的场所，“这家墓地”与“卖东西”的意思不符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是场所，不能说“这家学生”在地铁站旁边。"}], "explanations": {"商店": "正确：“商店”是卖东西的地方，可以用“这家”来数，也能位于地铁站旁边。", "厨房": "搭配：“家”不用来数房间，厨房应说“这间”，而且厨房不是卖东西的地方。", "墓地": "语义：墓地不是做生意的场所，“这家墓地”与“卖东西”的意思不符。", "学生": "语义：学生是人，不是场所，不能说“这家学生”在地铁站旁边。"}, "sentence_index": 0, "correct_answer": "商店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上新开了一只商店。", "explanation": "这里应该用〈家〉。商店要用量词“家”，“只”一般用于动物或成对东西中的一个。"}, {"text": "我家门口有一条商店。", "explanation": "这里应该用〈家〉。“条”用于细长的东西，如河、路、裤子，不用来数商店。"}, {"text": "他想开一本商店。", "explanation": "这里应该用〈家〉。“本”用于书、本子等，不能用来数商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商店", "is_correct": true, "explanation": "正确：“新开了一家”说的是店铺，商店符合这里的语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能被“新开”，也不用“一家”来数。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：量词“家”不用来数木头，木头也不能被“新开”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被“新开”，“新开了一家天空”说不通。"}], "explanations": {"商店": "正确：“新开了一家”说的是店铺，商店符合这里的语境。", "老虎": "语义：老虎是动物，不能被“新开”，也不用“一家”来数。", "木头": "搭配：量词“家”不用来数木头，木头也不能被“新开”。", "天空": "语义：天空不能被“新开”，“新开了一家天空”说不通。"}, "sentence_index": 6, "correct_answer": "商店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月去商店剪一次头发。", "explanation": "这里应该用〈理发店〉。商店卖东西，剪头发要去理发店；“商店”不提供理发服务。"}, {"text": "这家商店可以开处方药，需要医生的单子。", "explanation": "这里应该用〈药店〉。处方药要凭医生处方在药店购买，普通商店一般不卖处方药。"}, {"text": "我每个月都去商店存钱。", "explanation": "这里应该用〈银行〉。商店卖东西，存钱要去银行；“商店”不办理存款业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我商店买了一瓶水。", "corrected_sentence": "我在商店买了一瓶水。", "error_description": "错误：表示地点的介词“在”漏掉了，“商店”后面直接接动词；正确：“在商店买了一瓶水”，表示动作发生的地点要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只商店每天晚上九点关门。", "corrected_sentence": "这家商店每天晚上九点关门。", "error_description": "量词错误：“商店”应用量词“家”，“只”一般用于动物或成对器物中的一个，不能修饰商店。正确说法是「这家商店每天晚上九点关门。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
