INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "国家定出大家都得遵守的规则。", "primary_collocate": null, "pronunciation": "lì fǎ", "ipa": "li˥˩ fa˨˩", "syllable_count": 2, "sentences": [{"text": "国家正在为保护环境立法。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家已经立法禁止在车里吸烟。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定立法保护儿童。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让网络更安全，国家要立法。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市去年立法禁止用塑料袋。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望国家尽快立法。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国会正在讨论要不要立法。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有立法，才能管住乱扔垃圾的人。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家立法保护老人的权利。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家应该立法禁止酒后开车。", "target_word": "立法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立法权", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家制定法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立法", "is_correct": true, "explanation": "立法：表示国家为保护环境制定法律，与句意一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是休闲活动，不能表示为保护环境制定法律。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“为保护环境”之后接“唱歌”搭配不当，句子说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "配价：“吃饭”不能接受“保护环境”作为对象，句子说不通。"}], "explanations": {"立法": "立法：表示国家为保护环境制定法律，与句意一致。", "散步": "语义：“散步”是休闲活动，不能表示为保护环境制定法律。", "唱歌": "搭配：“为保护环境”之后接“唱歌”搭配不当，句子说不通。", "吃饭": "配价：“吃饭”不能接受“保护环境”作为对象，句子说不通。"}, "sentence_index": 0, "correct_answer": "立法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交警每天在路上立法。", "explanation": "这里应该用〈执法〉。执法指依法执行法律；立法指制定法律，交警执行交通规定，不能说立法。"}, {"text": "警察立法调查这起事故。", "explanation": "这里应该用〈立案〉。立案指正式登记案件；立法指制定法律，警察调查事故不是制定法律。"}, {"text": "市民都应该立法。", "explanation": "这里应该用〈守法〉。守法指遵守法律；立法指制定法律，普通市民不进行立法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立法", "is_correct": true, "explanation": "立法：表示国会制定法律，与“讨论要不要”的语境吻合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：国会讨论的是法律事务，“游泳”这类个人活动不是立法讨论的对象。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“讨论要不要”之后接“跳舞”，国会不会讨论此类事项，搭配不当。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”不是国会讨论的事务，与句意不符。"}], "explanations": {"立法": "立法：表示国会制定法律，与“讨论要不要”的语境吻合。", "游泳": "语义：国会讨论的是法律事务，“游泳”这类个人活动不是立法讨论的对象。", "跳舞": "搭配：“讨论要不要”之后接“跳舞”，国会不会讨论此类事项，搭配不当。", "做饭": "语义：“做饭”不是国会讨论的事务，与句意不符。"}, "sentence_index": 6, "correct_answer": "立法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校立法禁止吸烟。", "explanation": "这里应该用〈规定〉。“规定”指学校、机构定下要遵守的要求，如“学校规定禁止吸烟”；“立法”只能由国家或立法机关进行，学校不能立法。"}, {"text": "法院负责立法审案。", "explanation": "这里应该用〈司法〉。司法指依法审判；法院审案属于司法，不是立法。"}, {"text": "班长应该立法维持纪律。", "explanation": "这里应该用〈立规矩〉。“立规矩”指为班级定下行为规范；“立法”专指国家制定法律，班长不能立法，应说“班长应该立规矩维持纪律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定立法法律保护野生动物。", "corrected_sentence": "政府决定立法保护野生动物。", "error_description": "错误在于多出“法律”。“立法”本身已经包含“法”，后面不能再带“法律”作宾语，应说“立法保护野生动物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国会很立法禁止在公共场所吸烟。", "corrected_sentence": "国会立法禁止在公共场所吸烟。", "error_description": "错误在于多出“很”。“很”不能修饰“立法”这类动作性词语，应删去，说“国会立法禁止……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
