INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25876, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看别人有没有做错事并管好他们。", "primary_collocate": null, "pronunciation": "jiān guǎn", "ipa": "tɕjɛn˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府监管市场。", "target_word": "监管", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "食品安全需要有人监管。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行由国家部门监管。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上网时，父母要监管。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司没有人监管，所以问题很多。", "target_word": "监管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在监管网上的价格。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的排水要由环保部门监管。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们成立了一个小组来监管工程质量。", "target_word": "监管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师监管着学生做实验，怕出危险。", "target_word": "监管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的生产必须严格监管。", "target_word": "监管", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "监管了", "label": "体标"}, {"form": "监管着", "label": "体标"}, {"form": "监管过", "label": "体标"}, {"form": "监管部门", "label": "复合词"}], "register": "正式", "sense_fingerprint": "监管：监督并管理，防止别人做错事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“市场”搭配，不能说“唱市场”。"}, {"text": "监管", "is_correct": true, "explanation": "“监管”指监督管理，政府对市场进行监督管理，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水去除污垢，与政府对市场的作用无关，句子说不通。"}, {"text": "尝", "is_correct": false, "explanation": "语义：“尝”指用口辨别滋味，无法用来说明政府与市场的关系。"}], "explanations": {"唱": "搭配：“唱”不与“市场”搭配，不能说“唱市场”。", "监管": "“监管”指监督管理，政府对市场进行监督管理，符合句意。", "洗": "语义：“洗”指用水去除污垢，与政府对市场的作用无关，句子说不通。", "尝": "语义：“尝”指用口辨别滋味，无法用来说明政府与市场的关系。"}, "sentence_index": 0, "correct_answer": "监管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生要监管病人的身体。", "explanation": "这里应该用〈检查〉。“监管”用于对行为、机构、市场等进行监督管理，不用来指对病人身体的检查。"}, {"text": "气象台每天都监管天气变化。", "explanation": "这里应该用〈监测〉。“监测”用于天气、水质等情况的观测，“监管”用于人的行为、机构和市场。"}, {"text": "我一直监管着窗外的那场雨。", "explanation": "这里应该用〈注视〉。“监管”表示监督管理，不表示视线停留在某物上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产", "is_correct": false, "explanation": "语义：环保部门负责监督管理，不生产排水，句子意思不通。"}, {"text": "监管", "is_correct": true, "explanation": "“监管”指监督管理，环保部门负责对排水进行监管，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象通常是饮品，不能与“排水”搭配。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热或燃烧，环保部门不会“烧”排水，句子说不通。"}], "explanations": {"生产": "语义：环保部门负责监督管理，不生产排水，句子意思不通。", "监管": "“监管”指监督管理，环保部门负责对排水进行监管，符合句意。", "喝": "搭配：“喝”的对象通常是饮品，不能与“排水”搭配。", "烧": "语义：“烧”指用火加热或燃烧，环保部门不会“烧”排水，句子说不通。"}, "sentence_index": 6, "correct_answer": "监管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都监管家里那只小猫。", "explanation": "这里不宜用“监管”。“监管”的对象是人的行为、机构或市场，不用于照料小动物，应该用〈照顾〉。"}, {"text": "妈妈在厨房里监管着那锅汤。", "explanation": "这里不宜用“监管”。“监管”不用于烹饪时照看食物，应该用〈看着〉。"}, {"text": "出门前，我监管了一下包里的钥匙。", "explanation": "这里应该用〈检查〉。“监管”是对人的行为、机构或市场进行监督管理，不用于看一看东西在不在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在监管了这家银行。", "corrected_sentence": "政府正在监管这家银行。", "error_description": "错误：“正在”表示动作正在进行，与表示完成的“了”不能同用。正确形式是“正在监管这家银行”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把食品监管。", "corrected_sentence": "政府把食品监管好了。", "error_description": "错误：“把”字句中动词后缺少补语，“政府把食品监管”语义不完整。正确形式是“把食品监管好了”，补语“好了”应接在“监管”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
