INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不用花钱就能得到。", "primary_collocate": null, "pronunciation": "miǎn fèi", "ipa": "mjɛn˨˩˦ fei˥˩", "syllable_count": 2, "sentences": [{"text": "这个公园不要钱，是免费的。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的图书馆对学生免费开放。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店今天送免费咖啡。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件是免费的，你可以放心用。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末博物馆免费，我们去看看吧。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上找到了一本免费的书。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院给老人做免费检查。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天下没有免费的午餐。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个应用打电话是免费的。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店提供免费早餐，不用另外付钱。", "target_word": "免费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "免費", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不用付钱就能得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "免费", "is_correct": true, "explanation": "“免费”指不用花钱，句中“不要钱，是免费的”符合句意。"}, {"text": "贵", "is_correct": false, "explanation": "语义：句子说不要钱，接“是贵的”前后矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“不要钱”与“昂贵”正相反，句意矛盾。"}, {"text": "有偿", "is_correct": false, "explanation": "搭配：“有偿”多用于服务、劳动，不用来形容公园，而且与“不要钱”矛盾。"}], "explanations": {"免费": "“免费”指不用花钱，句中“不要钱，是免费的”符合句意。", "贵": "语义：句子说不要钱，接“是贵的”前后矛盾。", "昂贵": "语义：“不要钱”与“昂贵”正相反，句意矛盾。", "有偿": "搭配：“有偿”多用于服务、劳动，不用来形容公园，而且与“不要钱”矛盾。"}, "sentence_index": 0, "correct_answer": "免费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把血免费卖给了医院。", "explanation": "这里应该用〈有偿〉。卖血是收钱的，与“免费”矛盾，应说“有偿”。"}, {"text": "这件衣服免费，只要五十块钱。", "explanation": "这里应该用〈便宜〉。说“免费”就是不收钱，和后面“只要五十块钱”矛盾；表示价格低要用“便宜”。"}, {"text": "他工作很免费，大家都喜欢他。", "explanation": "这里应该用〈认真〉。“免费”只表示不用花钱，不能用来形容一个人工作的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "免费", "is_correct": true, "explanation": "“免费”指不用花钱，句中医院给老人做检查不收钱，符合句意。"}, {"text": "业余", "is_correct": false, "explanation": "语义：医院的检查不是业余的，“业余检查”说不通。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”不修饰检查，不能说“年轻检查”。"}, {"text": "黑色", "is_correct": false, "explanation": "语义：检查没有颜色，“黑色检查”说不通。"}], "explanations": {"免费": "“免费”指不用花钱，句中医院给老人做检查不收钱，符合句意。", "业余": "语义：医院的检查不是业余的，“业余检查”说不通。", "年轻": "搭配：“年轻”不修饰检查，不能说“年轻检查”。", "黑色": "语义：检查没有颜色，“黑色检查”说不通。"}, "sentence_index": 6, "correct_answer": "免费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的知识免费卖给了公司。", "explanation": "这里应该用〈有偿〉。“免费”表示不用花钱，“卖”是收钱的，两者矛盾，应说“有偿”。"}, {"text": "这家超市的东西价格免费。", "explanation": "这里应该用〈实惠〉。形容价格低可以说“实惠”或“便宜”，“免费”指东西不收钱，不能修饰价格。"}, {"text": "他家的院子免费很大。", "explanation": "这里应该用〈宽敞〉。“免费”只表示不花钱，不能用来形容院子的大小，应说“很宽敞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件免费了使用。", "corrected_sentence": "这个软件免费使用。", "error_description": "体标位置错误：“了”不能插在状语“免费”与动词“使用”之间，应去掉“了”，说“免费使用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校每天给同学免费地午餐。", "corrected_sentence": "学校每天给同学免费的午餐。", "error_description": "结构助词错误：修饰名词“午餐”的定语要用“的”，“地”用于修饰动词，应说“免费的午餐”，不能说“免费地午餐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
