INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水把脏东西弄干净。", "primary_collocate": null, "pronunciation": "xǐ", "ipa": "ɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "水果吃以前一定要洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我周末在家洗衣服、打扫房间。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的鞋子脏了，爸爸帮他洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子我已经洗好了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你洗过这件毛衣吗？", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完碗以后，她坐下来看电视。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜要用清水洗两遍。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上有泥，快去洗一下。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脏袜子放进机器里洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗太脏了，我想把它洗一洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗了", "label": "体标"}, {"form": "洗过", "label": "体标"}, {"form": "洗洗", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用水把脏东西弄干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703d6979-3962-4484-92d2-882f13f16783') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水把脏东西弄干净。"}, {"text": "细", "is_correct": false, "explanation": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。"}, {"text": "吸", "is_correct": false, "explanation": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。"}, {"text": "西", "is_correct": false, "explanation": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。"}, {"text": "戏", "is_correct": false, "explanation": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水把脏东西弄干净。", "细": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。", "吸": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。", "西": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。", "戏": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“吃以前一定要洗”指用水把水果上的脏东西弄干净。"}, {"text": "煮", "is_correct": false, "explanation": "语义：水果一般不煮着吃，“吃以前一定要煮”与语境不合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：水果不用烧，“吃以前一定要烧”说不通。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”用于衣服鞋子，水果不能穿，“吃以前一定要穿”说不通。"}], "explanations": {"洗": "与句中“洗”相同，“吃以前一定要洗”指用水把水果上的脏东西弄干净。", "煮": "语义：水果一般不煮着吃，“吃以前一定要煮”与语境不合。", "烧": "语义：水果不用烧，“吃以前一定要烧”说不通。", "穿": "语义：“穿”用于衣服鞋子，水果不能穿，“吃以前一定要穿”说不通。"}, "sentence_index": 0, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用布洗灰尘。", "explanation": "这里应该用〈擦〉。“擦”用于灰尘、汗等，灰尘不能说“洗”。"}, {"text": "他把牛奶洗进了杯子里。", "explanation": "这里应该用〈倒〉。“倒”用于把液体从一处转到另一处；“洗”指用水把脏东西弄干净，不能表示把牛奶倒进杯子。"}, {"text": "妈妈在锅里洗粥，香喷喷的。", "explanation": "这里应该用〈煮〉。“煮”用于粥等食物，“洗粥”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水把脏东西弄干净。"}, {"text": "席", "is_correct": false, "explanation": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。"}, {"text": "系", "is_correct": false, "explanation": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。"}, {"text": "醒", "is_correct": false, "explanation": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水把脏东西弄干净。", "席": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。", "系": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。", "醒": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“用清水洗两遍”指用水把菜弄干净。"}, {"text": "炒", "is_correct": false, "explanation": "语义：炒要用油和火，不能只用清水，“用清水炒两遍”说不通。"}, {"text": "削", "is_correct": false, "explanation": "搭配：“削”多用于果皮、铅笔等，“用清水削两遍”搭配不上。"}, {"text": "绣", "is_correct": false, "explanation": "语义：绣要用针线，与用清水的清洁动作无关，“用清水绣”说不通。"}], "explanations": {"洗": "与句中“洗”相同，“用清水洗两遍”指用水把菜弄干净。", "炒": "语义：炒要用油和火，不能只用清水，“用清水炒两遍”说不通。", "削": "搭配：“削”多用于果皮、铅笔等，“用清水削两遍”搭配不上。", "绣": "语义：绣要用针线，与用清水的清洁动作无关，“用清水绣”说不通。"}, "sentence_index": 6, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用熨斗洗了一下皱巴巴的衬衫。", "explanation": "这里应该用〈熨〉。“熨”是用熨斗把衣服烫平，不用水；“洗”不能这样用。"}, {"text": "他在墙上洗了一层白粉，很快就干了。", "explanation": "这里应该用〈刷〉。“刷”用于把涂料、白粉等涂在墙面上，“洗”不能这样用。"}, {"text": "她在手腕上洗香水，很香。", "explanation": "这里应该用〈喷〉。“喷”用于香水等液体，“洗香水”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件毛衣我洗了过一次。", "corrected_sentence": "这件毛衣我洗过一次。", "error_description": "“洗过”是动词后加“过”表示经历，不能再加“了”，说“洗了过”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我帮你洗一下的手。", "corrected_sentence": "我帮你洗一下手。", "error_description": "动量词“一下”后不能直接加“的”修饰名词；“洗一下手”中“一下”是动量词，应说“洗一下手”，不能说“洗一下的手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
