INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "用来问别人或某处是不是有某样东西或某个人，即是否拥有或存在。", "primary_collocate": null, "pronunciation": "yǒu méi yǒu", "ipa": "jou˨˩˦ mei˧˥ jou˨˩˦", "syllable_count": 3, "sentences": [{"text": "你有没有手机？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问，你有没有笔？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你家有没有小狗？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师，你有没有时间？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有没有哥哥或者姐姐？", "target_word": "有没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们学校有没有游泳池？", "target_word": "有没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有没有钱，可以借我一点吗？", "target_word": "有没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里有没有人坐？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你有没有今天的作业？", "target_word": "有没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里有没有水果？", "target_word": "有没有", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "正反问：询问是否拥有或存在某物、某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有没有", "is_correct": true, "explanation": "正确。“有没有”用来问对方是否拥有某样东西，与“你……手机”搭配。"}, {"text": "是不是", "is_correct": false, "explanation": "语义：“是不是”用来问身份或判断，不能问对方是否有手机。"}, {"text": "吃不吃", "is_correct": false, "explanation": "搭配：“吃”的宾语要能吃，手机不能吃。"}, {"text": "咬不咬", "is_correct": false, "explanation": "搭配：“咬”的对象要能咬，手机不能用来咬。"}], "explanations": {"有没有": "正确。“有没有”用来问对方是否拥有某样东西，与“你……手机”搭配。", "是不是": "语义：“是不是”用来问身份或判断，不能问对方是否有手机。", "吃不吃": "搭配：“吃”的宾语要能吃，手机不能吃。", "咬不咬": "搭配：“咬”的对象要能咬，手机不能用来咬。"}, "sentence_index": 0, "correct_answer": "有没有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你有没有姓王？", "explanation": "这里应该用〈是不是〉。“有没有”用来问拥有或存在，问姓什么要用〈是不是姓王〉。"}, {"text": "这件事你有没有重要？", "explanation": "这里应该用〈重不重要〉。“有没有”用来问拥有或存在，问事情的重要性要用〈重不重要〉。"}, {"text": "你有没有是学生？", "explanation": "这里应该用〈是不是〉。“有没有”用来问拥有或存在，问身份要用〈是不是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有没有", "is_correct": true, "explanation": "正确。“有没有”用来问对方是否有钱，与“你……钱，可以借我一点”搭配。"}, {"text": "穿不穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物等，钱不能穿。"}, {"text": "喝不喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，钱不能喝。"}, {"text": "唱不唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，不能唱钱。"}], "explanations": {"有没有": "正确。“有没有”用来问对方是否有钱，与“你……钱，可以借我一点”搭配。", "穿不穿": "搭配：“穿”的对象是衣物等，钱不能穿。", "喝不喝": "搭配：“喝”的宾语是饮品，钱不能喝。", "唱不唱": "语义：唱的对象是歌曲，不能唱钱。"}, "sentence_index": 6, "correct_answer": "有没有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有没有可以进去？", "explanation": "这里应该用〈可不可以〉。“有没有”用来问拥有或存在，问是否允许进去要用〈可不可以〉。"}, {"text": "你为什么有没有来？", "explanation": "这里应该用〈为什么没来〉。“有没有”不能放在“为什么”后面问原因，应该说“你为什么没来”。"}, {"text": "他有没有几点到家？", "explanation": "这里应该用〈几点到家〉。“有没有”用来问拥有或存在，问到家的时间要直接说〈几点到家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你有没有一个哥哥吗？", "corrected_sentence": "你有没有一个哥哥？", "error_description": "疑问重复：“有没有”本身已经是问句，句末不能再加“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你今天有没有了空？", "corrected_sentence": "你今天有没有空？", "error_description": "了的误用：“有没有”后面不能加“了”，应说“你今天有没有空？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
