INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为买东西而支付钱款。", "primary_collocate": null, "pronunciation": "fù qián", "ipa": "fu˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我在商店挑好衣服，就去付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里很多人排队付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着水果去收银台付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我喜欢，我现在就去付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在菜市场买了菜，付钱后回家。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想拿走这些东西，请先付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了一双鞋，高兴地付钱了。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上买东西，也要先付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友拿出零钱，自己付钱买面包。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买这个杯子，请问在哪儿付钱？", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了钱", "label": "体标"}, {"form": "付过钱", "label": "体标"}], "register": "中性", "sense_fingerprint": "购物时用钱买下东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：挑好衣服后去付钱，表示买东西要支付钱款。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：挑衣服的人是买方，不是收钱的一方，不能说“收钱”。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：挑好衣服之后去睡觉，语义不连贯。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：挑好衣服之后去打扫，与在商店付钱的情境不符。"}], "explanations": {"付钱": "正确：挑好衣服后去付钱，表示买东西要支付钱款。", "收钱": "语义：挑衣服的人是买方，不是收钱的一方，不能说“收钱”。", "睡觉": "语义：挑好衣服之后去睡觉，语义不连贯。", "打扫": "语义：挑好衣服之后去打扫，与在商店付钱的情境不符。"}, "sentence_index": 0, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路边免费拿了一本书，又去付钱。", "explanation": "这里应该用〈领取〉。付钱指为买东西支付钱款，免费拿到的东西不需要付钱，句中用“付钱”不合理。"}, {"text": "老师把奖状发给了学生，学生又去付钱。", "explanation": "这里应该用〈颁发〉。付钱指为买东西支付钱款，奖状是学校颁发的，学生不需要付钱。"}, {"text": "我付钱了一封信给奶奶。", "explanation": "这里应该用〈寄〉。付钱指为买东西支付钱款，把信送给别人要说“寄信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：选好鞋子后高兴地付钱，符合买鞋的语境。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：高兴地烧掉鞋子，与买鞋的语境矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "配价：“吃掉”需要可吃的宾语，“鞋”不能被吃掉。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“高兴地摔碎”与常理相悖，鞋子也不会碎。"}], "explanations": {"付钱": "正确：选好鞋子后高兴地付钱，符合买鞋的语境。", "烧掉": "语义：高兴地烧掉鞋子，与买鞋的语境矛盾。", "吃掉": "配价：“吃掉”需要可吃的宾语，“鞋”不能被吃掉。", "摔碎": "语义：“高兴地摔碎”与常理相悖，鞋子也不会碎。"}, "sentence_index": 6, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "售货员付钱后给我装袋子。", "explanation": "这里应该用〈收〉。付钱的是买方，售货员是收钱的一方，不能说“付钱”。"}, {"text": "强盗抢钱时付了钱。", "explanation": "这里应该用〈抢〉。付钱指买东西时把钱给别人，强盗是把别人的钱拿走，不能说“付钱”。"}, {"text": "小偷偷东西时，也付了钱。", "explanation": "这里应该用〈偷〉。付钱指买东西时把钱给别人，小偷是偷偷拿走东西，不能说付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把想买的书拿到收银台，准备付了钱。", "corrected_sentence": "我把想买的书拿到收银台，准备付钱。", "error_description": "“准备”后接的是尚未发生的动作，不能用表示完成的“了”。“付”和“钱”之间多了“了”，应说“准备付钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网上挑中一件外套，然后很付钱。", "corrected_sentence": "我在网上挑中一件外套，然后去付钱。", "error_description": "“很”是程度副词，不能修饰“付钱”这类动作。此处应用趋向动词“去”，即“然后去付钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
