INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸袋是用纸做成的袋子，可以装东西。", "primary_collocate": null, "pronunciation": "zhǐ dài", "ipa": "ʈʂɻ̩˨˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "请给我一个纸袋，我要装水果。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸袋是用纸做的，比塑料袋环保。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从纸袋里拿出一块热面包。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的纸袋上有蓝色的图案。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧衣服装进纸袋，送给朋友。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸袋太小，放不下这个大盒子。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个黄色的纸袋送礼。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有个纸袋，里面是我的午饭。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用纸袋做了一顶小帽子。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸袋破了，苹果掉了一地。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个纸袋", "label": "量词"}, {"form": "紙袋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用纸做成、可以装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：请人“装水果”的容器，纸袋正符合这一语境。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不是用来装水果的容器，句意不通。"}, {"text": "皮球", "is_correct": false, "explanation": "语义：皮球是玩具，不能用来装水果。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果本身，不是用来装东西的容器，句意不通。"}], "explanations": {"纸袋": "正确：请人“装水果”的容器，纸袋正符合这一语境。", "鸡蛋": "语义：鸡蛋是食物，不是用来装水果的容器，句意不通。", "皮球": "语义：皮球是玩具，不能用来装水果。", "西瓜": "语义：西瓜是水果本身，不是用来装东西的容器，句意不通。"}, "sentence_index": 0, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一块纸袋，装了三个苹果。", "explanation": "这里应该用〈个〉。纸袋是立体的袋子，量词用“个”；“块”多用于块状的物体，不用于纸袋。"}, {"text": "他咬了一口纸袋，味道很甜。", "explanation": "这里应该用〈糖果〉。纸袋不能吃，“味道很甜”应用于食物，要说糖果。"}, {"text": "天冷了，他戴着纸袋去上班。", "explanation": "这里应该用〈口罩〉。“戴”用于口罩、帽子等，纸袋不能戴在脸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：“她买了一个黄色的”后面接的是可以用来送礼的袋子，纸袋最自然。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所是场所，不能买来送礼，句意荒谬。"}, {"text": "垃圾袋", "is_correct": false, "explanation": "语义：垃圾袋是用来装垃圾的，不能当作礼物送人。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是放垃圾的器具，不能当作礼物送人。"}], "explanations": {"纸袋": "正确：“她买了一个黄色的”后面接的是可以用来送礼的袋子，纸袋最自然。", "厕所": "语义：厕所是场所，不能买来送礼，句意荒谬。", "垃圾袋": "语义：垃圾袋是用来装垃圾的，不能当作礼物送人。", "垃圾桶": "语义：垃圾桶是放垃圾的器具，不能当作礼物送人。"}, "sentence_index": 6, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸袋刷牙，刷得很干净。", "explanation": "这里应该用〈牙刷〉。刷牙要用牙刷，纸袋不能用来刷牙。"}, {"text": "他用纸袋打开了门。", "explanation": "这里应该用〈钥匙〉。开门多用钥匙，纸袋不能用来开门。"}, {"text": "他用纸袋吃饭，吃得很香。", "explanation": "这里应该用〈筷子〉。吃饭要用筷子或勺子，纸袋不能用来吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把面包装进一张纸袋里。", "corrected_sentence": "妈妈把面包装进一个纸袋里。", "error_description": "量词错误：“纸袋”是立体的袋子，量词应用“个”，不能用平面物体的量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小弟弟把糖果装进纸袋上了。", "corrected_sentence": "小弟弟把糖果装进纸袋里了。", "error_description": "方位词错误：把东西装进袋子应说“纸袋里”，“上”表示在表面之上，不能说“纸袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
