INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "来买东西的人。", "primary_collocate": null, "pronunciation": "gù kè", "ipa": "ku˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "商店里有很多顾客。", "target_word": "顾客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位顾客想买一件红色的衣服。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员对顾客很热情。", "target_word": "顾客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "顾客说这个菜太咸了。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很关心每一位顾客。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天下雨，来买菜的顾客不多。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "顾客可以在网上看到商品的价格。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的顾客大多是附近的居民。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "顾客用完餐，服务员就来收盘子。", "target_word": "顾客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有位顾客把手机忘在了店里。", "target_word": "顾客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "老顾客", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：到商店或饭馆买东西、接受服务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25894, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顾客", "is_correct": true, "explanation": "正确：顾客指来买东西或接受服务的人。"}, {"text": "谷壳", "is_correct": false, "explanation": "gǔ（第三声）与 gù（第四声）声调不同，ké（第二声）与 kè（第四声）声调不同，意思是谷物的外壳。"}, {"text": "住客", "is_correct": false, "explanation": "zhù（第四声）与 gù 声母不同（zh 与 g），意思是住在酒店里的客人。"}, {"text": "过客", "is_correct": false, "explanation": "guò（第四声）与 gù 韵母不同（uo 与 u），意思是过路的人。"}, {"text": "录课", "is_correct": false, "explanation": "lù（第四声）与 gù 声母不同（l 与 g），意思是录制课程。"}], "explanations": {"顾客": "正确：顾客指来买东西或接受服务的人。", "谷壳": "gǔ（第三声）与 gù（第四声）声调不同，ké（第二声）与 kè（第四声）声调不同，意思是谷物的外壳。", "住客": "zhù（第四声）与 gù 声母不同（zh 与 g），意思是住在酒店里的客人。", "过客": "guò（第四声）与 gù 韵母不同（uo 与 u），意思是过路的人。", "录课": "lù（第四声）与 gù 声母不同（l 与 g），意思是录制课程。"}, "sentence_index": null, "correct_answer": "顾客"}, "level_3": {"options": [{"text": "顾客", "is_correct": true, "explanation": "正确：顾客指来商店买东西的人，与“商店里”搭配。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是看病的人，商店里不会有很多病人。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客指坐车的人，与商店的场景不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮挂在天上，商店里不会有很多月亮。"}], "explanations": {"顾客": "正确：顾客指来商店买东西的人，与“商店里”搭配。", "病人": "语义：病人是看病的人，商店里不会有很多病人。", "乘客": "语义：乘客指坐车的人，与商店的场景不符。", "月亮": "语义：月亮挂在天上，商店里不会有很多月亮。"}, "sentence_index": 0, "correct_answer": "顾客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家里来了顾客，妈妈很高兴。", "explanation": "这里应该用〈客人〉。顾客指来买东西或接受服务的人，到家里做客的人要说客人。"}, {"text": "公交车上的顾客都下车了。", "explanation": "这里应该用〈乘客〉。顾客指买东西、接受服务的人，坐车的人要说乘客。"}, {"text": "景区里的顾客特别多。", "explanation": "这里应该用〈游客〉。顾客指来店里买东西的人，到景区参观游览的人要说游客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顾客", "is_correct": true, "explanation": "正确：顾客可以在网上看到商品的价格，指购买商品的人。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木是植物，不能上网查看商品价格。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能上网，句子的主语无法完成这个动作。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会上网，无法看到商品的价格。"}], "explanations": {"顾客": "正确：顾客可以在网上看到商品的价格，指购买商品的人。", "树木": "语义：树木是植物，不能上网查看商品价格。", "石头": "语义：石头不能上网，句子的主语无法完成这个动作。", "黑板": "语义：黑板不会上网，无法看到商品的价格。"}, "sentence_index": 6, "correct_answer": "顾客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考场门口站满了顾客，大家都很紧张。", "explanation": "这里应该用〈考生〉。顾客指来买东西的人，参加考试的人要说考生。"}, {"text": "诊室里坐着几位顾客，都在等医生叫号。", "explanation": "这里应该用〈病人〉。顾客指来买东西的人，在诊室看病的人要说病人。"}, {"text": "投票站前排着长队，顾客们耐心地等着投票。", "explanation": "这里应该用〈选民〉。顾客指来买东西的人，去投票站投票的人要说选民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位顾客们走进了店里。", "corrected_sentence": "一位顾客走进了店里。", "error_description": "错误：“们”表示复数，不能与数量短语“一位”同用，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只顾客在柜台前等着。", "corrected_sentence": "两位顾客在柜台前等着。", "error_description": "错误：“只”用于动物或成对的东西，不能用来数人。这里应把“只”改为“位”，说“两位顾客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
