INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河流就是地上长长的、流动的水。", "primary_collocate": null, "pronunciation": "hé liú", "ipa": "xɤ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家有很多河流。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江是中国最长的河流。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流从山上流到海里。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雨多，河流里的水变多了。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地方的河流都很干净。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流两边种着很多树。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的蓝线是河流。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流给人们带来了水和鱼。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河流很长，我们走了一天。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里几乎没有河流。", "target_word": "河流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "地面上流动的天然水道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：说一个国家「有很多作业」不符合常理，与句意不合。"}, {"text": "公式", "is_correct": false, "explanation": "语义：公式是数学或科学的表达式，国家里不会「有很多公式」。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：国家不会“有很多眼睛”，句子说不通。"}, {"text": "河流", "is_correct": true, "explanation": "「河流」指地面流动的天然水道，国家里可以有很多，句子通顺。"}], "explanations": {"作业": "语义：说一个国家「有很多作业」不符合常理，与句意不合。", "公式": "语义：公式是数学或科学的表达式，国家里不会「有很多公式」。", "眼睛": "语义：国家不会“有很多眼睛”，句子说不通。", "河流": "「河流」指地面流动的天然水道，国家里可以有很多，句子通顺。"}, "sentence_index": 0, "correct_answer": "河流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在草地上看见了一朵河流。", "explanation": "这里应该用〈条〉。「朵」用于花，河流用「条」。"}, {"text": "河流上种满了柳树。", "explanation": "这里应该用〈河岸〉。「河流」指水道本身，柳树种在岸上，不能说种在河流上。"}, {"text": "今天下了一场大河流。", "explanation": "这里应该用〈大雨〉。「河流」指流动的水道，不能指从天而降的雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林", "is_correct": false, "explanation": "语义：地图上的蓝线表示水道，不是森林，句子不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：地图上的蓝线不会是数字，与句意矛盾。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：「眼睛」是人的器官，不能用来指地图上的线条。"}, {"text": "河流", "is_correct": true, "explanation": "「河流」是地图上蓝线所表示的水道，句意通顺。"}], "explanations": {"森林": "语义：地图上的蓝线表示水道，不是森林，句子不通。", "数字": "语义：地图上的蓝线不会是数字，与句意矛盾。", "眼睛": "语义：「眼睛」是人的器官，不能用来指地图上的线条。", "河流": "「河流」是地图上蓝线所表示的水道，句意通顺。"}, "sentence_index": 6, "correct_answer": "河流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的河流很肥沃。", "explanation": "这里应该用〈土地〉。「肥沃」形容土地，河流是水道，不能说肥沃。"}, {"text": "我们爬上河流看日出。", "explanation": "这里应该用〈高山〉。「爬上」用于高山、楼梯等有高度的地方，河流是水道，不能爬。"}, {"text": "我们吃完河流就去散步。", "explanation": "这里应该用〈饭〉。「吃」的对象是食物，河流是水道，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只河流穿过了整个城市。", "corrected_sentence": "这条河流穿过了整个城市。", "error_description": "「河流」是长条形的水道，量词应用「条」；「只」用于动物或成对的东西，此处误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片地区的河流们很多。", "corrected_sentence": "这片地区的河流很多。", "error_description": "「河流」不是指人的名词，不能加「们」，应说「这片地区的河流很多」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
