INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布做的袋子，可以装东西。", "primary_collocate": null, "pronunciation": "bù dài", "ipa": "pu˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我有一个旧布袋，里面装着书。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋是妈妈用旧衣服做的。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从布袋里拿出两个苹果。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把脏衣服放进布袋里。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋上有两根长带子，背起来很方便。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋太重，我一个人提不动。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用布袋装着花生去看朋友。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布袋可以洗，所以很环保。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的布袋里有铅笔和本子。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天农民把玉米装进大布袋。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个布袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "用布做成、可以装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：“旧布袋”里装着书，布袋是装东西的袋子，句意通顺。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不能用来装书。"}, {"text": "水瓶", "is_correct": false, "explanation": "语义：水瓶是盛水的，不适合用来装书。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的用具，里面不能装书，与“里面装着书”不合。"}], "explanations": {"布袋": "正确：“旧布袋”里装着书，布袋是装东西的袋子，句意通顺。", "花瓶": "语义：花瓶是用来插花的，不能用来装书。", "水瓶": "语义：水瓶是盛水的，不适合用来装书。", "雨伞": "语义：雨伞是挡雨的用具，里面不能装书，与“里面装着书”不合。"}, "sentence_index": 0, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把布袋，装满了玉米。", "explanation": "这里应该用〈个〉。布袋是立体的袋子，量词用“个”；“把”用于有柄或能握住的东西，不用于布袋。"}, {"text": "下雨了，他撑着布袋走在路上。", "explanation": "这里应该用〈伞〉。“撑”用于雨伞、阳伞，布袋不能撑。"}, {"text": "她用布袋写字，写得很整齐。", "explanation": "这里应该用〈笔〉。写字要用笔，布袋不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：“用……装着花生”需要容器，布袋正是用来装东西的。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“装”需要容器作工具，桌子不能用来装花生。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能拿来装花生。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：嘴是身体器官，不是盛装东西的器具。"}], "explanations": {"布袋": "正确：“用……装着花生”需要容器，布袋正是用来装东西的。", "桌子": "配价：“装”需要容器作工具，桌子不能用来装花生。", "窗户": "语义：窗户是建筑部件，不能拿来装花生。", "嘴": "语义：嘴是身体器官，不是盛装东西的器具。"}, "sentence_index": 6, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她穿着布袋去学校上课。", "explanation": "这里应该用〈鞋〉。“穿”用于鞋袜、衣服，布袋不能穿。"}, {"text": "奶奶用布袋煮面条，煮得很快。", "explanation": "这里应该用〈锅〉。煮面条要用锅，布袋不能下锅煮。"}, {"text": "她用布袋梳头，头发很整齐。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，布袋不能用来梳头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一张布袋装了花生。", "corrected_sentence": "她用一个布袋装了花生。", "error_description": "量词错误：布袋是立体的袋子，量词应用“个”，不能用平面物体的量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把钥匙放进布袋上了。", "corrected_sentence": "妈妈把钥匙放进布袋里了。", "error_description": "方位词错误：把东西放进袋子应说“布袋里”，“上”表示在表面之上，不能说“布袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
