INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情时按照规则或别人的要求来。", "primary_collocate": null, "pronunciation": "zūn shǒu", "ipa": "tswən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "玩游戏时要遵守规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们遵守老师的要求，排好队。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好了，你要遵守时间。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遵守了和妈妈的约定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆里，请遵守安静的要求。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人遵守医生的要求，按时吃药。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这里的人都要遵守小区的规矩。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个好学生，遵守所有的课堂规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都遵守约定，游戏才好玩。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸要求早睡，我遵守了。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遵守了", "label": "体标"}, {"form": "遵守着", "label": "体标"}, {"form": "遵守过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事时按规则、约定或他人要求来做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规则」表示玩游戏时依规则行事。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：「提高」用于水平、质量，不能说提高规则。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修补器物，不能用于规则。"}, {"text": "喂", "is_correct": false, "explanation": "配价：「喂」要求动物或人作对象，不能以「规则」作宾语。"}], "explanations": {"遵守": "正确。「遵守规则」表示玩游戏时依规则行事。", "提高": "搭配：「提高」用于水平、质量，不能说提高规则。", "修理": "语义：「修理」指修补器物，不能用于规则。", "喂": "配价：「喂」要求动物或人作对象，不能以「规则」作宾语。"}, "sentence_index": 0, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种植物遵守四季的变化开花。", "explanation": "这里应该用〈遵循〉。「遵守」用于规定、约定，自然变化的规律要用「遵循」。"}, {"text": "他终于遵守了自己的梦想。", "explanation": "这里应该用〈实现〉。「遵守」用于规则、约定，梦想要说「实现」。"}, {"text": "我们要遵守环境。", "explanation": "这里应该用〈保护〉。「遵守」的对象是规则、要求，保护环境要用「保护」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规矩」表示依照小区的规矩行事。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要求具体的物体作宾语，不能搬规矩。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧，与规矩无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指烹调食物，与规矩无关。"}], "explanations": {"遵守": "正确。「遵守规矩」表示依照小区的规矩行事。", "搬": "配价：「搬」要求具体的物体作宾语，不能搬规矩。", "烧": "语义：「烧」指燃烧，与规矩无关。", "煮": "语义：「煮」指烹调食物，与规矩无关。"}, "sentence_index": 6, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他遵守了老师的问题。", "explanation": "这里应该用〈回答〉。「遵守」的对象是规定、要求，回应问题要用「回答」。"}, {"text": "我遵守这幅画。", "explanation": "这里应该用〈欣赏〉。「遵守」用于规则、要求，欣赏艺术品要用「欣赏」。"}, {"text": "我们要遵守教室。", "explanation": "这里应该用〈打扫〉。「遵守」的对象是规定，打扫场所要用「打扫」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟没遵守了和我的约定。", "corrected_sentence": "弟弟没遵守和我的约定。", "error_description": "「没」否定动作时，动词后不能再加「了」。错误在“遵守”后面的“了”；应说「没遵守」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们遵守很好。", "corrected_sentence": "同学们遵守得很好。", "error_description": "动词带程度补语时，中间要加「得」。应说「遵守得很好」，不能说「遵守很好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
