INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25902, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很坏很危险。", "primary_collocate": null, "pronunciation": "yán zhòng", "ipa": "jɛn˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "昨晚的大雨造成了严重的水灾。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病很严重，要马上去医院。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的空气污染越来越严重。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题比你想的严重。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车祸不太严重，只有一个人受了伤。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了一个很严重的错误。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧很严重，妈妈一晚没睡。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的堵车问题十分严重。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，这座城市受到严重的破坏。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿伤得很严重，不能走路。", "target_word": "严重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚴重", "label": "繁体"}, {"form": "严重性", "label": "复合"}], "register": "中性", "sense_fingerprint": "情况、问题或伤病程度深，后果危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25902, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "严重", "is_correct": true, "explanation": "正确：严重 yán zhòng，程度深、情况危险，如「严重的水灾」。"}, {"text": "严正", "is_correct": false, "explanation": "严正 yán zhèng：zhèng 与 zhòng 韵母不同（eng 与 ong），意思是态度庄重、立场鲜明。"}, {"text": "严整", "is_correct": false, "explanation": "严整 yán zhěng：zhěng 与 zhòng 声调和韵母都不同，意思是严肃整齐。"}, {"text": "言中", "is_correct": false, "explanation": "言中 yán zhōng：zhōng（第一声）与 zhòng（第四声）声调不同，意思是话说中了。"}], "explanations": {"严重": "正确：严重 yán zhòng，程度深、情况危险，如「严重的水灾」。", "严正": "严正 yán zhèng：zhèng 与 zhòng 韵母不同（eng 与 ong），意思是态度庄重、立场鲜明。", "严整": "严整 yán zhěng：zhěng 与 zhòng 声调和韵母都不同，意思是严肃整齐。", "言中": "言中 yán zhōng：zhōng（第一声）与 zhòng（第四声）声调不同，意思是话说中了。"}, "sentence_index": null, "correct_answer": "严重"}, "level_3": {"options": [{"text": "严重", "is_correct": true, "explanation": "正确：「严重」修饰「水灾」，表示灾害程度深。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：「幸福」表示美好的感受，与「水灾」的灾害义相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」形容外表好看，不能修饰「水灾」。"}, {"text": "安静", "is_correct": false, "explanation": "语义：「安静」指没有声音或动静，与「水灾」的灾害义冲突。"}], "explanations": {"严重": "正确：「严重」修饰「水灾」，表示灾害程度深。", "幸福": "语义：「幸福」表示美好的感受，与「水灾」的灾害义相反。", "漂亮": "体貌：「漂亮」形容外表好看，不能修饰「水灾」。", "安静": "语义：「安静」指没有声音或动静，与「水灾」的灾害义冲突。"}, "sentence_index": 0, "correct_answer": "严重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的球技很严重。", "explanation": "这里应该用〈厉害〉。严重说情况或伤病很坏，不用来夸人的球技。"}, {"text": "双方的讨论很严重。", "explanation": "这里应该用〈激烈〉。严重说情况坏，讨论的热烈程度要用激烈。"}, {"text": "他的手艺很严重。", "explanation": "这里应该用〈高超〉。严重不用来评价手艺，手艺好要用高超。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严重", "is_correct": true, "explanation": "正确：「严重」说明发烧的程度深。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」指人多、吵闹，不能描述发烧的病情。"}, {"text": "好看", "is_correct": false, "explanation": "体貌：「好看」描述外貌，发烧是身体状况，不能用外貌词。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」指不费力，与发烧的病情相反。"}], "explanations": {"严重": "正确：「严重」说明发烧的程度深。", "热闹": "语义：「热闹」指人多、吵闹，不能描述发烧的病情。", "好看": "体貌：「好看」描述外貌，发烧是身体状况，不能用外貌词。", "轻松": "语义：「轻松」指不费力，与发烧的病情相反。"}, "sentence_index": 6, "correct_answer": "严重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的服务很严重。", "explanation": "这里应该用〈周到〉。严重说情况坏，服务的细致程度要用周到。"}, {"text": "这个书包很严重，我背不动。", "explanation": "这里应该用〈沉重〉。严重指程度深，描述东西的重量要用沉重。"}, {"text": "这次考试的分数很严重。", "explanation": "这里应该用〈糟糕〉。严重强调程度深、后果危险，不直接用来评价分数的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他得了很严重病，需要马上住院。", "corrected_sentence": "他得了很严重的病，需要马上住院。", "error_description": "错误：「很严重病」。正确：「很严重的病」。形容词短语修饰名词时，中间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说地很严重，我们都很担心。", "corrected_sentence": "妈妈说得很严重，我们都很担心。", "error_description": "错误：「说地很严重」。正确：「说得很严重」。状态补语要用「得」连接动词和补语，「地」用在动词前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱。"}, {"text": "下载", "is_correct": false, "explanation": "下载指把文件存到自己的设备上，与“付费”没有反义关系。"}, {"text": "点赞", "is_correct": false, "explanation": "点赞指表示喜欢，与“付费”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看指看视频或节目，与“付费”不是反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱。", "下载": "下载指把文件存到自己的设备上，与“付费”没有反义关系。", "点赞": "点赞指表示喜欢，与“付费”没有反义关系。", "观看": "观看指看视频或节目，与“付费”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱。"}, {"text": "分享", "is_correct": false, "explanation": "分享指与别人共同使用，与“付费”不是反义关系。"}, {"text": "评论", "is_correct": false, "explanation": "评论指发表看法，与“付费”没有反义关系。"}, {"text": "转发", "is_correct": false, "explanation": "转发指把内容传给别人，与“付费”没有反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱。", "分享": "分享指与别人共同使用，与“付费”不是反义关系。", "评论": "评论指发表看法，与“付费”没有反义关系。", "转发": "转发指把内容传给别人，与“付费”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付钱才能得到东西。", "primary_collocate": null, "pronunciation": "fù fèi", "ipa": "fu˥˩ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个游戏要付费才能玩。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这门网课需要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想听全部的歌，就要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不付费的人只能看前十分钟。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想付费，所以只看免费的视频。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月付费听音乐。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡馆的无线网络不用付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付费以后，你会收到一个密码。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的小火车要付费，大门不用。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票要付费才能进，朋友替我付费，我很不好意思。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了费", "label": "体标"}, {"form": "付过费", "label": "体标"}, {"form": "付費", "label": "繁体"}, {"form": "付费会员", "label": "复合"}], "register": "中性", "sense_fingerprint": "先付钱才能使用或得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“这个游戏要付费才能玩”指先交钱才能玩，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记不是玩游戏的条件，与“玩”的意思不符。"}, {"text": "退出", "is_correct": false, "explanation": "语义：退出游戏就不能玩了，与“才能玩”的意思矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“要洗澡才能玩”搭配不通，洗澡与游戏没有关系。"}], "explanations": {"付费": "正确。“这个游戏要付费才能玩”指先交钱才能玩，符合句意。", "忘记": "语义：忘记不是玩游戏的条件，与“玩”的意思不符。", "退出": "语义：退出游戏就不能玩了，与“才能玩”的意思矛盾。", "洗澡": "搭配：“要洗澡才能玩”搭配不通，洗澡与游戏没有关系。"}, "sentence_index": 0, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每年清明都向烈士付费。", "explanation": "这里应该用〈缅怀〉。付费指交钱获得服务，向烈士表达敬意不能用付费。"}, {"text": "他说错了话，就向朋友付费。", "explanation": "这里应该用〈道歉〉。说错话要向朋友道歉；付费指交钱获得东西或服务，不能表示认错。"}, {"text": "他在超市门口捡到一把伞，就付费还给了失主。", "explanation": "这里应该用〈归还〉。付费指为获得商品或服务交钱，把捡到的东西还给失主是无偿的，不能说付费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“无线网络不用付费”指不用交钱，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与无线网络无关，句子说的是网络的收费情况。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：网络不会发烧，“无线网络不用发烧”搭配不通。"}, {"text": "讲笑话", "is_correct": false, "explanation": "语义：讲笑话与无线网络的收费无关，句意不通。"}], "explanations": {"付费": "正确。“无线网络不用付费”指不用交钱，符合句意。", "散步": "语义：散步与无线网络无关，句子说的是网络的收费情况。", "发烧": "搭配：网络不会发烧，“无线网络不用发烧”搭配不通。", "讲笑话": "语义：讲笑话与无线网络的收费无关，句意不通。"}, "sentence_index": 6, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树要付费才能长大。", "explanation": "搭配：树不能付费，“付费”的主体应是人或机构，搭配不通。"}, {"text": "他每天付费上班，很辛苦。", "explanation": "搭配：上班是劳动并领取工资，不是付费获得的服务，“付费上班”搭配不通。"}, {"text": "她很高兴，因为朋友付费夸了她。", "explanation": "搭配：〈夸〉不是可以付费获得的服务，“付费夸”搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你付费过以后，就能看全部内容。", "corrected_sentence": "你付过费以后，就能看全部内容。", "error_description": "体标位置错误：“过”应紧跟动词，应说“付过费”，不能放在“付费”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "付费完的人可以进去。", "corrected_sentence": "付完费的人可以进去。", "error_description": "结果补语位置错误：“完”应紧跟动词，应说“付完费”，不能说“付费完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
