INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25906, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只能用一次、用完就扔的。", "primary_collocate": null, "pronunciation": "yí cì xìng", "ipa": "i˧˥ tsʰɹ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "饭馆里的一次性筷子用完就扔。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢用一次性杯子，太浪费了。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带了一次性手套去打扫房间。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的一次性餐具很便宜。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里用的一次性口罩每天都要换。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要用一次性塑料袋，对环境不好。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野餐的时候，我们用一次性盘子。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种一次性雨衣只能穿一次。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅馆给客人准备了一次性拖鞋。", "target_word": "一次性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次性筷子用的木头太多了，我们应该少用。", "target_word": "一次性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次性用品", "label": "复合"}, {"form": "一次性筷子", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：只能用一次、用完就扔的（一次性筷子）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐用", "is_correct": false, "explanation": "语义：“耐用”指能长期使用，与后半句“用完就扔”矛盾。"}, {"text": "一次性", "is_correct": true, "explanation": "“一次性”指用一次就扔，与“用完就扔”相符。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”用于人或身体，不用于形容筷子。"}, {"text": "永久", "is_correct": false, "explanation": "语义：“永久”指长久不变，与“用完就扔”矛盾。"}], "explanations": {"耐用": "语义：“耐用”指能长期使用，与后半句“用完就扔”矛盾。", "一次性": "“一次性”指用一次就扔，与“用完就扔”相符。", "健康": "搭配：“健康”用于人或身体，不用于形容筷子。", "永久": "语义：“永久”指长久不变，与“用完就扔”矛盾。"}, "sentence_index": 0, "correct_answer": "一次性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找到了一个一次性住处。", "explanation": "这里应该用〈临时〉。“一次性”指用完即弃的物品，不能修饰住处；暂时住的地方要说“临时住处”。"}, {"text": "这是一件一次性的古董。", "explanation": "这里应该用〈珍贵〉。“一次性”指用完即弃的东西，古董要长久保存，不能说一次性的。"}, {"text": "这是我们一次性的办公地点。", "explanation": "这里应该用〈暂时〉。“一次性”指用完即弃的东西，办公地点不能用它来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，盘子不能说苗条。"}, {"text": "一次性", "is_correct": true, "explanation": "“一次性”指用一次就扔，野餐时用纸盘、塑料盘很常见。"}, {"text": "珍稀", "is_correct": false, "explanation": "语域：“珍稀”属书面语，多指动植物或文物，不用于日常的盘子。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或动物的身材，不用于形容盘子。"}], "explanations": {"苗条": "体貌：“苗条”形容人的身材，盘子不能说苗条。", "一次性": "“一次性”指用一次就扔，野餐时用纸盘、塑料盘很常见。", "珍稀": "语域：“珍稀”属书面语，多指动植物或文物，不用于日常的盘子。", "矮小": "体貌：“矮小”形容人或动物的身材，不用于形容盘子。"}, "sentence_index": 6, "correct_answer": "一次性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了一台一次性的洗衣机。", "explanation": "这里应该用〈耐用〉。“一次性”指用完即弃，不能修饰需要长期使用的洗衣机。"}, {"text": "他在教室里有一个一次性的座位。", "explanation": "这里应该用〈固定〉。“一次性”指用完即弃的东西，座位不是用完就扔的。"}, {"text": "他们之间有一次性的友谊。", "explanation": "这里应该用〈长久〉。“一次性”指用完即弃，不能修饰需要长期维持的友谊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双筷子是一次性。", "corrected_sentence": "这双筷子是一次性的。", "error_description": "错误：“一次性”作谓语时要带“的”，应说“是一次性的”，不能说“是一次性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些餐具都是很一次性的。", "corrected_sentence": "这些餐具都是一次性的。", "error_description": "程度副词错误：“一次性”是非程度形容词，不能用“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
