INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大自然中本就存在、可供人类利用的东西，如水、树木、石头。", "primary_collocate": null, "pronunciation": "zì rán zī yuán", "ipa": "tsz̩⁵¹ ʐan³⁵ tsz̩⁵⁵ ɥɛn³⁵", "syllable_count": 4, "sentences": [{"text": "水、树木和石头都是自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里有很多自然资源，像树和水。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树木是自然资源，可以做桌子和椅子。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，空气和阳光也是自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要爱护身边的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的石头很多，是很好的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有自然资源，人就不能生活。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友，水是最重要的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的树是我们的自然资源。", "target_word": "自然资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大自然给了我们水、土地和很多自然资源。", "target_word": "自然资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大自然里的具体东西，如水、树木、石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然资源", "is_correct": true, "explanation": "填入“自然资源”：水、树木和石头都属于大自然里的东西，正是“自然资源”的所指。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：水、树木和石头不是垃圾，说它们“都是垃圾”与事实和句意相反。"}, {"text": "机器", "is_correct": false, "explanation": "语义：水、树木和石头不是机器，“都是机器”明显不符事实。"}, {"text": "污染", "is_correct": false, "explanation": "搭配：“污染”是一种状况，不能作为“都是”后面的类别名词，句子不通。"}], "explanations": {"自然资源": "填入“自然资源”：水、树木和石头都属于大自然里的东西，正是“自然资源”的所指。", "垃圾": "语义：水、树木和石头不是垃圾，说它们“都是垃圾”与事实和句意相反。", "机器": "语义：水、树木和石头不是机器，“都是机器”明显不符事实。", "污染": "搭配：“污染”是一种状况，不能作为“都是”后面的类别名词，句子不通。"}, "sentence_index": 0, "correct_answer": "自然资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂生产的是自然资源。", "explanation": "这里应该用〈工业产品〉。自然资源是大自然里本来就有的东西，工厂不能生产它们。"}, {"text": "工人在做自然资源。", "explanation": "这里应该用〈家具〉。自然资源是大自然里原有的东西，不是工人做出来的。"}, {"text": "汽车是一种自然资源。", "explanation": "这里应该用〈交通工具〉。汽车是人造的，不属于大自然里的东西，不是自然资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然资源", "is_correct": true, "explanation": "填入“自然资源”：没有它人就不能生活，正是自然界中人类必需的物质和能量，与句意相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是人生存所必需的，“没有黑板，人就不能生活”不符合事实。"}, {"text": "唱片", "is_correct": false, "explanation": "语义：唱片是娱乐用品，不是生存必需的，“没有唱片，人就不能生活”句子不成立。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“手术”是特定的治疗行为，不是人生存所需的物质，不能用“没有……人就不能生活”来说。"}], "explanations": {"自然资源": "填入“自然资源”：没有它人就不能生活，正是自然界中人类必需的物质和能量，与句意相符。", "黑板": "语义：黑板不是人生存所必需的，“没有黑板，人就不能生活”不符合事实。", "唱片": "语义：唱片是娱乐用品，不是生存必需的，“没有唱片，人就不能生活”句子不成立。", "手术": "搭配：“手术”是特定的治疗行为，不是人生存所需的物质，不能用“没有……人就不能生活”来说。"}, "sentence_index": 6, "correct_answer": "自然资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们的房间里有很多自然资源。", "explanation": "这里应该用〈玩具〉。自然资源是大自然里的东西，不是玩具，不能放在房间里让孩子玩。"}, {"text": "学生每天都背自然资源。", "explanation": "这里应该用〈课本〉。自然资源是物质，不是可以背诵的书籍。"}, {"text": "妈妈穿着漂亮的自然资源。", "explanation": "这里应该用〈服装〉。自然资源不是衣服，不能拿来穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂不应该随意把浪费自然资源。", "corrected_sentence": "工厂不应该随意浪费自然资源。", "error_description": "多出一个“把”字：“把”字句应为“把+处置对象+动词”，此处“把”后直接接动词“浪费”，结构不成立；删去“把”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不应该浪费的自然资源。", "corrected_sentence": "我们不应该浪费自然资源。", "error_description": "多了一个“的”：动词“浪费”直接带宾语“自然资源”，中间不能加“的”，删去“的”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
