INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让做某事。", "primary_collocate": null, "pronunciation": "jìn zhǐ", "ipa": "tɕin˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校禁止学生在教室里吃东西。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里禁止停车，请把车开走。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里禁止大声说话。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈禁止我晚上玩手机。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司禁止员工上班时睡觉。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上禁止使用手机打电话。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师禁止我们在考试时说话。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园禁止带狗进来。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生禁止他喝酒，他只好喝茶。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里禁止游泳，因为水很深。", "target_word": "禁止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁止了", "label": "完成体"}, {"form": "禁止过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "用规定或命令不让别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正确答案：禁止 jìn zhǐ，意思是不让做某事。"}, {"text": "静止", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（-ng 与 -n），静止意思是不动，与“不让做某事”无关。"}, {"text": "紧致", "is_correct": false, "explanation": "jǐn 与 jìn 声调不同，zhì 与 zhǐ 声调不同，紧致意思是紧密结实。"}, {"text": "信纸", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j），信纸意思是写信用的纸。"}], "explanations": {"禁止": "正确答案：禁止 jìn zhǐ，意思是不让做某事。", "静止": "jìng 与 jìn 韵尾不同（-ng 与 -n），静止意思是不动，与“不让做某事”无关。", "紧致": "jǐn 与 jìn 声调不同，zhì 与 zhǐ 声调不同，紧致意思是紧密结实。", "信纸": "xìn 与 jìn 声母不同（x 与 j），信纸意思是写信用的纸。"}, "sentence_index": null, "correct_answer": "禁止"}, "level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正确：“禁止”表示不许学生做某事，与“学校”作为规定者的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不能用来表示学校不许学生吃东西。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量或程度的增多，不能接“学生在教室里吃东西”这类行为。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的宾语是地点或展览，“学生吃东西”不能作参观的对象。"}], "explanations": {"禁止": "正确：“禁止”表示不许学生做某事，与“学校”作为规定者的语境相符。", "欣赏": "语义：“欣赏”指赏识美好的事物，不能用来表示学校不许学生吃东西。", "增加": "搭配：“增加”说的是数量或程度的增多，不能接“学生在教室里吃东西”这类行为。", "参观": "语义：“参观”的宾语是地点或展览，“学生吃东西”不能作参观的对象。"}, "sentence_index": 0, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看到有人打架，立刻上去禁止他们。", "explanation": "这里应该用〈制止〉。制止指当场阻拦正在进行的行为；禁止是用规定或命令不让人做某事，不用于当场阻拦。"}, {"text": "大雨禁止了我们出门。", "explanation": "这里应该用〈阻止〉。禁止的施事应是能下规定或命令的人，大雨不能下令；阻止可以用于自然现象。"}, {"text": "我禁止了他的邀请。", "explanation": "这里应该用〈拒绝〉。禁止是不让做某事，不用于回绝别人的邀请或请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25912, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正确答案：禁止 jìn zhǐ，意思是不让做某事。"}, {"text": "尽职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，尽职意思是尽到自己的职责。"}, {"text": "进制", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，进制意思是进位的制度，如二进制。"}, {"text": "金纸", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，金纸意思是金色的纸，多用于祭祀。"}], "explanations": {"禁止": "正确答案：禁止 jìn zhǐ，意思是不让做某事。", "尽职": "zhí（第二声）与 zhǐ（第三声）声调不同，尽职意思是尽到自己的职责。", "进制": "zhì（第四声）与 zhǐ（第三声）声调不同，进制意思是进位的制度，如二进制。", "金纸": "jīn（第一声）与 jìn（第四声）声调不同，金纸意思是金色的纸，多用于祭祀。"}, "sentence_index": null, "correct_answer": "禁止"}, "level_3": {"options": [{"text": "禁止", "is_correct": true, "explanation": "正确：“禁止”表示老师不许学生做某事，与“考试时说话”的规定语境相符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”指使人宽心，与考试期间不许讲话的规定语境不合。"}, {"text": "测验", "is_correct": false, "explanation": "配价：“测验”的宾语是知识或能力，不能以“说话”这类行为作宾语。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”通常接人或建议，不接“在考试时说话”这种违反纪律的行为。"}], "explanations": {"禁止": "正确：“禁止”表示老师不许学生做某事，与“考试时说话”的规定语境相符。", "安慰": "语义：“安慰”指使人宽心，与考试期间不许讲话的规定语境不合。", "测验": "配价：“测验”的宾语是知识或能力，不能以“说话”这类行为作宾语。", "欢迎": "搭配：“欢迎”通常接人或建议，不接“在考试时说话”这种违反纪律的行为。"}, "sentence_index": 6, "correct_answer": "禁止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了禁止事故，工厂每周都要检查设备。", "explanation": "这里应该用〈防止〉。禁止的对象是人的行为，不能以事故这类事件作宾语；防止用于防范事情发生。"}, {"text": "这种药能禁止头痛。", "explanation": "这里应该用〈缓解〉。禁止用于制止人的行为，不能用来减轻头痛这类症状；缓解指使症状减轻。"}, {"text": "政府禁止了这片森林。", "explanation": "这里应该用〈保护〉。禁止后面接的是人的行为，不能以森林这类地方作宾语；保护指照顾并使其免受破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游泳池里禁止不跳水。", "corrected_sentence": "游泳池里禁止跳水。", "error_description": "错误：“禁止不跳水”。正确：“禁止跳水”。“禁止”本身已含否定，句中再加“不”成为双重否定，意思颠倒，应删去“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站里很禁止吸烟。", "corrected_sentence": "车站里禁止吸烟。", "error_description": "错误：“很禁止吸烟”。正确：“禁止吸烟”。“很”一般修饰形容词，不直接修饰“禁止”这类动作动词，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
