INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吸管是用来喝饮料的管子。", "primary_collocate": null, "pronunciation": "xī guǎn", "ipa": "ɕi˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我喝可乐的时候喜欢用吸管。", "target_word": "吸管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根吸管是红色的，很长。", "target_word": "吸管", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "宝宝刚学会用吸管喝水。", "target_word": "吸管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吸管里还有一点饮料。", "target_word": "吸管", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她用吸管喝完了杯子里的最后一点果汁。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买奶茶时，店员给了我一根粗吸管。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟对着吸管吹气，杯子里出现很多泡泡。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的吸管是用纸做的。", "target_word": "吸管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝完奶茶，请把吸管放进垃圾桶。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷躺在床上，只能用吸管喝水。", "target_word": "吸管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "塑料吸管", "label": "复合"}, {"form": "纸吸管", "label": "复合"}], "register": "中性", "sense_fingerprint": "喝饮料时用的细管子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管（xī guǎn）是中空的细管，用来吸取饮料。"}, {"text": "习惯", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，guàn（第四声）与 guǎn（第三声）声调也不同，意思是习惯。"}, {"text": "戏馆", "is_correct": false, "explanation": "声调混淆：xì guǎn 与 xī guǎn 仅首音节声调不同，意思是戏院。"}, {"text": "西关", "is_correct": false, "explanation": "声调混淆：xī guān 与 xī guǎn 仅第二音节声调不同；西关是地名（如广州西关）。"}], "explanations": {"吸管": "正确：吸管（xī guǎn）是中空的细管，用来吸取饮料。", "习惯": "xí（第二声）与 xī（第一声）声调不同，guàn（第四声）与 guǎn（第三声）声调也不同，意思是习惯。", "戏馆": "声调混淆：xì guǎn 与 xī guǎn 仅首音节声调不同，意思是戏院。", "西关": "声调混淆：xī guān 与 xī guǎn 仅第二音节声调不同；西关是地名（如广州西关）。"}, "sentence_index": null, "correct_answer": "吸管"}, "level_3": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管是喝饮料时用的细管，句子说喝可乐时用的正是它。"}, {"text": "筷子", "is_correct": false, "explanation": "体貌：筷子是实心的细条，无法把可乐吸进嘴里，与“喝可乐”的语境不符。"}, {"text": "纸巾", "is_correct": false, "explanation": "语义：纸巾是用来擦东西的，不是喝饮料时使用的器具。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子用来盛放食物，不能用来喝可乐。"}], "explanations": {"吸管": "正确：吸管是喝饮料时用的细管，句子说喝可乐时用的正是它。", "筷子": "体貌：筷子是实心的细条，无法把可乐吸进嘴里，与“喝可乐”的语境不符。", "纸巾": "语义：纸巾是用来擦东西的，不是喝饮料时使用的器具。", "盘子": "语义：盘子用来盛放食物，不能用来喝可乐。"}, "sentence_index": 0, "correct_answer": "吸管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把牛奶倒进吸管里。", "explanation": "这里应该用〈瓶子〉。吸管是细管，不能用来盛装牛奶，应说倒进瓶子里。"}, {"text": "他用吸管夹了一块肉。", "explanation": "这里应该用〈筷子〉。夹东西要用筷子，吸管是细管，不能用来夹肉。"}, {"text": "这根吸管是用来排污水的。", "explanation": "这里应该用〈管子〉。排污水要用管子，吸管只用来吸饮料，不能用来排水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸管", "is_correct": true, "explanation": "正确：吸管一端含在嘴里，另一端插在杯中，对着它吹气会在饮料里冒泡。"}, {"text": "气球", "is_correct": false, "explanation": "体貌：气球是封闭的，吹进去的气到不了杯子里，与“杯子里出现泡泡”不合。"}, {"text": "手指", "is_correct": false, "explanation": "语义：对着手指吹气不会让杯子里出现泡泡。"}, {"text": "麦克风", "is_correct": false, "explanation": "语义：对着麦克风吹气，气不会进入杯子，杯子里不会出现泡泡。"}], "explanations": {"吸管": "正确：吸管一端含在嘴里，另一端插在杯中，对着它吹气会在饮料里冒泡。", "气球": "体貌：气球是封闭的，吹进去的气到不了杯子里，与“杯子里出现泡泡”不合。", "手指": "语义：对着手指吹气不会让杯子里出现泡泡。", "麦克风": "语义：对着麦克风吹气，气不会进入杯子，杯子里不会出现泡泡。"}, "sentence_index": 6, "correct_answer": "吸管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一只吸管。", "explanation": "这里应该用〈根〉。吸管细长，量词用“根”；“只”多用于动物和成对物件中的一个。"}, {"text": "她递给我一张吸管。", "explanation": "这里应该用〈根〉。“张”用于平面的东西，吸管是细长条，应说“一根”。"}, {"text": "他拿来一块吸管。", "explanation": "这里应该用〈根〉。“块”用于块状的东西，吸管是细长的，应说“一根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子里插着一只吸管。", "corrected_sentence": "杯子里插着一根吸管。", "error_description": "量词错误：吸管应用量词“根”，应说“插着一根吸管”。“只”多用于动物或成对物件中的一个，不用来数吸管。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吸管放进了杯子。", "corrected_sentence": "他把吸管放进了杯子。", "error_description": "缺少“把”：“放进”前的宾语“吸管”要用“把”引出，应说“他把吸管放进了杯子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
