INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指用的多少。", "primary_collocate": null, "pronunciation": "shǐ yòng liàng", "ipa": "ʂʐ̩²¹⁴ jʊŋ⁵¹ ljaŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这个房间灯的使用量很小。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的使用量不大，一个月只用一瓶。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水的使用量，夏天比冬天大。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我这种药的使用量是多少。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里网络的使用量越来越大了。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电的使用量可以在手机上看到。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的纸张使用量比同事多得多。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件的使用量最近上升了。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做菜时盐的使用量不能太多。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想减少办公用品的使用量，节约钱。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”指外观，“很小”不能用来描述颜色。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能用于灯。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：用的多少，“灯的使用量很小”指用得少。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指写作的人，不能用于灯。"}], "explanations": {"颜色": "体貌：“颜色”指外观，“很小”不能用来描述颜色。", "性格": "语义：“性格”指人的个性，不能用于灯。", "使用量": "使用量：用的多少，“灯的使用量很小”指用得少。", "作者": "语义：“作者”指写作的人，不能用于灯。"}, "sentence_index": 0, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的使用量很广。", "explanation": "这里应该用〈用途〉。使用量指用的多少，说药的用处广要用“用途”。"}, {"text": "这家餐厅的顾客使用量很多。", "explanation": "这里应该用〈数量〉。使用量指用在物品上的多少，指人数时要说“数量”。"}, {"text": "我们学习的使用量很长。", "explanation": "这里应该用〈时间〉。使用量只说用的多少，说学习的长短要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于纸张。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：用的多少，“比同事多得多”说明用得多。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”不是可以比多少的量，“比同事多得多”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用于纸张。"}], "explanations": {"身高": "体貌：“身高”指人的高矮，不能用于纸张。", "使用量": "使用量：用的多少，“比同事多得多”说明用得多。", "形状": "语义：“形状”不是可以比多少的量，“比同事多得多”说不通。", "脾气": "语义：“脾气”指人的性情，不能用于纸张。"}, "sentence_index": 6, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的使用量很贵。", "explanation": "这里应该用〈价格〉。使用量指用的多少，说衣服值多少钱要用“价格”。"}, {"text": "这条路的使用量很长。", "explanation": "这里应该用〈长度〉。使用量只说用的多少，说路的长短要用“长度”。"}, {"text": "他的使用量增加了三公斤。", "explanation": "这里应该用〈体重〉。使用量指用的多少，不能用来说人的体重增加了多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调的使用量的很小。", "corrected_sentence": "这台空调的使用量很小。", "error_description": "错误形式是“使用量的很小”，正确形式是“使用量很小”。“使用量”后直接接形容词作谓语时不加“的”，多出的“的”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的水的使用量少很。", "corrected_sentence": "我家的水的使用量很少。", "error_description": "错误形式是“使用量少很”，正确形式是“使用量很少”。程度副词“很”应放在形容词“少”之前，不能放在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
