INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃饭用的东西，比如碗和筷子。", "primary_collocate": null, "pronunciation": "cān jù", "ipa": "tsʰan˥˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "吃饭前，请先洗手，再拿餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有三套餐具。", "target_word": "餐具", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "餐具要洗干净才能用。", "target_word": "餐具", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友用的餐具很小。", "target_word": "餐具", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "饭店给每个人换了餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校食堂的餐具是塑料的。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时我带着自己的餐具。", "target_word": "餐具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把餐具放进了柜子里。", "target_word": "餐具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些餐具里有碗、盘子和勺子。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一副干净的餐具。", "target_word": "餐具", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一副餐具", "label": "量词"}, {"form": "一次性餐具", "label": "复合"}], "register": "中性", "sense_fingerprint": "吃饭时用的碗、筷子等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25926, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：餐具是吃饭时用的碗、勺、筷子等器具。"}, {"text": "惨剧", "is_correct": false, "explanation": "cǎn（第三声）与 cān（第一声）声调不同，意思是悲惨的事件。"}, {"text": "残局", "is_correct": false, "explanation": "cán（第二声）与 cān（第一声）、jú（第二声）与 jù（第四声）声调都不同，意思是残余的局面或棋局。"}, {"text": "餐叙", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），声调相同，意思是一起吃饭交谈。"}], "explanations": {"餐具": "正确：餐具是吃饭时用的碗、勺、筷子等器具。", "惨剧": "cǎn（第三声）与 cān（第一声）声调不同，意思是悲惨的事件。", "残局": "cán（第二声）与 cān（第一声）、jú（第二声）与 jù（第四声）声调都不同，意思是残余的局面或棋局。", "餐叙": "xù 与 jù 声母不同（x/j），声调相同，意思是一起吃饭交谈。"}, "sentence_index": null, "correct_answer": "餐具"}, "level_3": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：饭前洗手后拿餐具，符合准备吃饭的语境。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：饭前拿玩具与吃饭无关，不符合这里的准备动作。"}, {"text": "勇气", "is_correct": false, "explanation": "搭配：“拿”后接的是具体的物品，不说拿勇气。"}, {"text": "书本", "is_correct": false, "explanation": "语义：饭前拿书本不是准备吃饭的动作，句中没有读书的语境。"}], "explanations": {"餐具": "正确：饭前洗手后拿餐具，符合准备吃饭的语境。", "玩具": "语义：饭前拿玩具与吃饭无关，不符合这里的准备动作。", "勇气": "搭配：“拿”后接的是具体的物品，不说拿勇气。", "书本": "语义：饭前拿书本不是准备吃饭的动作，句中没有读书的语境。"}, "sentence_index": 0, "correct_answer": "餐具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃饭时要用餐具擦嘴。", "explanation": "这里应该用〈餐巾〉。擦嘴要用餐巾，餐具是吃饭时用的器具，不能用来擦嘴。"}, {"text": "我们围着餐具坐下。", "explanation": "这里应该用〈饭桌〉。大家围着饭桌坐下，餐具不能作为围坐的地方。"}, {"text": "饭店用餐具煮面条。", "explanation": "这里应该用〈炊具〉。煮面条要用锅等炊具，餐具不能用来煮东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐具", "is_correct": true, "explanation": "正确：旅行时带上自己的餐具是常见做法。"}, {"text": "床", "is_correct": false, "explanation": "语义：床太大，不能随身带着去旅行。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能随身携带，“带着”不能用于房屋。"}, {"text": "身材", "is_correct": false, "explanation": "配价：“带”的宾语须是可以随身携带的东西，身材不能被带着走。"}], "explanations": {"餐具": "正确：旅行时带上自己的餐具是常见做法。", "床": "语义：床太大，不能随身带着去旅行。", "房子": "语义：房子不能随身携带，“带着”不能用于房屋。", "身材": "配价：“带”的宾语须是可以随身携带的东西，身材不能被带着走。"}, "sentence_index": 6, "correct_answer": "餐具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请给我一块干净的餐具。", "explanation": "这里应该用〈副〉。餐具可以说“一副”或“一套”，“块”不用于餐具。"}, {"text": "饭店里摆着一张餐具。", "explanation": "这里应该用〈副〉。“张”用于平面的东西，餐具成套计量，应说“一副”。"}, {"text": "他买了一本餐具。", "explanation": "这里应该用〈副〉。“本”用于书籍等，不用于餐具，应说“一副”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我见过这本餐具。", "corrected_sentence": "我见过这套餐具。", "error_description": "量词错误：餐具成套计量，应说“这套餐具”，不说“这本餐具”。“本”用于书籍等，不用于餐具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他餐具摆在了桌子上。", "corrected_sentence": "他把餐具摆在了桌子上。", "error_description": "缺少“把”：“摆在”的宾语“餐具”提到动词前时，要用“把”引出，应说“他把餐具摆在了桌子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
