INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方到原来的地方。", "primary_collocate": null, "pronunciation": "huí", "ipa": "xweɪ˧˥", "syllable_count": 1, "sentences": [{"text": "天黑了，我该回家了。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月回一次老家。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗跑回了自己的窝。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候回学校？", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟放学后直接回房间写作业。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆住了三天，昨天回广州了。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买完菜就回厨房做饭。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走了半小时才回到家。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把杯子送回厨房。", "target_word": "回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿晚上都飞回树上。", "target_word": "回", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回了", "label": "完成体"}, {"form": "回过", "label": "经历体"}, {"form": "回来", "label": "复合词"}, {"form": "回去", "label": "复合词"}], "register": "中性", "sense_fingerprint": "返回原来所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回", "is_correct": true, "explanation": "回（huí）：从别的地方回到原来所在的地方，是本词。"}, {"text": "会", "is_correct": false, "explanation": "会（huì）与 huí 声调不同（第四声），意思是“会议”。"}, {"text": "悔", "is_correct": false, "explanation": "悔（huǐ）与 huí 声调不同（第三声），意思是“后悔”。"}, {"text": "挥", "is_correct": false, "explanation": "挥（huī）与 huí 声调不同（第一声），意思是“挥动”。"}], "explanations": {"回": "回（huí）：从别的地方回到原来所在的地方，是本词。", "会": "会（huì）与 huí 声调不同（第四声），意思是“会议”。", "悔": "悔（huǐ）与 huí 声调不同（第三声），意思是“后悔”。", "挥": "挥（huī）与 huí 声调不同（第一声），意思是“挥动”。"}, "sentence_index": null, "correct_answer": "回"}, "level_3": {"options": [{"text": "回", "is_correct": true, "explanation": "回：返回，天黑了说“回家”，指回到家里。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“吃家”不通，与回家无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物、身体等，不能说“洗家”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“家”作宾语。"}], "explanations": {"回": "回：返回，天黑了说“回家”，指回到家里。", "吃": "语义：“吃”指进食，“吃家”不通，与回家无关。", "洗": "搭配：“洗”的宾语是衣物、身体等，不能说“洗家”。", "睡": "配价：“睡”是不及物动词，不能带“家”作宾语。"}, "sentence_index": 0, "correct_answer": "回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你什么时候回书？", "explanation": "这里应该用〈还〉。回指返回原处，归还书要说还。"}, {"text": "我还没去过动物园，明天我们回动物园玩吧。", "explanation": "这里应该用〈去〉。回指回到原来所在的地方，从没去过的动物园不能说回。"}, {"text": "他从来没去过北京，却总是回北京。", "explanation": "这里应该用〈去〉。回指回到原来去过的地方，从来没去过的北京不能说回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25928, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回", "is_correct": true, "explanation": "回（huí）：从别的地方回到原来所在的地方，是本词。"}, {"text": "灰", "is_correct": false, "explanation": "灰（huī）与 huí 声调不同（第一声），意思是“灰色”。"}, {"text": "汇", "is_correct": false, "explanation": "汇（huì）与 huí 声调不同（第四声），意思是“汇集”。"}, {"text": "毁", "is_correct": false, "explanation": "毁（huǐ）与 huí 声调不同（第三声），意思是“毁坏”。"}, {"text": "慧", "is_correct": false, "explanation": "慧（huì）与 huí 声调不同（第四声），意思是“智慧”。"}], "explanations": {"回": "回（huí）：从别的地方回到原来所在的地方，是本词。", "灰": "灰（huī）与 huí 声调不同（第一声），意思是“灰色”。", "汇": "汇（huì）与 huí 声调不同（第四声），意思是“汇集”。", "毁": "毁（huǐ）与 huí 声调不同（第三声），意思是“毁坏”。", "慧": "慧（huì）与 huí 声调不同（第四声），意思是“智慧”。"}, "sentence_index": null, "correct_answer": "回"}, "level_3": {"options": [{"text": "回", "is_correct": true, "explanation": "回：返回，指妈妈买完菜后回到厨房。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与去厨房做饭无关。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中游动，不能说“游厨房”。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语是文字，“写厨房”不成搭配。"}], "explanations": {"回": "回：返回，指妈妈买完菜后回到厨房。", "唱": "语义：“唱”指唱歌，与去厨房做饭无关。", "游": "语义：“游”指在水中游动，不能说“游厨房”。", "写": "搭配：“写”的宾语是文字，“写厨房”不成搭配。"}, "sentence_index": 6, "correct_answer": "回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我回了一杯热水。", "explanation": "这里应该用〈倒〉。回指回到原处，倒水要说倒，不能用回。"}, {"text": "我把作业回给了老师。", "explanation": "这里应该用〈交〉。把作业上交给老师要说交，回字在这里不能表示交付。"}, {"text": "他每个月回三千块钱。", "explanation": "这里应该用〈挣〉。回表示返回或答复，不能表示收入，应说挣三千块钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下班后回宿舍上了。", "corrected_sentence": "他下班后回宿舍去了。", "error_description": "表示趋向的“去”不能换成“上”，“回宿舍上”不成立，应说“回宿舍去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年回了过一次老家。", "corrected_sentence": "他去年回过一次老家。", "error_description": "“回”后同时出现“了”和“过”，两个体标不能并用；表示曾经回去的经历只用“过”，应去掉“了”，说“去年回过一次老家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免税", "is_correct": true, "explanation": "免税指免除税收，与“征税”意思相反，二者构成反义。"}, {"text": "问候", "is_correct": false, "explanation": "与“征税”无反义关系，“问候”指打招呼、问好，与税收无关。"}, {"text": "写作", "is_correct": false, "explanation": "与“征税”无反义关系，“写作”指写文章，与税收无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“征税”无反义关系，“散步”指随意走动，与税收无关。"}], "correct_answer": "免税", "explanations": {"免税": "免税指免除税收，与“征税”意思相反，二者构成反义。", "问候": "与“征税”无反义关系，“问候”指打招呼、问好，与税收无关。", "写作": "与“征税”无反义关系，“写作”指写文章，与税收无关。", "散步": "与“征税”无反义关系，“散步”指随意走动，与税收无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免税", "is_correct": true, "explanation": "免税指免除税收，与“征税”意思相反，二者构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "与“征税”无反义关系，“游泳”指在水中活动，与税收无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“征税”无反义关系，“唱歌”指用声音表达乐曲，与税收无关。"}, {"text": "打扫", "is_correct": false, "explanation": "与“征税”无反义关系，“打扫”指清除脏物，与税收无关。"}], "correct_answer": "免税", "explanations": {"免税": "免税指免除税收，与“征税”意思相反，二者构成反义。", "游泳": "与“征税”无反义关系，“游泳”指在水中活动，与税收无关。", "唱歌": "与“征税”无反义关系，“唱歌”指用声音表达乐曲，与税收无关。", "打扫": "与“征税”无反义关系，“打扫”指清除脏物，与税收无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "政府向人们收钱。", "primary_collocate": null, "pronunciation": "zhēng shuì", "ipa": "tʂəŋ˥ ʂweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "政府要对大家征税，用来修路。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车的人要交钱，因为政府对车征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对酒征税，所以酒很贵。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问，政府为什么要征税？", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府征税以后，就有钱盖学校了。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都对大公司征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府明年要对旅馆征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对手机征税，手机的价钱会涨。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说政府不对农民征税了。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对有很多房子的人征税。", "target_word": "征税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征了税", "label": "体标"}, {"form": "征过税", "label": "体标"}], "register": "正式", "sense_fingerprint": "政府向人们收取税钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "征税", "is_correct": true, "explanation": "填入“征税”：政府向大家收税款，用来修路，句意通顺。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，不能用来修路，“对大家表扬，用来修路”句意不通。"}, {"text": "调查", "is_correct": false, "explanation": "搭配：“调查”的对象是事情或情况，不能说“对大家调查，用来修路”。"}, {"text": "承认", "is_correct": false, "explanation": "配价：“承认”的对象是事实或观点，不能说“对大家承认”，句子不成立。"}], "explanations": {"征税": "填入“征税”：政府向大家收税款，用来修路，句意通顺。", "表扬": "语义：“表扬”是称赞，不能用来修路，“对大家表扬，用来修路”句意不通。", "调查": "搭配：“调查”的对象是事情或情况，不能说“对大家调查，用来修路”。", "承认": "配价：“承认”的对象是事实或观点，不能说“对大家承认”，句子不成立。"}, "sentence_index": 0, "correct_answer": "征税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "居民每年都要按时征税。", "explanation": "这里应该用〈纳税〉。征税是政府向人们收钱，居民是纳税的一方，不能说“居民征税”。"}, {"text": "每个学生都要按时征税。", "explanation": "这里应该用〈缴费〉。征税只能由政府进行，学生交的是学费等费用，不是税。"}, {"text": "交警对乱停车的人征税。", "explanation": "这里应该用〈罚款〉。征税是按税法收取税款，对违章的人收的是罚款，不是税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "征税", "is_correct": true, "explanation": "填入“征税”：市政府明年对旅馆征收税款，句意通顺。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”要带请求、要求之类的对象，不能说“对旅馆拒绝”，句子不通。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是事件或成就，不能说“对旅馆祝贺”，句意不通。"}, {"text": "担心", "is_correct": false, "explanation": "配价：“担心”的对象是某种情况，不能说“对旅馆担心”，与“明年要”的规划语境不合。"}], "explanations": {"征税": "填入“征税”：市政府明年对旅馆征收税款，句意通顺。", "拒绝": "搭配：“拒绝”要带请求、要求之类的对象，不能说“对旅馆拒绝”，句子不通。", "祝贺": "搭配：“祝贺”的对象是事件或成就，不能说“对旅馆祝贺”，句意不通。", "担心": "配价：“担心”的对象是某种情况，不能说“对旅馆担心”，与“明年要”的规划语境不合。"}, "sentence_index": 6, "correct_answer": "征税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去税务局征税。", "explanation": "这里应该用〈交税〉。征税是政府的行为，个人是交税的一方，不能说“去税务局征税”。"}, {"text": "这家公司每年都向税务局征税。", "explanation": "这里应该用〈报税〉。征税是税务机关的行为，公司只能报税，不能说“公司向税务局征税”。"}, {"text": "物业公司每月向业主征税。", "explanation": "这里应该用〈收取〉。征税只能由国家依法进行，物业公司收的是管理费用，不是税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府去年对进口车征税过。", "corrected_sentence": "政府去年对进口车征过税。", "error_description": "“征税”是离合词，体标“过”要放在“征”和“税”之间，应说“征过税”。“征税过”把“过”放在末尾，不符合汉语语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府网上卖的书征税。", "corrected_sentence": "政府对网上卖的书征税。", "error_description": "“征税”的对象前要用介词“对”引出，应说“政府对网上卖的书征税”。省略“对”直接说“政府网上卖的书征税”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
