INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "回收率是指把用过的物品收回来再用的数量占所有物品数量的比例。", "primary_collocate": null, "pronunciation": "huí shōu lǜ", "ipa": "xweɪ˧˥ ʂoʊ˥˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂的旧衣服回收率是百分之四十。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区的回收率终于超过了一半。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店给顾客一点钱，所以瓶子的回收率很高。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种电池的回收率太低了，真可惜。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王负责统计每个月的回收率。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年纸箱的回收率比今年高。", "target_word": "回收率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回收率每年都在增长，环境越来越好。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道易拉罐的回收率有多高。", "target_word": "回收率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的回收率排在世界第一。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新机器让旧手机的回收率达到了九成。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾回收率", "label": "复合词"}, {"form": "旧衣回收率", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用过的物品收回再用的数量占总数的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回收率", "is_correct": true, "explanation": "正确：“回收率”指旧衣服被收回再用的比例，可以是百分之四十，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不用于旧衣服。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是比例，不能用“百分之四十”来表示。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物的岁数，旧衣服没有年龄。"}], "explanations": {"回收率": "正确：“回收率”指旧衣服被收回再用的比例，可以是百分之四十，符合句意。", "体重": "搭配：“体重”只用于人或动物，不用于旧衣服。", "颜色": "语义：“颜色”不是比例，不能用“百分之四十”来表示。", "年龄": "语义：“年龄”指人或生物的岁数，旧衣服没有年龄。"}, "sentence_index": 0, "correct_answer": "回收率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种电池的回收率很少，真可惜。", "explanation": "这里应该用〈回收量〉。回收量是数量，可以说“很少”；回收率是比例，应该说“很低”。"}, {"text": "我们社区的回收率有五百个瓶子。", "explanation": "这里应该用〈回收数量〉。回收率是比例，不能用''五百个瓶子''来计数。"}, {"text": "这家工厂的回收率重三吨。", "explanation": "这里应该用〈回收量〉。回收率是比例，没有重量，不能说''重三吨''。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回收率", "is_correct": true, "explanation": "正确：“回收率”指回收比例，可以随着时间增长，符合“环境越来越好”的句意。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”增长与“环境越来越好”相矛盾，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，与回收无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只用于人或动物，与回收无关。"}], "explanations": {"回收率": "正确：“回收率”指回收比例，可以随着时间增长，符合“环境越来越好”的句意。", "污染": "语义：“污染”增长与“环境越来越好”相矛盾，句意不通。", "身高": "搭配：“身高”只用于人或动物，与回收无关。", "体温": "搭配：“体温”只用于人或动物，与回收无关。"}, "sentence_index": 6, "correct_answer": "回收率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年旧手机的回收率多了一千部。", "explanation": "这里应该用〈回收总数〉。回收率是比例，不能用“多了一千部”来数；说回收总数多了才对。"}, {"text": "这个月学校的回收率有一千件，比上个月多。", "explanation": "这里应该用〈回收件数〉。回收率是百分比，不能说“有一千件”；件数才能这样计数。"}, {"text": "这个城市的回收率达到了一千吨。", "explanation": "这里应该用〈回收利用量〉。回收率是比例，不能用“一千吨”这样的重量来表示；应说回收利用量达到一千吨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座工厂的一块回收率是六成。", "corrected_sentence": "这座工厂的回收率是六成。", "error_description": "量词“块”用错了。“块”用于块状物品，不能修饰“回收率”，应直接说“这座工厂的回收率是六成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的回收率很提高了三成。", "corrected_sentence": "这个城市的回收率提高了三成。", "error_description": "副词“很”用错了。“很”修饰形容词或状态，不能放在动词“提高”前面，应说“这个城市的回收率提高了三成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "放：与“拿”构成反义，拿起与放下相对。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“拿”没有对立关系，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“拿”没有对立关系，不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“拿”没有对立关系，不构成反义。"}], "correct_answer": "放", "explanations": {"放": "放：与“拿”构成反义，拿起与放下相对。", "吃": "“吃”与“拿”没有对立关系，不构成反义。", "跑": "“跑”与“拿”没有对立关系，不构成反义。", "唱": "“唱”与“拿”没有对立关系，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "放：与“拿”构成反义，拿起与放下相对。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“拿”没有对立关系，不构成反义。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“拿”没有对立关系，不构成反义。"}, {"text": "看", "is_correct": false, "explanation": "“看”与“拿”没有对立关系，不构成反义。"}], "correct_answer": "放", "explanations": {"放": "放：与“拿”构成反义，拿起与放下相对。", "睡": "“睡”与“拿”没有对立关系，不构成反义。", "写": "“写”与“拿”没有对立关系，不构成反义。", "看": "“看”与“拿”没有对立关系，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把东西握住或取过来。", "primary_collocate": null, "pronunciation": "ná", "ipa": "na˧˥", "syllable_count": 1, "sentences": [{"text": "妈妈拿着菜篮子去市场。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我拿一下这个杯子。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸手拿桌上的苹果。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明从冰箱里拿了一瓶牛奶。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用两只手拿着大西瓜。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个锅太烫了，别用手直接拿。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让大家把课本拿出来。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿起电话，打给了妈妈。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先拿着这个，我去开门。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿了两个袋子，走进超市。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿了", "label": "完成体"}, {"form": "拿着", "label": "持续体"}, {"form": "拿过", "label": "经历体"}, {"form": "拿出来", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用手握住东西或把东西取过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿（ná）：用手握住或取过来某物，是本词。"}, {"text": "那", "is_correct": false, "explanation": "那（nà）与 ná 声调不同（第四声），意思是“那个”。"}, {"text": "哪", "is_correct": false, "explanation": "哪（nǎ）与 ná 声调不同（第三声），意思是“哪里”。"}, {"text": "难", "is_correct": false, "explanation": "难（nán）与 ná 韵母不同（-an 与 -a），意思是“困难”。"}, {"text": "呐", "is_correct": false, "explanation": "呐（nā）与 ná 声调不同（第一声），是语气词。"}, {"text": "麻", "is_correct": false, "explanation": "má 与 ná 声母不同（m 与 n），意思是“麻”。"}], "explanations": {"拿": "拿（ná）：用手握住或取过来某物，是本词。", "那": "那（nà）与 ná 声调不同（第四声），意思是“那个”。", "哪": "哪（nǎ）与 ná 声调不同（第三声），意思是“哪里”。", "难": "难（nán）与 ná 韵母不同（-an 与 -a），意思是“困难”。", "呐": "呐（nā）与 ná 声调不同（第一声），是语气词。", "麻": "má 与 ná 声母不同（m 与 n），意思是“麻”。"}, "sentence_index": null, "correct_answer": "拿"}, "level_3": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿着：用手握住，指妈妈手里握着菜篮子。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说“吃着菜篮子”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与拿着东西去市场无关。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，与提着篮子去市场不符。"}], "explanations": {"拿": "拿着：用手握住，指妈妈手里握着菜篮子。", "吃": "搭配：“吃”的宾语应为食物，不能说“吃着菜篮子”。", "唱": "语义：“唱”指唱歌，与拿着东西去市场无关。", "烧": "语义：“烧”指燃烧或加热，与提着篮子去市场不符。"}, "sentence_index": 0, "correct_answer": "拿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明拿开了冰箱门，走进厨房。", "explanation": "这里应该用〈打开〉。拿开指拿走物品，开门要说打开。"}, {"text": "妈妈把围裙拿在厨房的门上。", "explanation": "这里应该用〈挂〉。拿表示用手握住或取过来，把围裙挂在门上要说挂。"}, {"text": "他们去年拿了一场晚会。", "explanation": "这里应该用〈举办〉。拿表示用手握住或取过来，组织晚会要说举办，不能说拿晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿（ná）：用手握住或取过来某物，是本词。"}, {"text": "纳", "is_correct": false, "explanation": "纳（nà）与 ná 声调不同（第四声），意思是“缴纳”。"}, {"text": "南", "is_correct": false, "explanation": "南（nán）与 ná 韵母不同（-an 与 -a），意思是“南方”。"}, {"text": "爬", "is_correct": false, "explanation": "pá 与 ná 声母不同（p 与 n），意思是“爬行”。"}, {"text": "茶", "is_correct": false, "explanation": "chá 与 ná 声母不同（ch 与 n），意思是“茶”。"}], "explanations": {"拿": "拿（ná）：用手握住或取过来某物，是本词。", "纳": "纳（nà）与 ná 声调不同（第四声），意思是“缴纳”。", "南": "南（nán）与 ná 韵母不同（-an 与 -a），意思是“南方”。", "爬": "pá 与 ná 声母不同（p 与 n），意思是“爬行”。", "茶": "chá 与 ná 声母不同（ch 与 n），意思是“茶”。"}, "sentence_index": null, "correct_answer": "拿"}, "level_3": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿出来：用手取出，指老师让大家把课本取出。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”指发笑，不能说“把课本笑出来”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“课本”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“课本”作宾语。"}], "explanations": {"拿": "拿出来：用手取出，指老师让大家把课本取出。", "笑": "语义：“笑”指发笑，不能说“把课本笑出来”。", "睡": "配价：“睡”是不及物动词，不能带“课本”作宾语。", "哭": "配价：“哭”是不及物动词，不能带“课本”作宾语。"}, "sentence_index": 6, "correct_answer": "拿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿开了超市的门，走了进去。", "explanation": "这里应该用〈推〉。拿开指拿走物品，推门要说推开。"}, {"text": "她拿着栏杆下楼。", "explanation": "这里应该用〈扶〉。拿表示用手持物，扶栏杆要说扶。"}, {"text": "奶奶拿着小孙子，笑着亲了他一口。", "explanation": "这里应该用〈抱〉。拿表示用手握住或取过来，抱孩子要说抱，不能说拿着小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正拿了书包去学校。", "corrected_sentence": "她正拿着书包去学校。", "error_description": "“正”表示动作正在进行，应与“着”搭配，说“正拿着书包去学校”；“拿了”表示动作已经完成，与“正”的进行义矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她起拿一支笔，开始写字。", "corrected_sentence": "她拿起一支笔，开始写字。", "error_description": "“拿起”是动词“拿”加趋向补语“起”，语序应为“拿起”，不能说“起拿”；错误在于“拿”与“起”的先后顺序，与量词无关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大幅降低", "is_correct": true, "explanation": "正确：“降低”与“提高”是反义词，“大幅降低”表示销量大幅减少，与“大幅提高”相对。"}, {"text": "翻译", "is_correct": false, "explanation": "无反义关系：“翻译”指语言之间的转换，与“提高”没有对立关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是悠闲地走动，与“提高”没有对立关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”是交换意见，与“提高”没有对立关系。"}], "correct_answer": "大幅降低", "explanations": {"大幅降低": "正确：“降低”与“提高”是反义词，“大幅降低”表示销量大幅减少，与“大幅提高”相对。", "翻译": "无反义关系：“翻译”指语言之间的转换，与“提高”没有对立关系。", "散步": "无反义关系：“散步”是悠闲地走动，与“提高”没有对立关系。", "讨论": "无反义关系：“讨论”是交换意见，与“提高”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大幅降低", "is_correct": true, "explanation": "正确：“降低”与“提高”是反义词，“大幅降低”表示价格大幅下降，与“大幅提高”相对。"}, {"text": "开始", "is_correct": false, "explanation": "无反义关系：“开始”表示起始，与“提高”没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "无反义关系：“休息”表示停下来放松，与“提高”没有对立关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”是出行活动，与“提高”没有对立关系。"}], "correct_answer": "大幅降低", "explanations": {"大幅降低": "正确：“降低”与“提高”是反义词，“大幅降低”表示价格大幅下降，与“大幅提高”相对。", "开始": "无反义关系：“开始”表示起始，与“提高”没有对立关系。", "休息": "无反义关系：“休息”表示停下来放松，与“提高”没有对立关系。", "旅行": "无反义关系：“旅行”是出行活动，与“提高”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "变得比原来多了很多。", "primary_collocate": null, "pronunciation": "dà fú tí gāo", "ipa": "ta˥˩ fu˧˥ tʰi˧˥ kɑʊ˥", "syllable_count": 4, "sentences": [{"text": "今年大米的价格大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我加了工资，我的收入大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日期间，这家餐厅的客流量大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车的人多了，汽车的销量大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天用空调多，电费大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁票的价格大幅提高，很多人不坐了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月房租大幅提高了，我只好搬家。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开了新店以后，他的收入大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的房价大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了冬天，菜的价格会大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大幅提高了", "label": "体标"}], "register": "中性", "sense_fingerprint": "价格、收入、销量、温度等数量比原来高出很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大幅提高", "is_correct": true, "explanation": "正确：“大幅提高”表示价格比原来高很多，符合“今年大米的价格……了”的句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲或人，不能用于价格。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指语言之间的转换，与价格无关。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”指人或动物在水里运动，不能用于价格。"}], "explanations": {"大幅提高": "正确：“大幅提高”表示价格比原来高很多，符合“今年大米的价格……了”的句意。", "唱": "搭配：“唱”用于歌曲或人，不能用于价格。", "翻译": "语义：“翻译”指语言之间的转换，与价格无关。", "游": "搭配：“游”指人或动物在水里运动，不能用于价格。"}, "sentence_index": 0, "correct_answer": "大幅提高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把屋顶大幅提高了三米。", "explanation": "这里应该用〈抬高〉。屋顶是具体物体，高度变化要说“抬高”；“提高”不用于具体物体的高低。"}, {"text": "这座城市的面积大幅提高了。", "explanation": "这里应该用〈扩大〉。面积变大要说“扩大”，“提高”不用于空间的大小。"}, {"text": "这把椅子的颜色大幅提高了。", "explanation": "这里应该用〈加深〉。颜色变深要说加深；提高不用于颜色的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大幅提高", "is_correct": true, "explanation": "正确：“大幅提高”表示房租比原来高很多，符合“我只好搬家”的句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只用于饮品，不能用于房租。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是人的活动，不能用于房租。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是人或动物的休息动作，房租不能睡。"}], "explanations": {"大幅提高": "正确：“大幅提高”表示房租比原来高很多，符合“我只好搬家”的句意。", "喝": "搭配：“喝”只用于饮品，不能用于房租。", "散步": "搭配：“散步”是人的活动，不能用于房租。", "睡": "语义：“睡”是人或动物的休息动作，房租不能睡。"}, "sentence_index": 6, "correct_answer": "大幅提高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个假期大幅提高了两天。", "explanation": "这里应该用〈延长〉。时间变长要说“延长”，“提高”不用于时间。"}, {"text": "过年吃得太多，他的体重大幅提高了。", "explanation": "这里应该用〈增加〉。体重变重要说“增加”，“提高”一般不用于体重。"}, {"text": "这条马路的宽度大幅提高了。", "explanation": "这里应该用〈加宽〉。宽度变大要说“加宽”，“提高”不用于宽度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的油价很大幅提高了。", "corrected_sentence": "今年的油价大幅提高了。", "error_description": "副词“很”用错了。“大幅”已表示程度，不能再用“很”修饰，应说“今年的油价大幅提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的菜价没有大幅提高了。", "corrected_sentence": "这家餐厅的菜价没有大幅提高。", "error_description": "用“没（有）”否定时，句末不能再用表示完成的“了”，应说“没有大幅提高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
