INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "喝完了饮料，瓶子里没有东西了。", "primary_collocate": null, "pronunciation": "kōng píng", "ipa": "kʰʊŋ⁵⁵ pʰiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "我喝完了果汁，只剩一个空瓶。", "target_word": "空瓶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个空瓶以前装过牛奶。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把空瓶放在路中间。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起空瓶，说再来一瓶。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空瓶太轻，风一吹就倒了。", "target_word": "空瓶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在海边捡到了一个空瓶。", "target_word": "空瓶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里的空瓶你拿出来吧。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拿着一个空瓶，站在门口。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶旁边有几个空瓶。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个空瓶很干净，可以再用。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个空瓶", "label": "量词"}, {"form": "空瓶子", "label": "复合"}], "register": "中性", "sense_fingerprint": "喝完饮料后里面没有东西的瓶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18457a1-9dcd-4551-8484-b67740909c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空瓶", "is_correct": true, "explanation": "“只剩一个”指剩下的是空瓶，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与“喝完了果汁”的语境无关，句意不通。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币不是喝完后剩下的空容器，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“一个空气”不是自然的说法，与“只剩”也搭配不上。"}], "explanations": {"空瓶": "“只剩一个”指剩下的是空瓶，符合句意。", "手机": "语义：手机与“喝完了果汁”的语境无关，句意不通。", "硬币": "语义：硬币不是喝完后剩下的空容器，句意不通。", "空气": "搭配：“一个空气”不是自然的说法，与“只剩”也搭配不上。"}, "sentence_index": 0, "correct_answer": "空瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他举起一条空瓶，说再来一瓶。", "explanation": "这里应该用〈个〉。“条”用于细长的物体，瓶子不能用。"}, {"text": "他举起一张空瓶，说再来一瓶。", "explanation": "这里应该用〈个〉。“张”用于扁平物，瓶子不能用。"}, {"text": "他举起一块空瓶，说再来一瓶。", "explanation": "这里应该用〈个〉。“块”用于块状物，瓶子不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空瓶", "is_correct": true, "explanation": "冰箱里的空瓶可以拿出来，符合句意。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不会放在冰箱里，与“冰箱里的”矛盾。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯不会放在冰箱里，无法从冰箱里拿出来。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不会放在冰箱里，与“冰箱里的”矛盾。"}], "explanations": {"空瓶": "冰箱里的空瓶可以拿出来，符合句意。", "窗帘": "语义：窗帘不会放在冰箱里，与“冰箱里的”矛盾。", "地毯": "语义：地毯不会放在冰箱里，无法从冰箱里拿出来。", "台灯": "语义：台灯不会放在冰箱里，与“冰箱里的”矛盾。"}, "sentence_index": 6, "correct_answer": "空瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本空瓶很干净，可以再用。", "explanation": "这里应该用〈个〉。“本”用于书籍，瓶子应用“个”。"}, {"text": "这匹空瓶很干净，可以再用。", "explanation": "这里应该用〈个〉。“匹”用于马等牲畜，瓶子不能用。"}, {"text": "这辆空瓶很干净，可以再用。", "explanation": "这里应该用〈个〉。“辆”用于车辆，瓶子不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上只剩两座空瓶。", "corrected_sentence": "桌上只剩两个空瓶。", "error_description": "错误：“两座空瓶”；正确：“两个空瓶”。“座”用于山、桥等大型物体，空瓶的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
