INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好或更厉害。", "primary_collocate": null, "pronunciation": "jiā qiáng", "ipa": "tɕjɑ˥ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工人用钢条加强了这座桥。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙太薄了，我们要把它加强一下。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练想加强球队的防守。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，加强手臂的力量。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门不结实，我们把它加强一下。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给这台音箱换了大喇叭，加强了低音效果。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药和热水一起吃，能加强效果。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王让人加强城墙，不让敌人进来。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买了新机器，加强了生产能力。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光加强了舞台的效果。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加强了", "label": "体标"}, {"form": "加强过", "label": "体标"}, {"form": "加強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使具体事物或能力变得更结实、更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 4 words above tier T1 (max 2): 这台 (Zipf 3.53), 音箱 (Zipf 3.18), 喇叭 (Zipf 3.87), 低音 (Zipf 3.26)']::text[], '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加强", "is_correct": true, "explanation": "正确答案：加强 jiāqiáng，意思是使具体事物或能力变得更结实、更强。"}, {"text": "假墙", "is_correct": false, "explanation": "假墙 jiǎqiáng 与 jiāqiáng 第一音节声调不同（第三声），意思是假的墙。"}, {"text": "加钱", "is_correct": false, "explanation": "加钱 jiāqián 与 jiāqiáng 第二音节韵母不同（an 与 ang），意思是增加钱。"}, {"text": "加长", "is_correct": false, "explanation": "加长 jiācháng 与 jiāqiáng 第二音节声母不同（ch 与 q），意思是使变长。"}], "explanations": {"加强": "正确答案：加强 jiāqiáng，意思是使具体事物或能力变得更结实、更强。", "假墙": "假墙 jiǎqiáng 与 jiāqiáng 第一音节声调不同（第三声），意思是假的墙。", "加钱": "加钱 jiāqián 与 jiāqiáng 第二音节韵母不同（an 与 ang），意思是增加钱。", "加长": "加长 jiācháng 与 jiāqiáng 第二音节声母不同（ch 与 q），意思是使变长。"}, "sentence_index": null, "correct_answer": "加强"}, "level_3": {"options": [{"text": "削弱", "is_correct": false, "explanation": "语义：削弱是使变弱，与用钢条加固桥的做法相反。"}, {"text": "漆", "is_correct": false, "explanation": "搭配：“漆”指涂漆，用钢条不能漆桥，搭配不当。"}, {"text": "加强", "is_correct": true, "explanation": "加强：用钢条使这座桥更结实，与句中的做法相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃这座桥与用钢条加固它的做法不合。"}], "explanations": {"削弱": "语义：削弱是使变弱，与用钢条加固桥的做法相反。", "漆": "搭配：“漆”指涂漆，用钢条不能漆桥，搭配不当。", "加强": "加强：用钢条使这座桥更结实，与句中的做法相符。", "放弃": "语义：放弃这座桥与用钢条加固它的做法不合。"}, "sentence_index": 0, "correct_answer": "加强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂加强了产品的价格，每件多收十元。", "explanation": "这里应该用〈提高〉。价格的上涨要用提高或涨价，加强不用于价格的变化。"}, {"text": "他跑步时加强了速度，跑得更快。", "explanation": "这里应该用〈加快〉。速度、进度要用加快，加强不用于速度的变化。"}, {"text": "这座城市加强了绿地的面积。", "explanation": "这里应该用〈扩大〉。面积、规模的扩大要用扩大，加强不用于面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝效果。"}, {"text": "加强", "is_correct": true, "explanation": "加强：使药效更明显，与“能……效果”的语境相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、意见，不能说拒绝效果。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记的是事情，与“效果”的语义不合。"}], "explanations": {"喝": "搭配：“喝”的对象是饮品，不能说喝效果。", "加强": "加强：使药效更明显，与“能……效果”的语境相符。", "拒绝": "搭配：“拒绝”的对象是请求、意见，不能说拒绝效果。", "忘记": "语义：忘记的是事情，与“效果”的语义不合。"}, "sentence_index": 6, "correct_answer": "加强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给房间加强了一盏台灯。", "explanation": "这里应该用〈增添〉。添加物件要用增添，加强不带这种物件宾语。"}, {"text": "这次改革加强了农民的收入。", "explanation": "这里应该用〈提升〉。收入、水平的提高用提升或提高，加强不用于收入。"}, {"text": "我们的销售额加强了一倍。", "explanation": "这里应该用〈增长〉。销售额成倍增加要用增长或增加，加强不表示数量成倍变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把安全措施加强下来。", "corrected_sentence": "我们要把安全措施加强起来。", "error_description": "趋向补语应为“起来”，表示动作开始并持续，说“加强起来”；“加强下来”的说法不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把屋顶加强地很结实。", "corrected_sentence": "工人把屋顶加强得很结实。", "error_description": "补语标记应为“得”，用于引出结果程度；“地”是状语标记，只能放在动词前，不能用在“加强”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
