INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事想要达到的结果或目标。", "primary_collocate": "达到", "pronunciation": "mù dì", "ipa": "mu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "为了达到目的，他每天都练习。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于达到了目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目的达到了，可以回家了。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不达目的，他不会放手。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不择手段，只为达到自己的目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法能让你达到目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目的没有达到，很不高兴。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这个目的，大家都很努力。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了很多办法，才实现目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有达到目的，我们不会停下来。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的地", "label": "复合"}], "register": "中性", "sense_fingerprint": "努力想要到达或实现的那个结果", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“达到”不能带“天气”作宾语，句中表达不出做事想要得到的结果。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不是做事想要达到的结果，“为了达到颜色”句意不通。"}, {"text": "目的", "is_correct": true, "explanation": "正确：“目的”是做事想要达到的结果，与“达到”搭配，“为了达到目的”表示做事的目标。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“达到”后面接“目的”“目标”“水平”等，不接“感情”，句中无法成立。"}], "explanations": {"天气": "搭配：“达到”不能带“天气”作宾语，句中表达不出做事想要得到的结果。", "颜色": "语义：“颜色”是事物的属性，不是做事想要达到的结果，“为了达到颜色”句意不通。", "目的": "正确：“目的”是做事想要达到的结果，与“达到”搭配，“为了达到目的”表示做事的目标。", "感情": "搭配：“达到”后面接“目的”“目标”“水平”等，不接“感情”，句中无法成立。"}, "sentence_index": 0, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的目的很充分，所以不参加比赛。", "explanation": "这里应该用〈理由〉。「充分」修饰理由或根据，目的指想要达到的结果，不能说「目的很充分」。"}, {"text": "这次比赛的目的已经出来了。", "explanation": "这里应该用〈结果〉。比赛的结果可以出来，目的是事先设定的，不能说“出来”。"}, {"text": "这次失误的目的很严重。", "explanation": "这里应该用〈后果〉。“严重”形容失误造成的影响，目的是人想要达到的目标，不能用“严重”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一顿饭，不是可以“达到”的结果，“他的午饭没有达到”句意荒谬。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“达到”不能与“性格”搭配，“性格没有达到”无法表达句中的意思。"}, {"text": "目的", "is_correct": true, "explanation": "正确：“目的”是人想要达到的结果，“没有达到”与“很不高兴”前后呼应。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是具体的建筑物件，不能“达到”，句意荒谬。"}], "explanations": {"午饭": "语义：“午饭”是一顿饭，不是可以“达到”的结果，“他的午饭没有达到”句意荒谬。", "性格": "搭配：“达到”不能与“性格”搭配，“性格没有达到”无法表达句中的意思。", "目的": "正确：“目的”是人想要达到的结果，“没有达到”与“很不高兴”前后呼应。", "窗户": "语义：“窗户”是具体的建筑物件，不能“达到”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的目的很精彩。", "explanation": "这里应该用〈过程〉。“精彩”形容活动进行的经过，目的是想要达到的结果，不能用“精彩”来形容。"}, {"text": "他脸上的目的很平静。", "explanation": "这里应该用〈表情〉。“平静”形容人的表情或心情，目的指做事想要达到的结果，不能描述脸色。"}, {"text": "这列火车的目的很快。", "explanation": "这里应该用〈速度〉。“快”描述的是运行的快慢，目的不能用来描述速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一座明确的目的。", "corrected_sentence": "他有一个明确的目的。", "error_description": "量词错误：“目的”应该用量词“个”，不能用“座”。“座”用于山、桥、房屋等大型固定的物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的目的们已经达到了。", "corrected_sentence": "我们的目的已经达到了。", "error_description": "“们”的使用错误：“们”只用于指人的名词，抽象名词“目的”后面不能加“们”，应说“我们的目的”，不能说“我们的目的们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
