INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了达到某个目标而采取的具体方法或做法。", "primary_collocate": null, "pronunciation": "cuò shī", "ipa": "tsʰwɔ˥˩ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "政府想了很多措施来保护环境。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校采取了新的安全措施。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尽快想出有效的措施。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有好的措施，问题越来越多。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些措施对减少污染很有用。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防火，工厂加强了管理措施。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院采取措施，不让病人太担心。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们应该马上采取措施。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个很好的措施。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项措施能帮助更多的老人。", "target_word": "措施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "为解决问题或达到目标而采取的具体办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "措施", "is_correct": true, "explanation": "措施：为达到保护环境的目标而采取的具体做法，这里指做法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，不能用来保护环境，“想了很多颜色”也不成立。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”指穿的物品，与保护环境无关。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“想了很多”接的是做法或计划，“座位”不能这样搭配，也不能用来保护环境。"}], "explanations": {"措施": "措施：为达到保护环境的目标而采取的具体做法，这里指做法。", "颜色": "语义：“颜色”指外观，不能用来保护环境，“想了很多颜色”也不成立。", "衣服": "语义：“衣服”指穿的物品，与保护环境无关。", "座位": "搭配：“想了很多”接的是做法或计划，“座位”不能这样搭配，也不能用来保护环境。"}, "sentence_index": 0, "correct_answer": "措施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区的措施很齐全，有游泳池和图书馆。", "explanation": "这里应该用〈设施〉。措施指为达到目标采取的做法，游泳池、图书馆是设施，不能说“措施很齐全”。"}, {"text": "这位医生是我们的好措施。", "explanation": "这里应该用〈人才〉。措施指为达到目标采取的具体做法，不能用来指人，形容人的能力和价值要用人才。"}, {"text": "学校举行了一场措施，大家都很认真。", "explanation": "这里应该用〈活动〉。“举行”搭配“活动”，措施是为达到目标采取的具体做法，不能举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "措施", "is_correct": true, "explanation": "措施：为解决问题而采取的具体做法，这里指医院为安抚病人采取的做法。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“采取”后面接的是做法，不能接具体的家具“桌子”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不是为解决问题采取的做法。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物的滋味，与“不让病人太担心”无关，不是做法。"}], "explanations": {"措施": "措施：为解决问题而采取的具体做法，这里指医院为安抚病人采取的做法。", "桌子": "搭配：“采取”后面接的是做法，不能接具体的家具“桌子”。", "温度": "语义：“温度”指冷热程度，不是为解决问题采取的做法。", "味道": "语义：“味道”指食物的滋味，与“不让病人太担心”无关，不是做法。"}, "sentence_index": 6, "correct_answer": "措施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只措施很有效，老人们都喜欢。", "explanation": "这里应该用〈项〉。“只”多用于动物等，措施要用量词“项”。"}, {"text": "这种生活措施很健康。", "explanation": "这里应该用〈方式〉。“生活方式”指生活的样式，措施是为达到目标采取的具体做法，不能说“生活措施”。"}, {"text": "我们犯了一个措施，需要改正。", "explanation": "这里应该用〈错误〉。“犯”搭配“错误”，不能搭配“措施”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校需要采取有效地措施。", "corrected_sentence": "学校需要采取有效的措施。", "error_description": "错误：有效地措施。正确：有效的措施。“有效”修饰名词，应用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂对污染问题做了措施。", "corrected_sentence": "工厂对污染问题采取了措施。", "error_description": "错误：做了措施。正确：采取了措施。“措施”常与“采取”搭配，不说“做措施”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
