INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做错了事，要交给政府的钱。", "primary_collocate": null, "pronunciation": "fá kuǎn", "ipa": "fa˧˥ kʰwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "开车打电话要交一百元罚款。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的罚款不少，我有点难过。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸停错了地方，交了二百元罚款。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾的罚款是五十元。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没带钱，交不了罚款。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车不戴头盔，也要交罚款。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔罚款要在一个星期内交。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超速的罚款比停车的罚款高。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司因为污水问题交了很多罚款。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了交罚款，过了时间还要多交钱。", "target_word": "罚款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "罚款单", "label": "复合"}], "register": "中性", "sense_fingerprint": "因违反规定而被要求交给政府的钱（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罚款", "is_correct": true, "explanation": "正确。罚款指做错事后要交给政府的钱，可以与“要交一百元”搭配。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是发给人的钱，不是要交给政府的钱，与“开车打电话要交”的语境冲突。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是单位付给员工的钱，不能由人“交”出去。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“交”用于费用、罚款之类的款项，不能说交礼物。"}], "explanations": {"罚款": "正确。罚款指做错事后要交给政府的钱，可以与“要交一百元”搭配。", "奖金": "语义：奖金是发给人的钱，不是要交给政府的钱，与“开车打电话要交”的语境冲突。", "工资": "语义：工资是单位付给员工的钱，不能由人“交”出去。", "礼物": "搭配：“交”用于费用、罚款之类的款项，不能说交礼物。"}, "sentence_index": 0, "correct_answer": "罚款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把钱存进银行，一年后我能拿到三百元罚款。", "explanation": "这里应该用〈利息〉。罚款是因违规而交给政府的钱，存款一年后得到的收益要说“利息”。"}, {"text": "司机撞伤了行人，要交三千元罚款给对方。", "explanation": "这里应该用〈赔偿〉。罚款是交给政府的钱，赔给受害人的钱要说“赔偿”。"}, {"text": "租房时他要交一千元罚款。", "explanation": "这里应该用〈押金〉。罚款是因违规而交的钱，租房时交的担保金要说“押金”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罚款", "is_correct": true, "explanation": "正确。“这笔罚款”指需要交出的罚金，“要在一个星期内交”与之相符。"}, {"text": "奖学金", "is_correct": false, "explanation": "语义：奖学金是颁发给学生的奖励，是领取的，不是要交出去的钱。"}, {"text": "红包", "is_correct": false, "explanation": "语义：红包是送给别人的，不是要在期限内交上去的款项。"}, {"text": "俸禄", "is_correct": false, "explanation": "语域：俸禄是古代官员的薪俸，属书面或古语词，放在口语提醒句里很突兀，而且它是领取的钱。"}], "explanations": {"罚款": "正确。“这笔罚款”指需要交出的罚金，“要在一个星期内交”与之相符。", "奖学金": "语义：奖学金是颁发给学生的奖励，是领取的，不是要交出去的钱。", "红包": "语义：红包是送给别人的，不是要在期限内交上去的款项。", "俸禄": "语域：俸禄是古代官员的薪俸，属书面或古语词，放在口语提醒句里很突兀，而且它是领取的钱。"}, "sentence_index": 6, "correct_answer": "罚款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为他工作出色，公司发给他一千元罚款。", "explanation": "这里应该用〈奖金〉。罚款是因违规而交给政府的钱，不会因为表现好而由公司发给员工。"}, {"text": "妈妈帮我交了一学期的罚款。", "explanation": "这里应该用〈学费〉。罚款是因违规而交的钱，交一学期的费用要说“学费”。"}, {"text": "参加婚礼时，我给了新人五百元罚款。", "explanation": "这里应该用〈礼金〉。罚款是交给政府的罚金，送给新人的钱要说“礼金”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机昨天交了一张罚款。", "corrected_sentence": "司机昨天交了一笔罚款。", "error_description": "量词错误：“罚款”指一笔钱，量词应用“笔”，不能用“张”（“张”多用于纸张、票据）。错误形式是“一张罚款”，正确形式是“一笔罚款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前交着罚款。", "corrected_sentence": "我以前交过罚款。", "error_description": "“着”用错：表示经历的“过”要紧跟动词，说“交过罚款”；此处误用“着”，“着”表示持续状态，与“以前”的经历意思矛盾，应改为“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
