INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25952, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进一个地方。", "primary_collocate": null, "pronunciation": "tóu fàng", "ipa": "tʰoʊ˧˥ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请把旧电池投放到红色的箱子里。", "target_word": "投放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投放硬币后，机器才会开始工作。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往水池里投放了一些药片。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要往这个口里投放别的东西。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们把用过的纸投放到可回收桶里。", "target_word": "投放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园在湖里投放了几只天鹅。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快递员把包裹投放到智能柜里。", "target_word": "投放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在鱼缸里投放了新的水草。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验员往杯子里投放一颗小石子。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在花园里投放了一些老鼠药。", "target_word": "投放", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "投放了", "label": "体标：完成"}, {"form": "投放过", "label": "体标：经历"}, {"form": "投放量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把具体的东西放入箱子、水里等某个具体地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b90b6993-4408-4414-a5ca-24fcb8214168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投放", "is_correct": true, "explanation": "正确：“投放到红色的箱子里”表示把旧电池放进指定的回收箱，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂，不能用来说把电池放进箱子里。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：电池不能被烘烤后放进箱子，与“旧电池”的语境不符。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是珍藏的意思，与把旧电池送去回收的语境相反。"}], "explanations": {"投放": "正确：“投放到红色的箱子里”表示把旧电池放进指定的回收箱，符合句意。", "挂": "搭配：“挂”指悬挂，不能用来说把电池放进箱子里。", "烘烤": "语义：电池不能被烘烤后放进箱子，与“旧电池”的语境不符。", "收藏": "语义：“收藏”是珍藏的意思，与把旧电池送去回收的语境相反。"}, "sentence_index": 0, "correct_answer": "投放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把帽子投放在门口。", "explanation": "这里应该用〈挂〉。投放强调投入某处，不能用于悬挂物品。"}, {"text": "墙上投放了一张照片。", "explanation": "这里应该用〈贴〉。投放指投入某处，不能用于把照片固定在墙面上。"}, {"text": "他把垃圾投放在地上。", "explanation": "这里应该用〈扔〉。投放表示有意放入指定地点，不能用于随手扔在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投放", "is_correct": true, "explanation": "正确：“投放到智能柜里”表示把包裹放进柜子，符合送件的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：包裹送入智能柜前不需要“修理”，与语境不符。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”针对表面，不能说擦拭包裹后放进柜子。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”针对植物或土地，不能用于包裹。"}], "explanations": {"投放": "正确：“投放到智能柜里”表示把包裹放进柜子，符合送件的语境。", "修理": "语义：包裹送入智能柜前不需要“修理”，与语境不符。", "擦拭": "搭配：“擦拭”针对表面，不能说擦拭包裹后放进柜子。", "浇灌": "语义：“浇灌”针对植物或土地，不能用于包裹。"}, "sentence_index": 6, "correct_answer": "投放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他朝篮筐投放了一个篮球。", "explanation": "这里应该用〈投篮〉。投放表示把东西放进某个地方，不能用于把球投进篮筐。"}, {"text": "他用力朝门口投放了一块石头。", "explanation": "这里应该用〈投掷〉。投放表示有意放入某处，不能用于用力扔出去。"}, {"text": "这个孩子在草地上投放了一个风筝。", "explanation": "这里应该用〈放飞〉。投放表示把东西放进某个地方，不用于放飞风筝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一张纸投放了进回收箱。", "corrected_sentence": "他把一张纸投放进了回收箱。", "error_description": "错误形式：“投放了进”。正确形式：“投放进了”。“了”应放在结果补语“进”之后，不能插在“投放”和“进”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快递员把这个包裹投放着进了智能柜。", "corrected_sentence": "快递员把这个包裹投放进了智能柜。", "error_description": "错误形式：“投放着进了”。正确形式：“投放进了”。“着”表示动作持续的状态，这里是已经完成的投放，不能加“着”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
