INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海里的动物和植物。", "primary_collocate": null, "pronunciation": "hǎi yáng shēng wù", "ipa": "xai̯˨˩˦ jɑŋ˧˥ ʂɤŋ˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "海洋生物包括海里的鱼和海草。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水族馆里有很多漂亮的海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明最喜欢的海洋生物是海豚。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水变热，海洋生物会很难受。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画一种海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的小孩在沙滩上找海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家坐船去海底研究海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋生物不能离开海水生活。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了一百种海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜水的时候，我看到了很多海洋生物。", "target_word": "海洋生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "海里的动物和植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b90b6993-4408-4414-a5ca-24fcb8214168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋生物", "is_correct": true, "explanation": "海洋生物：指海里的动物和植物，与「包括海里的鱼和海草」一致。"}, {"text": "陆地生物", "is_correct": false, "explanation": "语义：「陆地生物」与句中「海里的鱼和海草」相矛盾，句意不通。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：「包括」后面要列举生物，海水是水，不说包括鱼和海草。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是生物，不能包括鱼和海草，句意不通。"}], "explanations": {"海洋生物": "海洋生物：指海里的动物和植物，与「包括海里的鱼和海草」一致。", "陆地生物": "语义：「陆地生物」与句中「海里的鱼和海草」相矛盾，句意不通。", "海水": "搭配：「包括」后面要列举生物，海水是水，不说包括鱼和海草。", "天气": "语义：天气不是生物，不能包括鱼和海草，句意不通。"}, "sentence_index": 0, "correct_answer": "海洋生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的海洋生物很新鲜。", "explanation": "这里应该用〈海鲜〉。海洋生物是生物学概念，指生物本身，饭店卖的食材要说海鲜。"}, {"text": "这艘船在海洋生物上航行。", "explanation": "这里应该用〈海上〉。海洋生物指海里的动物和植物，船航行的是海面这个地方，不能说在海洋生物上。"}, {"text": "草原上生长着很多海洋生物。", "explanation": "这里应该用〈植物〉。海洋生物指海里生活的生物，草原上的植物不能说成海洋生物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋生物", "is_correct": true, "explanation": "海洋生物：科学家在海底研究的对象，与句意一致。"}, {"text": "明星", "is_correct": false, "explanation": "语义：「明星」是演艺人员，科学家不会去海底研究明星，句意不通。"}, {"text": "动物园", "is_correct": false, "explanation": "搭配：「研究」后面不接动物园，海底也不会有动物园。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：在海底研究汽车，与「坐船去海底」的语境不合。"}], "explanations": {"海洋生物": "海洋生物：科学家在海底研究的对象，与句意一致。", "明星": "语义：「明星」是演艺人员，科学家不会去海底研究明星，句意不通。", "动物园": "搭配：「研究」后面不接动物园，海底也不会有动物园。", "汽车": "搭配：在海底研究汽车，与「坐船去海底」的语境不合。"}, "sentence_index": 6, "correct_answer": "海洋生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "沙漠里走着很多海洋生物。", "explanation": "这里应该用〈骆驼〉。骆驼生活在沙漠，海洋生物指海里生活的生物，不能用于沙漠。"}, {"text": "森林里住着很多海洋生物。", "explanation": "这里应该用〈野生动物〉。海洋生物指生活在海里的生物，森林里的动物不能说成海洋生物。"}, {"text": "教室里坐着很多海洋生物。", "explanation": "这里应该用〈学生〉。海洋生物指海里生活的生物，不能用来指教室里的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水族馆里养着很多有趣海洋生物。", "corrected_sentence": "这个水族馆里养着很多有趣的海洋生物。", "error_description": "「有趣」修饰名词时要加「的」。「有趣海洋生物」应改为「有趣的海洋生物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "潜水员在海底拍下了很多海洋生物们。", "corrected_sentence": "潜水员在海底拍下了很多海洋生物。", "error_description": "「们」只用于指人或拟人的群体。海洋生物是集合名词，表示多数用「很多」，不能加「们」，应改为「潜水员在海底拍下了很多海洋生物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
