INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了做成一件事情而使用的办法。", "primary_collocate": null, "pronunciation": "shǒu duàn", "ipa": "ʂoʊ˨˩˦ twan˥˩", "syllable_count": 2, "sentences": [{"text": "为了让孩子早点睡觉，妈妈换了个手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用了一个聪明的手段赢了比赛。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手段很简单，大家都能用。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要完成这件事，我们得换个手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫用了一个小手段拿到了鱼。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手段很多，总能把事情做成。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手段没有用，我们再想别的。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省钱，他们用了不少手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用哭的手段让妈妈买玩具。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要成功，就得先选好手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为做成一件事而用的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "正确：“换了个手段”指换一种办法，与“为了让孩子早点睡觉”相符。"}, {"text": "手表", "is_correct": false, "explanation": "语义：换手表与让孩子早点睡觉没有关系，不能作为达到目的的办法。"}, {"text": "体温计", "is_correct": false, "explanation": "语义：体温计用来测量体温，换它不能让孩子早点睡觉。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”与让孩子早点睡觉的办法没有关系，换字体不能达到这个目的。"}], "explanations": {"手段": "正确：“换了个手段”指换一种办法，与“为了让孩子早点睡觉”相符。", "手表": "语义：换手表与让孩子早点睡觉没有关系，不能作为达到目的的办法。", "体温计": "语义：体温计用来测量体温，换它不能让孩子早点睡觉。", "字体": "语义：“字体”与让孩子早点睡觉的办法没有关系，换字体不能达到这个目的。"}, "sentence_index": 0, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个手段重三公斤。", "explanation": "这里应该用〈工具〉。“手段”指为做成一件事而用的办法，是抽象的，没有重量，不能说“重三公斤”。"}, {"text": "他的手段是用木头做的。", "explanation": "这里应该用〈工具〉。“手段”是抽象的办法，不能用木头做。"}, {"text": "他是我最好的手段。", "explanation": "这里应该用〈伙伴〉。“手段”指办法，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "正确：“这个手段”指前面提到的办法，没有用就再想别的，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能作为办法来评价有用或没用，与“再想别的”也不呼应，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用“有用、没有用”来评价。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是办法，“这个太阳没有用”的说法不通。"}], "explanations": {"手段": "正确：“这个手段”指前面提到的办法，没有用就再想别的，句意通顺。", "天空": "语义：“天空”不能作为办法来评价有用或没用，与“再想别的”也不呼应，句意不通。", "天气": "搭配：“天气”不能用“有用、没有用”来评价。", "太阳": "语义：太阳是天体，不是办法，“这个太阳没有用”的说法不通。"}, "sentence_index": 6, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的手段被蚊子咬了，很痒。", "explanation": "这里应该用〈手〉。“手段”指做成事情的办法，不是身体部位。"}, {"text": "他的手段是成为冠军。", "explanation": "这里应该用〈目标〉。“手段”是达到目的的办法，“成为冠军”是最终目标。"}, {"text": "我们约在手段见面。", "explanation": "这里应该用〈地点〉。“手段”是抽象的办法，不能作为见面的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想出了一只新手段。", "corrected_sentence": "他们想出了一个新手段。", "error_description": "量词错误：“手段”用“个”或“种”计量，“只”不能用于“手段”。正确：一个新手段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想到了一个新手段们。", "corrected_sentence": "他想到了一个新手段。", "error_description": "词尾错误：“们”只用于指人，“手段”不能加“们”。正确：一个新手段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
