INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25962, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有好处。", "primary_collocate": null, "pronunciation": "yǒu yì", "ipa": "joʊ˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "早睡对身体有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "牛奶对骨头有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "少吃糖对牙齿有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多和朋友聊天对心情有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "慢慢吃饭对胃很有益。", "target_word": "有益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，喝点绿茶对心脏有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公园里走一走，对老人有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说学外语对工作很有益。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛让他得到了有益的经验。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对孩子有益的书，我们都买了。", "target_word": "有益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有益于", "label": "带介词的形式"}, {"form": "有益的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "对身体、心情、工作等有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b90b6993-4408-4414-a5ca-24fcb8214168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益（yǒu yì）：有好处，与本义一致。"}, {"text": "右翼", "is_correct": false, "explanation": "右翼（yòu yì）：第一个音节声调不同，yǒu 为第三声，yòu 为第四声，意思是右边的翅膀或右翼。"}, {"text": "游艺", "is_correct": false, "explanation": "游艺（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是游戏、娱乐活动。"}, {"text": "游弋", "is_correct": false, "explanation": "游弋（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是在水中来回巡游。"}], "explanations": {"有益": "有益（yǒu yì）：有好处，与本义一致。", "右翼": "右翼（yòu yì）：第一个音节声调不同，yǒu 为第三声，yòu 为第四声，意思是右边的翅膀或右翼。", "游艺": "游艺（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是游戏、娱乐活动。", "游弋": "游弋（yóu yì）：第一个音节声调不同，yóu 为第二声，意思是在水中来回巡游。"}, "sentence_index": null, "correct_answer": "有益"}, "level_3": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益：早睡对身体有好处，与前文语境一致。"}, {"text": "有趣", "is_correct": false, "explanation": "搭配：「有趣」形容事物令人感兴趣，不能说「对身体有趣」。"}, {"text": "有名", "is_correct": false, "explanation": "语义：「有名」指名气大，身体的好处与名气无关，句意不通。"}, {"text": "有礼", "is_correct": false, "explanation": "搭配：「有礼」形容人懂礼貌，身体不能「有礼」。"}], "explanations": {"有益": "有益：早睡对身体有好处，与前文语境一致。", "有趣": "搭配：「有趣」形容事物令人感兴趣，不能说「对身体有趣」。", "有名": "语义：「有名」指名气大，身体的好处与名气无关，句意不通。", "有礼": "搭配：「有礼」形容人懂礼貌，身体不能「有礼」。"}, "sentence_index": 0, "correct_answer": "有益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次进攻很有益。", "explanation": "这里应该用〈有效〉。有益说事物对人有好处，进攻的成效要用有效，不说有益。"}, {"text": "今天下午我很有益，我们去看电影吧。", "explanation": "这里应该用〈有空〉。有益说事物对人有好处，表示时间充裕、可以做事要用有空，不说人很有益。"}, {"text": "这是一条很有益的证据。", "explanation": "这里应该用〈有力〉。有力形容证据、论证有说服力，证据不说有益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25962, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益（yǒu yì）：有好处，与本义一致。"}, {"text": "优异", "is_correct": false, "explanation": "优异（yōu yì）：第一个音节声调不同，yōu 为第一声，意思是优秀、出色。"}, {"text": "游移", "is_correct": false, "explanation": "游移（yóu yí）：两个音节声调都不同，意思是犹豫不定。"}, {"text": "有戏", "is_correct": false, "explanation": "有戏（yǒu xì）：第二个音节声母不同，xì 与 yì 的声母不同，意思是有希望。"}], "explanations": {"有益": "有益（yǒu yì）：有好处，与本义一致。", "优异": "优异（yōu yì）：第一个音节声调不同，yōu 为第一声，意思是优秀、出色。", "游移": "游移（yóu yí）：两个音节声调都不同，意思是犹豫不定。", "有戏": "有戏（yǒu xì）：第二个音节声母不同，xì 与 yì 的声母不同，意思是有希望。"}, "sentence_index": null, "correct_answer": "有益"}, "level_3": {"options": [{"text": "有益", "is_correct": true, "explanation": "有益：在公园里走一走对老人有好处，与语境一致。"}, {"text": "有序", "is_correct": false, "explanation": "搭配：「有序」形容事情有条理，不用来说老人。"}, {"text": "有声", "is_correct": false, "explanation": "语义：「有声」指有声音，与对老人的好处无关，句意不通。"}, {"text": "有色", "is_correct": false, "explanation": "语义：「有色」指带颜色，对老人不能说有色，句意不通。"}], "explanations": {"有益": "有益：在公园里走一走对老人有好处，与语境一致。", "有序": "搭配：「有序」形容事情有条理，不用来说老人。", "有声": "语义：「有声」指有声音，与对老人的好处无关，句意不通。", "有色": "语义：「有色」指带颜色，对老人不能说有色，句意不通。"}, "sentence_index": 6, "correct_answer": "有益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手很有益。", "explanation": "这里应该用〈有名〉。有益说事物对人有好处，形容歌手的名气要用有名，不说有益。"}, {"text": "我对音乐很有益。", "explanation": "这里应该用〈有兴趣〉。有益说对身心或健康有好处，表示对事物感兴趣要用有兴趣。"}, {"text": "这块石头很有益。", "explanation": "这里应该用〈坚硬〉。有益说事物对人有好处，描述石头的质地要用坚硬，不说有益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃蔬菜身体有益。", "corrected_sentence": "吃蔬菜对身体有益。", "error_description": "错误形式：“吃蔬菜身体有益”。正确形式：“吃蔬菜对身体有益”。“有益”表示对某对象有好处，受益对象要用介词“对”引出，“对”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早起散步老人很有益。", "corrected_sentence": "早起散步对老人很有益。", "error_description": "「有益」前面要用介词「对」引出受益对象，「对」不能省略。应改为「早起散步对老人很有益」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
