INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面，不是水的地方。", "primary_collocate": null, "pronunciation": "lù dì", "ipa": "lu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "船靠岸了，大家走上陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上看不到陆地。", "target_word": "陆地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼不能在陆地上生活。", "target_word": "陆地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经过三天的航行，船终于靠近了陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小岛离陆地很远。", "target_word": "陆地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乌龟可以在水里，也可以在陆地上。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从飞机上往下看，陆地像一张地图。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了船，他终于踏上了陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的陆地上有很多树。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在海上漂了好几天，才回到陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块陆地", "label": "量词"}, {"form": "陆地动物", "label": "复合"}, {"form": "陸地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水以外的地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陆地", "is_correct": true, "explanation": "陆地指水以外的地面，船靠岸后大家走上的就是陆地。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”在上方，人不能走上天空，与船靠岸的情境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是可以行走的地方，不能走上去。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指小东西，不是可以走上去的地方，与船靠岸的情境不合。"}], "explanations": {"陆地": "陆地指水以外的地面，船靠岸后大家走上的就是陆地。", "天空": "语义：“天空”在上方，人不能走上天空，与船靠岸的情境不合。", "歌曲": "语义：“歌曲”不是可以行走的地方，不能走上去。", "玩意儿": "语义：“玩意儿”指小东西，不是可以走上去的地方，与船靠岸的情境不合。"}, "sentence_index": 0, "correct_answer": "陆地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔民们在陆地上划船，玩得很开心。", "explanation": "这里应该用〈水里〉。划船要在水里进行，陆地是地面，不是水的地方。"}, {"text": "海豚在陆地上跳跃，欢快地玩耍。", "explanation": "这里应该用〈大海〉。海豚生活在海中，应说大海；陆地是地面，不是水的地方。"}, {"text": "他一下子跳进了陆地。", "explanation": "这里应该用〈河里〉。跳进河里是跳入水中，应说河里；陆地是地面，不是水的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陆地", "is_correct": true, "explanation": "陆地指水以外的地面，从高处看，它呈现出像地图一样的形状。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是地形，从高处看不会像地图一样展开。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：“歌声”是听得见的声音，不能从高处看见，也不像地图。"}, {"text": "大伙儿", "is_correct": false, "explanation": "语义：“大伙儿”指一群人，从飞机上往下看，人群不会像一张地图。"}], "explanations": {"陆地": "陆地指水以外的地面，从高处看，它呈现出像地图一样的形状。", "鸡蛋": "语义：“鸡蛋”不是地形，从高处看不会像地图一样展开。", "歌声": "语义：“歌声”是听得见的声音，不能从高处看见，也不像地图。", "大伙儿": "语义：“大伙儿”指一群人，从飞机上往下看，人群不会像一张地图。"}, "sentence_index": 6, "correct_answer": "陆地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鲸鱼一直生活在陆地上。", "explanation": "这里应该用〈海里〉。鲸鱼生活在海中，陆地是地面，不是水的地方。"}, {"text": "他用水桶把陆地装走了。", "explanation": "这里应该用〈泥土〉。装走的是泥土，陆地是大片地表，不能用水桶装走。"}, {"text": "这口陆地很深，要用绳子才能打上水。", "explanation": "这里应该用〈井〉。陆地是地面，不能说深，应说“这口井很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔民们陆地上搭了一个帐篷。", "corrected_sentence": "渔民们在陆地上搭了一个帐篷。", "error_description": "位置错误：“陆地”作处所时前面要加“在”，应说“在陆地上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在陆地的上，望着远方的大海。", "corrected_sentence": "他站在陆地上，望着远方的大海。", "error_description": "方位词错误：“陆地”后接方位词“上”时不加“的”，应说“陆地上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
