INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或事物走过的道路或者经历的事情。", "primary_collocate": null, "pronunciation": "lì chéng", "ipa": "li˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书讲了老人一生的历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的创业历程很不容易。", "target_word": "历程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的成长历程让妈妈很高兴。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想写下自己的学习历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的发展历程很长。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们介绍了那位科学家的研究历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店走过了一百年的历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回头看这段历程，他笑了。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常说起自己的人生历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影记录了球队的奋斗历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段历程", "label": "量词"}, {"form": "人生历程", "label": "复合"}, {"form": "歷程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物一路走过、经历的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。"}, {"text": "日程", "is_correct": false, "explanation": "声调无关的单音位混淆：rì chéng 与 lì chéng 仅声母 r/l 不同，意思是每天的安排。"}, {"text": "礼成", "is_correct": false, "explanation": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是典礼结束。"}, {"text": "里程", "is_correct": false, "explanation": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是路程的长度。"}], "explanations": {"历程": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。", "日程": "声调无关的单音位混淆：rì chéng 与 lì chéng 仅声母 r/l 不同，意思是每天的安排。", "礼成": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是典礼结束。", "里程": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是路程的长度。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指一生走过的道路或经历，与“一生”搭配，指老人的人生经历。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指小东西，不能表示老人一生的经历。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能是一本书讲述的人生内容。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与讲老人一生的经历无关。"}], "explanations": {"历程": "历程指一生走过的道路或经历，与“一生”搭配，指老人的人生经历。", "玩意儿": "语义：“玩意儿”指小东西，不能表示老人一生的经历。", "价格": "语义：“价格”指商品的钱数，不能是一本书讲述的人生内容。", "体温": "语义：“体温”指身体的温度，与讲老人一生的经历无关。"}, "sentence_index": 0, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙的历程很亮。", "explanation": "这里应该用〈颜色〉。说墙亮不亮，指的是颜色；历程指一个人或事物走过的道路或经历，不能形容颜色。"}, {"text": "这个历程里人很多。", "explanation": "这里应该用〈市场〉。人很多的场所是市场；历程指走过的道路或经历的事情，不指场所。"}, {"text": "他用钥匙打开了历程。", "explanation": "这里应该用〈门〉。钥匙能打开的是门；历程指走过的道路或经历的事情，不是可以打开的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。"}, {"text": "立正", "is_correct": false, "explanation": "lì zhèng 与 lì chéng 第二音节声母与声调不同（zh 与 ch），立正指站直的姿势。"}, {"text": "议程", "is_correct": false, "explanation": "yì chéng 与 lì chéng 仅声母不同（y 与 l），议程指会议的进行安排。"}, {"text": "力争", "is_correct": false, "explanation": "lì zhēng 与 lì chéng 第二音节声母与声调不同（zh 与 ch，一声与二声），力争指努力争取。"}], "explanations": {"历程": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。", "立正": "lì zhèng 与 lì chéng 第二音节声母与声调不同（zh 与 ch），立正指站直的姿势。", "议程": "yì chéng 与 lì chéng 仅声母不同（y 与 l），议程指会议的进行安排。", "力争": "lì zhēng 与 lì chéng 第二音节声母与声调不同（zh 与 ch，一声与二声），力争指努力争取。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指走过的道路或经历，老店走过一百年的经历可以说历程。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格和情绪，老店不能走过一百年的脾气。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“走过”可以用于道路、岁月，不搭配“数量”。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”是空气的冷热，与老店走过的时间无关。"}], "explanations": {"历程": "历程指走过的道路或经历，老店走过一百年的经历可以说历程。", "脾气": "语义：“脾气”指性格和情绪，老店不能走过一百年的脾气。", "数量": "搭配：“走过”可以用于道路、岁月，不搭配“数量”。", "气温": "语义：“气温”是空气的冷热，与老店走过的时间无关。"}, "sentence_index": 6, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的历程很冷，冻得发抖。", "explanation": "这里应该用〈手〉。冻得发抖、感到冷的是身体部位；历程指走过的道路或经历的事情，不能形容身体的冷。"}, {"text": "历程很烫，小心别碰。", "explanation": "这里应该用〈汤〉。这句说的是可以烫人的东西；历程指经历的过程，不是可以触碰的东西。"}, {"text": "孩子们在历程里踢球。", "explanation": "这里应该用〈操场〉。孩子们踢球的地方是操场；历程指经历的过程或道路，不能表示场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她回顾了一段漫长地历程。", "corrected_sentence": "她回顾了一段漫长的历程。", "error_description": "修饰语错误：“漫长”作定语修饰名词“历程”，应用“的”连接；用“地”（标示状语）错误。应说“漫长的历程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于走完了一颗艰难的历程。", "corrected_sentence": "他们终于走完了一段艰难的历程。", "error_description": "量词错误：“历程”用“段”计量，应说“一段艰难的历程”；“颗”用于圆粒状的东西，不能用于历程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西里面出现很多小泡泡。", "primary_collocate": null, "pronunciation": "fā pào", "ipa": "fa˥ pʰau˥˩", "syllable_count": 2, "sentences": [{"text": "沐浴露一揉就发泡，味道也好闻。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水泥里加了药粉，就会发泡变轻。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂用机器让塑料发泡，做成软垫。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的洗碗液发泡不多。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把洗发水倒在手上，一搓就发泡了。", "target_word": "发泡", "complexity_tier": "T3", "furigana": "wǒ bǎ xǐ fà shuǐ dào zài shǒu shàng, yì cuō jiù fā pào le.", "sentence_source": "generated"}, {"text": "这罐饮料摇过以后会发泡。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油漆发泡了，墙面看起来不平。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋清用打蛋器搅，很快就发泡。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种材料一加热就发泡，体积变大。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这盆水里加了洗洁精，搅几下就发泡了。", "target_word": "发泡", "complexity_tier": "T3", "furigana": "zhè pén shuǐ lǐ jiā le xǐ jié jīng, jiǎo jǐ xià jiù fā pào le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "发泡了", "label": "体标"}, {"form": "发泡剂", "label": "复合"}, {"form": "發泡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西里面出现许多小泡泡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09206b64-ef69-428b-a35b-eee9be641633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发泡", "is_correct": true, "explanation": "发泡（fā pào）：东西里面出现很多小泡泡。"}, {"text": "发报", "is_correct": false, "explanation": "发报（fā bào）与 fā pào 只差声母 b/p，声调相同，意思是拍发电报。"}, {"text": "发包", "is_correct": false, "explanation": "发包（fā bāo）与 fā pào 声母不同（b/p），声调也不同，意思是把工程或业务承包出去。"}, {"text": "发票", "is_correct": false, "explanation": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}], "explanations": {"发泡": "发泡（fā pào）：东西里面出现很多小泡泡。", "发报": "发报（fā bào）与 fā pào 只差声母 b/p，声调相同，意思是拍发电报。", "发包": "发包（fā bāo）与 fā pào 声母不同（b/p），声调也不同，意思是把工程或业务承包出去。", "发票": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}, "sentence_index": null, "correct_answer": "发泡"}, "level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“一揉就发泡”指沐浴露揉搓后产生小泡泡，与“味道也好闻”的描述一致。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指遇冷变硬，与“一揉”的动作不符，沐浴露揉后不会冻结。"}, {"text": "烘干", "is_correct": false, "explanation": "搭配：“烘干”指烘去水分，与“一揉就”的动作和结果不搭配。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”需要人主动切割，且会把物体割开，与句中“揉”的情况不符。"}], "explanations": {"发泡": "“一揉就发泡”指沐浴露揉搓后产生小泡泡，与“味道也好闻”的描述一致。", "冻结": "语义：“冻结”指遇冷变硬，与“一揉”的动作不符，沐浴露揉后不会冻结。", "烘干": "搭配：“烘干”指烘去水分，与“一揉就”的动作和结果不搭配。", "切开": "语义：“切开”需要人主动切割，且会把物体割开，与句中“揉”的情况不符。"}, "sentence_index": 0, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁锅放在潮湿的地方，很快就发泡了。", "explanation": "这里应该用〈生锈〉。铁遇潮氧化生成铁锈，应说“生锈”；“发泡”指东西里出现很多小泡泡，不能形容金属氧化。"}, {"text": "石头长期暴露在风雨中，会发泡。", "explanation": "这里应该用〈风化〉。石头受风雨侵蚀逐渐变松，应说“风化”；“发泡”指东西里出现很多小泡泡，与石头变松无关。"}, {"text": "盐放进水里会发泡。", "explanation": "这里应该用〈溶解〉。盐溶于水并不产生泡沫，“发泡”不能用于此情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“油漆发泡了”指油漆膜鼓起成泡，导致墙面不平，句意通顺。"}, {"text": "抹平", "is_correct": false, "explanation": "语义：“抹平”表示使表面平整，与句末的“墙面看起来不平”矛盾。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指加热到水沸腾，油漆不会被煮沸，与句意不符。"}, {"text": "刷新", "is_correct": false, "explanation": "搭配：“刷新”指更新、提高，不能用来描述油漆的状态，搭配不当。"}], "explanations": {"发泡": "“油漆发泡了”指油漆膜鼓起成泡，导致墙面不平，句意通顺。", "抹平": "语义：“抹平”表示使表面平整，与句末的“墙面看起来不平”矛盾。", "煮沸": "语义：“煮沸”指加热到水沸腾，油漆不会被煮沸，与句意不符。", "刷新": "搭配：“刷新”指更新、提高，不能用来描述油漆的状态，搭配不当。"}, "sentence_index": 6, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玻璃杯遇到热水就发泡了。", "explanation": "这里应该用〈开裂〉。玻璃骤遇热水会裂开，应说“开裂”；“发泡”指东西里出现很多小泡泡，不能形容玻璃破裂。"}, {"text": "冰块放在太阳下，很快就发泡了。", "explanation": "这里应该用〈融化〉。冰块受热变成水，应说“融化”；“发泡”指东西里出现很多小泡泡，不能表示冰变成水。"}, {"text": "牛奶加入柠檬汁后，很快就发泡了。", "explanation": "这里应该用〈凝固〉。牛奶遇酸会凝结成块，并不产生泡沫，不能用“发泡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶洗洁精一摇就被发泡了。", "corrected_sentence": "这瓶洗洁精一摇就发泡了。", "error_description": "“发泡”是不及物动词，不能用“被”构成被动句，应说“就发泡了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种洗洁精发泡的很快。", "corrected_sentence": "这种洗洁精发泡得很快。", "error_description": "“发泡”后面带程度补语时要用助词「得」，不能用「的」，应说“发泡得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
