INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律效力就是一条法律规则能管人的力量。", "primary_collocate": null, "pronunciation": "fǎ lǜ xiào lì", "ipa": "fa˨˩˦ ly˥˩ ɕjɑʊ˥˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "法律效力就是法律能管人的力量。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规则有法律效力，大家都要守。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有法律效力，规则就管不了人。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张通知没有法律效力。", "target_word": "法律效力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律效力让每个人都要守规矩。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个合同有法律效力。", "target_word": "法律效力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件有法律效力，请认真读。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的玩笑没有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签了字，这份合同就有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新规定已经有了法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "一条法律规则能约束人、让人必须遵守的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道德规范", "is_correct": false, "explanation": "语义：道德靠自觉而非法律强制，“道德规范就是法律能管人的力量”不成立。"}, {"text": "法律效力", "is_correct": true, "explanation": "正确。句中的定义是“法律能管人的力量”，即“法律效力”。"}, {"text": "语言文字", "is_correct": false, "explanation": "语义：语言文字本身不具备约束力，句意不成立。"}, {"text": "法律条文", "is_correct": false, "explanation": "搭配：“条文”指文字内容，不能用“力量”来描述它。"}], "explanations": {"道德规范": "语义：道德靠自觉而非法律强制，“道德规范就是法律能管人的力量”不成立。", "法律效力": "正确。句中的定义是“法律能管人的力量”，即“法律效力”。", "语言文字": "语义：语言文字本身不具备约束力，句意不成立。", "法律条文": "搭配：“条文”指文字内容，不能用“力量”来描述它。"}, "sentence_index": 0, "correct_answer": "法律效力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他违反了规定，必须承担法律效力。", "explanation": "这里应该用〈法律责任〉。效力指规则的约束力，违规的人承担的是责任，不能说“承担法律效力”。"}, {"text": "这种面膜的法律效力很明显。", "explanation": "这里应该用〈效果〉。效力指法律规则的约束力，化妆品的作用应说效果，不能说“法律效力很明显”。"}, {"text": "每位员工都要履行法律效力。", "explanation": "这里应该用〈法律义务〉。效力是规则的约束力，员工要履行的是义务，不能说“履行法律效力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：文件没有香味，这一说法与句意不符。"}, {"text": "法律效力", "is_correct": true, "explanation": "正确。“这份文件有法律效力”说明文件具有约束力，与句意相符。"}, {"text": "甜度", "is_correct": false, "explanation": "搭配：“甜度”只用于食物等的味道，不能用于文件。"}, {"text": "体温", "is_correct": false, "explanation": "语义：文件没有体温，句子不成立。"}], "explanations": {"香味": "语义：文件没有香味，这一说法与句意不符。", "法律效力": "正确。“这份文件有法律效力”说明文件具有约束力，与句意相符。", "甜度": "搭配：“甜度”只用于食物等的味道，不能用于文件。", "体温": "语义：文件没有体温，句子不成立。"}, "sentence_index": 6, "correct_answer": "法律效力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校给这名学生颁发了法律效力。", "explanation": "这里应该用〈毕业证书〉。颁发的是证书，“效力”不能被颁发。"}, {"text": "她在这家公司的法律效力很强。", "explanation": "这里应该用〈能力〉。效力指法律规则的约束力，员工的工作本事应说能力，不能说“法律效力很强”。"}, {"text": "这位老师的法律效力很高。", "explanation": "这里应该用〈水平〉。效力指法律规则的约束力，老师的教学能力应说水平，不能说“法律效力很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项规定是法律效力。", "corrected_sentence": "这项规定有法律效力。", "error_description": "错误形式：“是法律效力”；正确形式：“有法律效力”。“是”表示等同，后接名词；“法律效力”是规则的约束力，表示拥有要用动词“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份文件很法律效力。", "corrected_sentence": "这份文件很有法律效力。", "error_description": "错误：“很”后面要接形容词，“法律效力”是名词，应加“有”，说“很有法律效力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
