INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时间表是一张纸或一个表格，上面写好了每件事情要在什么时候做。", "primary_collocate": null, "pronunciation": "shí jiān biǎo", "ipa": "ʂɨ˧˥ tɕjɛn˥ pjɑʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我的桌子上贴着一张时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把时间表发给了每个学生。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看看时间表，明天上午我们有什么课？", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张时间表上写着每天的活动。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我做了一张学习时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把时间表放在书包里了。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间表上写着，三点开会。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都看一下墙上的时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把时间表带回家给爸爸看。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张时间表我是用红笔写的。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张时间表", "label": "量词"}, {"form": "一份时间表", "label": "量词"}], "register": "中性", "sense_fingerprint": "写着每件事时间的一张纸或表格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间表", "is_correct": true, "explanation": "正确。“桌子上贴着一张时间表”指桌上贴着写有时间安排的纸。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是卧具，不能贴在桌子上。"}, {"text": "网", "is_correct": false, "explanation": "语义：网是编织物，与句中“贴着”和桌上的情境不符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“贴着”只用于纸张等扁平物，不能与“椅子”搭配。"}], "explanations": {"时间表": "正确。“桌子上贴着一张时间表”指桌上贴着写有时间安排的纸。", "床": "语义：床是卧具，不能贴在桌子上。", "网": "语义：网是编织物，与句中“贴着”和桌上的情境不符。", "椅子": "搭配：“贴着”只用于纸张等扁平物，不能与“椅子”搭配。"}, "sentence_index": 0, "correct_answer": "时间表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看了一下手上的时间表，已经三点了。", "explanation": "这里应该用〈手表〉。手表能告诉人现在几点；时间表是写着事情安排的纸，戴不到手上。"}, {"text": "他在时间表上写了一封长信寄给朋友。", "explanation": "这里应该用〈信纸〉。写信要用信纸；时间表是列出每件事时间的表格。"}, {"text": "墙上的时间表每过一秒就响一下。", "explanation": "这里应该用〈钟〉。钟会走动、会响；时间表是一张纸，不会响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间表", "is_correct": true, "explanation": "正确。“时间表上写着”指表格上写有内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是可以书写的平面，句中“写着”不合。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“写着”的对象应是可书写的平面，河水不能与之搭配。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不能用来写字，与“写着，三点开会”冲突。"}], "explanations": {"时间表": "正确。“时间表上写着”指表格上写有内容。", "天气": "语义：天气是气象状况，不是可以书写的平面，句中“写着”不合。", "河水": "搭配：“写着”的对象应是可书写的平面，河水不能与之搭配。", "云": "语义：云不能用来写字，与“写着，三点开会”冲突。"}, "sentence_index": 6, "correct_answer": "时间表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员递给我们一张时间表，让我们点菜。", "explanation": "这里应该用〈菜单〉。菜单是列出可点菜品的纸；时间表列出活动的时间安排，不能用来点菜。"}, {"text": "收银员打印了一张时间表，上面写着总金额。", "explanation": "这里应该用〈收据〉。收据记录付款金额；时间表记录活动时间，不写金额。"}, {"text": "他拿着一张时间表找路。", "explanation": "这里应该用〈地图〉。地图标示道路与方位，能用来找路；时间表只列出活动时间，帮不上找路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的墙上贴着一座时间表。", "corrected_sentence": "我的墙上贴着一张时间表。", "error_description": "量词错误：纸质时间表应用“张”，“座”用于山、建筑等大型物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把新的时间表放在抽屉里过。", "corrected_sentence": "我把新的时间表放在抽屉里了。", "error_description": "体貌错误：“放在抽屉里”是已经完成的动作，应用“了”；“过”表示曾经有过的经历，不能用于此，应改为“放在抽屉里了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
