INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家自己定的法律。", "primary_collocate": null, "pronunciation": "guó nèi fǎ", "ipa": "kuɔ˧˥ neɪ˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "每个国家都有自己的国内法。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国内法是本国人要遵守的法律。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在中国，外国人也要遵守国内法。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国内法很严格。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国内法不能管别的国家。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学习中国的国内法。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行前，你最好了解目的地国家的国内法。", "target_word": "国内法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内法是一个国家自己定的。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部国内法去年改了。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家的国内法不一样。", "target_word": "国内法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "國內法", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个国家自己制定、本国人要遵守的法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内法", "is_correct": true, "explanation": "正确：每个国家自己制定的法律就是国内法。"}, {"text": "国际法", "is_correct": false, "explanation": "语义：「国际法」是国家之间共同遵守的规则，不是每个国家自己的法律，句意不合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：国家不会「拥有」手机这类东西，句意不通。"}, {"text": "行当", "is_correct": false, "explanation": "语域：「行当」是口语，而且不能指法律，与书面语句子不合。"}], "explanations": {"国内法": "正确：每个国家自己制定的法律就是国内法。", "国际法": "语义：「国际法」是国家之间共同遵守的规则，不是每个国家自己的法律，句意不合。", "手机": "语义：国家不会「拥有」手机这类东西，句意不通。", "行当": "语域：「行当」是口语，而且不能指法律，与书面语句子不合。"}, "sentence_index": 0, "correct_answer": "国内法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中美两国签署了国内法。", "explanation": "这里应该用〈国际条约〉。两国之间达成的协议要说国际条约；国内法是一国自己制定的，不能由两国签署。"}, {"text": "国内法当场宣布了判决。", "explanation": "这里应该用〈法院〉。宣布判决的是法院，国内法是法律，不能宣布判决。"}, {"text": "国内法要经过各国批准。", "explanation": "这里应该用〈国际公约〉。需要各国批准的是国际公约；国内法由一国自己制定，不需要其他国家批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内法", "is_correct": true, "explanation": "正确：旅行前应了解目的地国家自己制定的法律。"}, {"text": "体温", "is_correct": false, "explanation": "语义：国家没有体温，「了解……的体温」说不通。"}, {"text": "叫声", "is_correct": false, "explanation": "搭配：「了解」一般不与「叫声」搭配，而且国家没有叫声，句意不通。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：国家不会留下脚印，句意不通。"}], "explanations": {"国内法": "正确：旅行前应了解目的地国家自己制定的法律。", "体温": "语义：国家没有体温，「了解……的体温」说不通。", "叫声": "搭配：「了解」一般不与「叫声」搭配，而且国家没有叫声，句意不通。", "脚印": "语义：国家不会留下脚印，句意不通。"}, "sentence_index": 6, "correct_answer": "国内法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "编剧写了一部国内法。", "explanation": "这里应该用〈剧本〉。编剧写的是剧本，国内法是一国自己定的法律，不能由编剧写成。"}, {"text": "导演拍了一部国内法。", "explanation": "这里应该用〈电影〉。导演拍的是电影，国内法是法律，不能拍成影片。"}, {"text": "乐团演奏了一部国内法。", "explanation": "这里应该用〈交响乐〉。乐团演奏的是交响乐，国内法不能演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们严格国内法。", "corrected_sentence": "我们严格执行国内法。", "error_description": "搭配错误：「严格」作动词时要接「执行」「要求」等，不能直接带「国内法」作宾语，应说「严格执行国内法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家刚刚制造了国内法。", "corrected_sentence": "这个国家刚刚颁布了国内法。", "error_description": "错误：动词搭配错了。颁布法律要用「颁布」，「制造」用于具体的产品，应说「颁布国内法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
